/// `App::new_for_test` に渡すテスト設定。
///
/// Phase C では実プロセスの `data_dir::init` を経由せず、`set_test_override` で
/// `TempDir` を差し込む。App 内の全 DB/インデクサ open はその data_dir を参照する。
struct AppTestConfig {
    /// テスト用データディレクトリ。`data_dir::set_test_override(Some(...))` に設定済みの
    /// パスを渡す。(呼び出し側の `TempDir` が App より長生きする必要あり)
    data_dir: std::path::PathBuf,
    /// 起動時に `settings.json` をこの内容で上書きしてから App::default を呼ぶ。
    /// None なら `Settings::load` が空ファイルから default 設定を作る。
    settings: Option<crate::settings::Settings>,
}

impl App {
    /// テスト用コンストラクタ。本番の `App::default` と同じ DB/indexer open 経路を
    /// 通すが、以下が異なる:
    ///
    /// 1. `config.data_dir` を `data_dir::set_test_override` 経由で強制する前提 (呼び出し側で)
    /// 2. `config.settings` があれば `settings.json` に書き出してから load する
    /// 3. 名前索引 supervisor の初期 spawn は行わない
    ///    (呼び出し側が `spawn_initial_name_index_supervisors()` を明示的に呼ぶ)
    /// 4. 初期サイズ / font / theme は設定しない (テスト側で Context を用意する想定)
    ///
    /// 注意: Tantivy / SQLite / notify-rs などの実スレッドは通常どおり起動するので、
    /// テスト終了時には `drop(app)` で正しく停止すること (IndexerManager::drop が
    /// supervisor を signal_stop→join で止める)。
    fn new_for_test(config: AppTestConfig) -> Self {
        // settings.json をあらかじめ書いておく (App::default 内の Settings::load が拾う)
        if let Some(settings) = &config.settings {
            std::fs::create_dir_all(&config.data_dir).ok();
            let json = serde_json::to_string_pretty(settings).expect("serialize settings");
            std::fs::write(config.data_dir.join("settings.json"), json)
                .expect("write settings.json");
        }
        // data_dir::get() はこの時点で config.data_dir を返さなければならない
        debug_assert_eq!(
            crate::data_dir::get(),
            config.data_dir,
            "data_dir::set_test_override(Some(config.data_dir)) を先に呼ぶこと"
        );
        let mut app = App::default();
        // 起動時 purge-retry worker はテストハーネスでは既定オフにする。本番の既定は true
        // (app.rs:9667) だが、テストで有効だと `App::update` を回す並列テストがこの worker を
        // spawn し、プロセスグローバルの data_dir override 経由で別テストの rating.db 等を
        // 触ってフレークする (undo_restores_zip_book_container_rating_key ほか、並列時のみ稀に
        // 失敗)。purge-retry の journal 再試行そのものを検証するテストだけ明示的に true へ
        // 戻して driver を回す契約にする (review-v2.3.0 追補19: テスト隔離)。
        app.delete_purge_retry_needed = false;
        // `spawn_initial_name_index_supervisors` はテスト側で必要なときだけ呼ぶ契約
        app
    }
}

fn scan_media_names(dir: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = scan_directory(dir)
        .all_media
        .into_iter()
        .filter_map(|(path, _, _, _)| {
            path.file_name()
                .and_then(|name| name.to_str())
                .map(str::to_owned)
        })
        .collect();
    names.sort();
    names
}

fn scan_folder_names(dir: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = scan_directory(dir)
        .folders
        .into_iter()
        .filter_map(|(item, _)| {
            if let GridItem::Folder(path) = item {
                path.file_name()
                    .and_then(|name| name.to_str())
                    .map(str::to_owned)
            } else {
                None
            }
        })
        .collect();
    names.sort();
    names
}

fn scan_convertible_archive_names(dir: &std::path::Path) -> Vec<String> {
    let mut names: Vec<String> = scan_directory(dir)
        .folders
        .into_iter()
        .filter_map(|(item, _)| match item {
            GridItem::ConvertibleArchive { path, .. } => path
                .file_name()
                .and_then(|name| name.to_str())
                .map(str::to_owned),
            _ => None,
        })
        .collect();
    names.sort();
    names
}

#[test]
fn scan_directory_never_lists_portable_metadata_bundle() {
    let temp = TempDir::new().unwrap();
    std::fs::create_dir(temp.path().join("visible")).unwrap();
    std::fs::create_dir(
        temp.path()
            .join(crate::fs_entry::PORTABLE_METADATA_BUNDLE_DIRNAME),
    )
    .unwrap();
    assert_eq!(scan_folder_names(temp.path()), vec!["visible"]);
    let shown_hidden = scan_directory_with_convertible_archives(temp.path(), true, true).unwrap();
    assert!(shown_hidden.folders.iter().all(|(item, _)| {
        item.container_path().map_or(true, |path| {
            !crate::fs_entry::is_internal_app_entry_name(path.file_name().unwrap_or_default())
        })
    }));
}

#[test]
fn comic_export_composition_applies_multiply_marker() {
    let base = egui::ColorImage::new([8, 8], vec![egui::Color32::WHITE; 64]);
    let mut bubble = comic_core::BubbleObject::default();
    bubble.shape = comic_core::BubbleShape::RoundRect {
        half_w: 2.0,
        half_h: 2.0,
        corner_px: 0.0,
    };
    bubble.fill = Some(comic_core::Rgba::new(255, 235, 59, 255));
    bubble.fill_opacity = 1.0;
    bubble.blend = comic_core::FillBlend::Multiply;
    bubble.outline.width_px = 0.0;
    bubble.text = comic_core::TextBlock::default();
    bubble.auto_size = false;
    let object = comic_core::AnnotationObject::new_bubble(1, (4.0, 4.0), bubble);

    let result = composite_comic_objects_for_export(
        &base,
        &[object],
        &comic_core::FontSet::new(),
        &comic_core::StampImages::new(),
    );

    assert_eq!(
        result.pixels[4 * 8 + 4].to_srgba_unmultiplied(),
        [255, 235, 59, 255]
    );
}

