#[test]
fn rar_folder_scan_keeps_all_volumes_visible_without_header_io() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/archives/rar-multipart-filename-regression");
    let standalone_names = [
        "○×△□ Vol.1.rar",
        "○×△□ Vol.2.rar",
        "○×△□ Vol.2a.rar",
        "○×△□ Vol.10.rar",
        "○×△□ Vol.10a.rar",
        "○×△□ Vol.123.rar",
        "○×△□ Vol.１.rar",
    ];
    for name in standalone_names {
        crate::rar_loader::inspect_for_direct_read(&root.join(name)).unwrap();
    }
    let mut expected: Vec<String> = standalone_names.into_iter().map(str::to_owned).collect();
    expected.sort();
    assert_eq!(scan_convertible_archive_names(&root), expected);

    let split_root = root.join("real-split-control");
    let first = split_root.join("real-split-control.part1.rar");
    let second = split_root.join("real-split-control.part2.rar");
    crate::rar_loader::inspect_for_direct_read(&first).unwrap();
    crate::rar_loader::inspect_for_direct_read(&second).unwrap();
    assert_eq!(
        scan_convertible_archive_names(&split_root),
        vec![
            "real-split-control.part1.rar".to_string(),
            "real-split-control.part2.rar".to_string(),
        ]
    );
}

#[cfg(windows)]
#[test]
fn scan_directory_lists_windows_directory_symlink_and_file_symlink() {
    let tmp = TempDir::new().expect("tempdir");
    let target_dir = tmp.path().join("target-dir");
    let link_dir = tmp.path().join("link-dir");
    std::fs::create_dir(&target_dir).unwrap();
    if std::os::windows::fs::symlink_dir(&target_dir, &link_dir).is_err() {
        return;
    }
    assert_eq!(
        scan_folder_names(tmp.path()),
        vec!["link-dir", "target-dir"]
    );

    let target_image = tmp.path().join("target.jpg");
    let link_image = tmp.path().join("link-image.jpg");
    std::fs::write(&target_image, b"image").unwrap();
    if std::os::windows::fs::symlink_file(&target_image, &link_image).is_err() {
        return;
    }

    assert_eq!(
        scan_media_names(tmp.path()),
        vec!["link-image.jpg", "target.jpg"]
    );
}

#[test]
fn scan_directory_hides_source_when_upscaled_derivative_sidecar_exists() {
    let tmp = TempDir::new().expect("tempdir");
    std::fs::write(tmp.path().join("movie.mp4"), b"source").unwrap();
    std::fs::write(tmp.path().join("movie.jpg"), b"cover").unwrap();
    std::fs::write(tmp.path().join("movie.miv.mkv"), b"upscaled").unwrap();
    std::fs::write(tmp.path().join("movie.miv.json"), b"{}").unwrap();

    assert_eq!(scan_media_names(tmp.path()), vec!["movie.miv.mkv"]);
}

