#[test]
fn startup_archive_open_auto_fullscreen_follows_setting_and_file_kind() {
    let tmp = TempDir::new().expect("tempdir");
    let zip = tmp.path().join("book.zip");
    let cbz = tmp.path().join("book.cbz");
    let pdf = tmp.path().join("scan.pdf");
    let rar = tmp.path().join("book.rar");
    let seven_z = tmp.path().join("book.7z");
    let image = tmp.path().join("cover.jpg");
    let folder = tmp.path().join("folder");
    for path in [&zip, &cbz, &pdf, &rar, &seven_z, &image] {
        std::fs::write(path, b"dummy").unwrap();
    }
    std::fs::create_dir(&folder).unwrap();

    let mut settings = crate::settings::Settings::default();
    settings.auto_fullscreen_zip_pdf = false;
    assert!(!startup_openable_should_auto_fullscreen(
        &settings,
        &zip,
        crate::folder_tree::OpenablePathKind::File,
    ));

    settings.auto_fullscreen_zip_pdf = true;
    for path in [&zip, &cbz, &pdf, &rar, &seven_z] {
        assert!(
            startup_openable_should_auto_fullscreen(
                &settings,
                path,
                crate::folder_tree::OpenablePathKind::File,
            ),
            "{} should inherit the explicit archive open fullscreen setting",
            path.display()
        );
    }
    assert!(!startup_openable_should_auto_fullscreen(
        &settings,
        &image,
        crate::folder_tree::OpenablePathKind::File,
    ));
    assert!(!startup_openable_should_auto_fullscreen(
        &settings,
        &folder,
        crate::folder_tree::OpenablePathKind::Directory,
    ));

    settings.auto_fullscreen_image_folders = true;
    assert!(
        startup_openable_should_auto_fullscreen(
            &settings,
            &folder,
            crate::folder_tree::OpenablePathKind::Directory,
        ),
        "image-only folder fullscreen is decided after directory load, but explicit folder opens should carry the intent"
    );

    settings.auto_fullscreen_zip_pdf = false;
    assert!(
        !startup_openable_should_auto_fullscreen(
            &settings,
            &folder,
            crate::folder_tree::OpenablePathKind::Directory,
        ),
        "folder option is subordinate to the main direct-page setting"
    );

    settings.detached_viewer_open_images_in_window = true;
    assert!(
        startup_openable_should_auto_fullscreen(
            &settings,
            &zip,
            crate::folder_tree::OpenablePathKind::File,
        ),
        "multi-window viewer mode forces ZIP/PDF direct open without mutating the saved full-feature preference"
    );
    assert!(
        startup_openable_should_auto_fullscreen(
            &settings,
            &folder,
            crate::folder_tree::OpenablePathKind::Directory,
        ),
        "multi-window viewer mode also enables the image-only folder option when that checkbox is on"
    );
}

