#[test]
fn details_order_drives_ai_prefetch_targets_and_indicator_directions() {
    let mut app = phase_c_support::setup_app();
    app.items = (0..6)
        .map(|idx| GridItem::Image(PathBuf::from(format!("C:/details/{idx}.jpg"))))
        .collect();
    app.visible_indices = (0..6).collect();
    app.settings.grid_view_mode = crate::settings::GridViewMode::Details;
    app.details_order = vec![5, 4, 3, 2, 1, 0];
    app.settings.ai_upscale_prefetch_forward = 2;
    app.settings.ai_upscale_prefetch_back = 1;

    let targets = app.ai_prefetch_targets(4);
    let targets_with_positions = targets
        .iter()
        .map(|&idx| {
            (
                app.current_grid_order()
                    .iter()
                    .position(|&candidate| candidate == idx)
                    .unwrap(),
                idx,
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(targets_with_positions, vec![(2, 3), (0, 5), (3, 2)]);

    let indicator = app
        .final_ai_prefetch_indicator(4)
        .expect("missing prefetch pages should keep the indicator visible");
    assert_eq!(indicator.behind, vec![FsPrefetchPageState::Missing]);
    assert_eq!(
        indicator.ahead,
        vec![FsPrefetchPageState::Missing, FsPrefetchPageState::Missing]
    );
}

#[test]
fn fs_prefetch_indicator_keeps_nearest_dots_and_summarizes_only_nonzero_far_states() {
    use FsPrefetchPageState::{Active, Missing, Ready};

    // 先読み枚数の上限は前後とも 10 枚。近い側だけを点で残し、遠方は状態別の個数へ畳む。
    let pages = [
        (7, Ready),
        (8, Missing),
        (9, Ready),
        (10, Missing),
        (11, Active),
        (12, Ready),
        (14, Ready),
        (15, Active),
        (16, Missing),
        (17, Ready),
        (18, Active),
        (19, Active),
        (20, Missing),
    ];
    let indicator = build_fs_prefetch_indicator(13, false, pages)
        .expect("unfinished targets should be visible");

    let behind = indicator.behind_display();
    assert_eq!(
        behind.dots,
        vec![Ready, Missing, Active, Ready],
        "behind は現在に近い末尾 4 ページを点のまま残す"
    );
    assert_eq!(
        behind.far_counts,
        vec![
            FsPrefetchStateCount {
                state: Ready,
                count: 1,
            },
            FsPrefetchStateCount {
                state: Missing,
                count: 1,
            },
        ],
        "遠方に 0 件の active は個数表示へ出さない"
    );

    let ahead = indicator.ahead_display();
    assert_eq!(
        ahead.dots,
        vec![Ready, Active, Missing, Ready],
        "ahead は現在に近い先頭 4 ページを点のまま残す"
    );
    assert_eq!(
        ahead.far_counts,
        vec![
            FsPrefetchStateCount {
                state: Active,
                count: 2,
            },
            FsPrefetchStateCount {
                state: Missing,
                count: 1,
            },
        ],
        "遠方に 0 件の ready は個数表示へ出さない"
    );

    assert_eq!(
        indicator.tooltip_text(),
        "先読み: 取得済み 5 / 取得中 4 / 未取得 4",
        "ホバー表示は点にした分と畳んだ分の合計を数える"
    );
}

