#[test]
fn final_effect_prefetch_admission_reports_each_condition() {
    let empty = std::collections::HashSet::new();
    assert_eq!(
        should_prefetch_final_effect(true, &empty, 42, false, 100, Some(100)),
        FinalEffectPrefetchAdmission::Allow
    );

    let keep_set = std::collections::HashSet::from([2]);
    assert_eq!(
        should_prefetch_final_effect(false, &keep_set, 2, false, 99, Some(100)),
        FinalEffectPrefetchAdmission::Allow
    );
    assert_eq!(
        should_prefetch_final_effect(false, &keep_set, 3, true, 99, Some(100)),
        FinalEffectPrefetchAdmission::NotInKeepSet
    );
    assert_eq!(
        should_prefetch_final_effect(false, &keep_set, 2, false, 100, Some(100)),
        FinalEffectPrefetchAdmission::OverLowWatermark
    );
}

#[test]
fn final_effect_prepare_band_bypasses_low_but_not_keep_set() {
    let keep_set = std::collections::HashSet::from([2]);
    assert_eq!(
        should_prefetch_final_effect(false, &keep_set, 2, true, 100, Some(100)),
        FinalEffectPrefetchAdmission::Allow
    );
    assert_eq!(
        should_prefetch_final_effect(false, &keep_set, 3, true, 100, Some(100)),
        FinalEffectPrefetchAdmission::NotInKeepSet
    );
    assert_eq!(
        should_prefetch_final_effect(false, &keep_set, 2, false, usize::MAX, None),
        FinalEffectPrefetchAdmission::Allow,
        "unlimited mode must disable the LOW admission gate"
    );
}

#[test]
fn next_video_search_uses_display_order_and_skips_non_video_items() {
    use crate::grid_item::GridItem;

    let items = vec![
        GridItem::Video(PathBuf::from("c:/a.mp4")),
        GridItem::Image(PathBuf::from("c:/a.jpg")),
        GridItem::ZipImage {
            zip_path: PathBuf::from("c:/book.zip"),
            entry_name: "p01.jpg".to_string(),
        },
        GridItem::PdfPage {
            pdf_path: PathBuf::from("c:/scan.pdf"),
            page_num: 0,
            content_type: None,
        },
        GridItem::Video(PathBuf::from("c:/b.mp4")),
        GridItem::Folder(PathBuf::from("c:/sub")),
    ];
    let visible_indices = vec![0, 1, 2, 3, 4, 5];

    assert_eq!(
        App::find_next_video_in_display_order_from(&items, &visible_indices, 0, false),
        Some(4),
        "画像 / ZIP 内画像 / PDF ページ / フォルダを飛ばして次の動画を選ぶ"
    );
    assert_eq!(
        App::find_next_video_in_display_order_from(&items, &visible_indices, 4, false),
        None,
        "末尾側に動画が無ければ Continuous は停止する"
    );
    assert_eq!(
        App::find_next_video_in_display_order_from(&items, &visible_indices, 4, true),
        Some(0),
        "ContinuousLoop は display_order の先頭側へ wrap する"
    );
    assert_eq!(
        App::find_next_video_in_display_order_from(&items, &[4, 3, 2, 0], 4, true),
        Some(0),
        "詳細ソート等で並び替わった表示順を使って wrap する"
    );

    let filtered = vec![4];
    assert_eq!(
        App::find_next_video_in_display_order_from(&items, &filtered, 4, true),
        Some(4),
        "表示リストに動画 1 本だけなら同じ動画を繰り返す"
    );
    assert_eq!(
        App::find_next_video_in_display_order_from(&items, &[1, 2, 3], 4, true),
        None,
        "現在動画が表示リスト外で、wrap しても動画候補が無ければ None"
    );
}

#[test]
fn next_audio_search_uses_display_order_and_skips_non_audio_items() {
    use crate::grid_item::GridItem;

    // 音声を挟んだ混在リスト。連続再生は display 順で次の Audio だけを拾う。
    let items = vec![
        GridItem::Audio(PathBuf::from("c:/1.flac")),
        GridItem::Image(PathBuf::from("c:/a.jpg")),
        GridItem::Video(PathBuf::from("c:/b.mp4")),
        GridItem::Audio(PathBuf::from("c:/2.m4a")),
        GridItem::Folder(PathBuf::from("c:/sub")),
    ];
    let order = vec![0, 1, 2, 3, 4];

    assert_eq!(
        App::find_next_audio_in_display_order_from(&items, &order, 0, false),
        Some(3),
        "画像 / 動画 / フォルダを飛ばして次の音声を選ぶ"
    );
    assert_eq!(
        App::find_next_audio_in_display_order_from(&items, &order, 3, false),
        None,
        "末尾側に音声が無ければ連続再生は停止する"
    );
    assert_eq!(
        App::find_next_audio_in_display_order_from(&items, &order, 3, true),
        Some(0),
        "連続 + ループは display_order の先頭側へ wrap する"
    );
    assert_eq!(
        App::find_next_audio_in_display_order_from(&items, &[0], 0, true),
        Some(0),
        "表示リストに音声 1 本だけなら同じ音声を繰り返す"
    );
    assert_eq!(
        App::find_next_audio_in_display_order_from(&items, &[1, 2, 4], 0, true),
        None,
        "現在音声が表示リスト外で、wrap しても音声候補が無ければ None"
    );
}

