    #[test]
    fn quick_folder_histories_are_isolated_per_slot() {
        let mut app = setup_app();
        let a = PathBuf::from(r"C:\miv-test\a");
        let a_child = PathBuf::from(r"C:\miv-test\a\child");
        let b = PathBuf::from(r"C:\miv-test\b");
        let b_child = PathBuf::from(r"C:\miv-test\b\child");

        app.set_quick_folder_slot_target(QuickFolderSlotId::A, a.clone());
        app.set_quick_folder_slot_target(QuickFolderSlotId::B, b.clone());

        app.active_quick_folder_slot = Some(QuickFolderSlotId::A);
        app.current_folder = Some(a.clone());
        app.record_folder_nav_transition(&a_child);
        app.current_folder = Some(a_child.clone());

        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::A.index()]
                .history
                .back_stack,
            vec![a.clone()]
        );
        assert!(
            app.quick_folder_workspaces[QuickFolderSlotId::B.index()]
                .history
                .back_stack
                .is_empty()
        );
        assert!(app.folder_nav_back_stack.is_empty());

        assert_eq!(
            app.activate_quick_folder_slot(QuickFolderSlotId::B),
            QuickFolderSwitchTarget::Folder(b.clone())
        );
        app.record_folder_nav_transition(&b);
        app.current_folder = Some(b.clone());
        app.record_folder_nav_transition(&b_child);
        app.current_folder = Some(b_child);

        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::A.index()]
                .history
                .back_stack,
            vec![a.clone()]
        );
        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::B.index()]
                .history
                .back_stack,
            vec![b.clone()]
        );

        app.active_quick_folder_slot = Some(QuickFolderSlotId::A);
        app.current_folder = Some(a_child.clone());
        assert_eq!(app.navigate_folder_history_back(), Some(a.clone()));
        assert!(
            app.quick_folder_workspaces[QuickFolderSlotId::B.index()]
                .history
                .forward_stack
                .is_empty()
        );
        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::A.index()]
                .history
                .forward_stack,
            vec![a_child]
        );
    }

    #[test]
    fn drive_current_dirs_are_isolated_per_quick_folder_slot() {
        let mut app = setup_app();
        let a_d = PathBuf::from(r"D:\miv-test\a");
        let b_d = PathBuf::from(r"D:\miv-test\b");
        let a_e = PathBuf::from(r"E:\miv-test\a");
        let d_key = drive_current_key_for_letter('d').unwrap();
        let e_key = drive_current_key_for_letter('E').unwrap();

        app.active_quick_folder_slot = Some(QuickFolderSlotId::A);
        app.update_active_quick_folder_target(&a_d);
        app.update_active_quick_folder_target(&a_e);

        app.active_quick_folder_slot = Some(QuickFolderSlotId::B);
        app.update_active_quick_folder_target(&b_d);

        assert_eq!(app.active_drive_current_dir('D'), Some(b_d.clone()));
        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::A.index()]
                .drive_current_dirs
                .get(&d_key),
            Some(&a_d)
        );
        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::A.index()]
                .drive_current_dirs
                .get(&e_key),
            Some(&a_e)
        );
        assert_eq!(
            app.quick_folder_workspaces[QuickFolderSlotId::B.index()]
                .drive_current_dirs
                .get(&d_key),
            Some(&b_d)
        );
        assert_eq!(
            app.settings.quick_folder_drive_current_dirs[QuickFolderSlotId::A.index()].get(&d_key),
            Some(&a_d)
        );
        assert_eq!(
            app.settings.quick_folder_drive_current_dirs[QuickFolderSlotId::B.index()].get(&d_key),
            Some(&b_d)
        );

        app.clear_quick_folder_slot(QuickFolderSlotId::B);
        assert!(
            app.quick_folder_workspaces[QuickFolderSlotId::B.index()]
                .drive_current_dirs
                .is_empty()
        );
        assert!(
            app.settings.quick_folder_drive_current_dirs[QuickFolderSlotId::B.index()].is_empty()
        );
    }

