    #[test]
    fn facet_edit_rollup_matches_converted_archive_cache_zip_keys() {
        use crate::archive_converter::ArchiveFormat;
        use crate::grid_item::{GridItem, ThumbnailState};
        use crate::settings::FacetEditFlag;

        let mut app = setup_app();
        let src = std::path::PathBuf::from(r"C:\books\book.rar");
        let cache = std::path::PathBuf::from(r"C:\cache\book.zip");
        app.items = vec![GridItem::ConvertibleArchive {
            path: src.clone(),
            format: ArchiveFormat::Rar,
        }];
        app.thumbnails = vec![ThumbnailState::Pending; app.items.len()];
        app.image_metas = vec![Some((1, 2)); app.items.len()];

        let key = crate::adjustment_db::zip_entry_key(&cache, "p001.jpg");
        app.adjusted_page_keys.insert(key.clone());
        app.settings
            .facet_filter
            .edits
            .insert(FacetEditFlag::Adjustment);
        app.rebuild_visible_indices();
        assert!(
            app.visible_indices.is_empty(),
            "cache ZIP map が無い間は従来どおり元アーカイブ root だけを見る"
        );

        app.converted_archive_cache_paths.insert(
            crate::path_key::normalize_keep_drive(&src),
            crate::app::ConvertedArchiveSourceState::CachedZip(cache.clone()),
        );
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "変換済みアーカイブ親セルは cache ZIP 側のページ補正も拾う"
        );

        app.settings.facet_filter.edits.clear();
        app.adjusted_page_keys.clear();
        app.mask_page_keys.insert(key.clone());
        app.settings.facet_filter.edits.insert(FacetEditFlag::Mask);
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "消しゴムマスクも同じ cache ZIP ロールアップで拾う"
        );

        app.settings.facet_filter.edits.clear();
        app.mask_page_keys.clear();
        app.local_adjust_page_keys.insert(key.clone());
        app.settings
            .facet_filter
            .edits
            .insert(FacetEditFlag::LocalAdjustment);
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "補正レイヤーも同じ cache ZIP ロールアップで拾う"
        );

        app.settings.facet_filter.edits.clear();
        app.local_adjust_page_keys.clear();
        app.rotation_page_keys.insert(key);
        app.settings
            .facet_filter
            .edits
            .insert(FacetEditFlag::Rotation);
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "非破壊回転も同じ cache ZIP ロールアップで拾う"
        );
    }

    #[test]
    fn converted_archive_cache_path_poll_rebuilds_rollup_edit_filter() {
        use crate::archive_converter::ArchiveFormat;
        use crate::grid_item::GridItem;
        use crate::settings::FacetEditFlag;
        use std::io::Write;

        let mut app = setup_app();
        let src = app.tmp.path().join("book.7z");
        let cached = app.tmp.path().join("book.zip");
        std::fs::File::create(&src)
            .unwrap()
            .write_all(b"archive")
            .unwrap();
        std::fs::File::create(&cached)
            .unwrap()
            .write_all(b"PK\x03\x04")
            .unwrap();

        let src_meta = std::fs::metadata(&src).unwrap();
        let src_mtime = crate::ui_helpers::mtime_secs(&src_meta);
        let src_size = src_meta.len() as i64;
        let cached_size = std::fs::metadata(&cached).unwrap().len() as i64;
        app.archive_cache_db
            .as_ref()
            .unwrap()
            .record(
                &src,
                src_mtime,
                src_size,
                ArchiveFormat::SevenZ,
                &cached,
                cached_size,
                1,
                false,
            )
            .unwrap();
        app.adjusted_page_keys
            .insert(crate::adjustment_db::zip_entry_key(&cached, "p001.jpg"));
        app.settings
            .facet_filter
            .edits
            .insert(FacetEditFlag::Adjustment);

        app.install_new_items(
            vec![GridItem::ConvertibleArchive {
                path: src,
                format: ArchiveFormat::SevenZ,
            }],
            vec![Some((src_mtime, src_size))],
        );
        app.rebuild_visible_indices();
        assert!(
            app.visible_indices.is_empty(),
            "worker 完了前は cache ZIP 側の補正キーをまだ拾わない"
        );
        app.start_converted_archive_cache_paths_refresh(
            &std::collections::HashSet::from([0]),
            (0, 1),
            (0, 1),
        );

        let ctx = egui::Context::default();
        for _ in 0..50 {
            app.poll_converted_archive_cache_paths(&ctx);
            if app.converted_archive_cache_paths_pending.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }

        assert!(app.converted_archive_cache_paths_pending.is_none());
        assert_eq!(
            app.visible_indices,
            vec![0],
            "cache ZIP map 完了時に状態フィルタの表示集合も更新される"
        );
    }

    #[test]
    fn grid_edit_badges_roll_up_only_to_one_visible_parent() {
        use crate::grid_item::{GridItem, ThumbnailState};

        let mut app = setup_app();
        let root = std::path::PathBuf::from("c:/pics");
        let image = root.join("edited.jpg");
        let direct_folder = root.join("direct");
        let deep_folder = root.join("deep");
        let archive_parent = root.join("archive-parent");
        let zip = root.join("book.zip");
        let outer_zip = root.join("outer.zip");

        app.current_folder = Some(root);
        app.items = vec![
            GridItem::Image(image.clone()),
            GridItem::Folder(direct_folder.clone()),
            GridItem::Folder(deep_folder.clone()),
            GridItem::Folder(archive_parent.clone()),
            GridItem::ZipFile(zip.clone()),
            GridItem::ZipDir {
                zip_path: outer_zip.clone(),
                dir_prefix: "chapter/".to_string(),
                is_archive: false,
                representative: None,
            },
            GridItem::ZipDir {
                zip_path: outer_zip.clone(),
                dir_prefix: "deep/".to_string(),
                is_archive: false,
                representative: None,
            },
            GridItem::ZipDir {
                zip_path: outer_zip.clone(),
                dir_prefix: "books/inner.zip/".to_string(),
                is_archive: true,
                representative: None,
            },
        ];
        app.thumbnails = vec![ThumbnailState::Pending; app.items.len()];
        app.image_metas = vec![None; app.items.len()];

        app.adjusted_page_keys
            .insert(crate::adjustment_db::normalize_path(&image));
        app.mask_page_keys
            .insert(crate::adjustment_db::normalize_path(
                &direct_folder.join("p001.jpg"),
            ));
        app.conceal_page_keys
            .insert(crate::adjustment_db::normalize_path(
                &deep_folder.join("child").join("p001.jpg"),
            ));
        app.comic_page_keys
            .insert(crate::adjustment_db::zip_entry_key(
                &archive_parent.join("book.zip"),
                "p001.jpg",
            ));
        app.adjusted_page_keys
            .insert(crate::adjustment_db::zip_entry_key(&zip, "p001.jpg"));
        app.local_adjust_page_keys
            .insert(crate::adjustment_db::zip_entry_key(
                &outer_zip,
                "chapter/p001.jpg",
            ));
        app.local_adjust_page_keys
            .insert(crate::adjustment_db::zip_entry_key(
                &outer_zip,
                "deep/child/p001.jpg",
            ));
        app.mask_page_keys
            .insert(crate::adjustment_db::zip_entry_key(
                &outer_zip,
                "books/inner.zip/sub/p001.jpg",
            ));

        assert!(app.grid_edit_badges(0).page_override);
        assert!(
            app.grid_edit_badges(1).mask,
            "フォルダ直下の編集済みページは、そのフォルダセルへ出す"
        );
        assert!(
            !app.grid_edit_badges(2).conceal,
            "孫フォルダ配下の編集はサムネバッジでは親の親へ伝播しない"
        );
        assert!(
            !app.grid_edit_badges(3).comic,
            "直下書庫内ページは書庫セル側で示し、フォルダセルへは伝播しない"
        );
        assert!(app.grid_edit_badges(4).page_override);
        assert!(
            app.grid_edit_badges(5).local_adjust,
            "通常の ZIP 内仮想フォルダは直下ページだけを示す"
        );
        assert!(
            !app.grid_edit_badges(6).local_adjust,
            "通常の ZIP 内仮想フォルダは下位フォルダへは伝播しない"
        );
        assert!(
            app.grid_edit_badges(7).mask,
            "内側アーカイブとして表示される ZipDir はその本全体を示す"
        );
    }

    #[test]
    fn opening_zip_under_facet_filter_suppresses_then_restores_parent_filter() {
        use crate::grid_item::{GridItem, ThumbnailState};
        use crate::settings::FacetItemKind;

        let mut app = setup_app();
        let parent = std::path::PathBuf::from(r"C:\books");
        let zip_path = parent.join("vol1.zip");

        app.current_folder = Some(parent.clone());
        app.items = vec![GridItem::ZipFile(zip_path.clone())];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.image_metas = vec![None];
        app.settings.facet_filter.kinds.insert(FacetItemKind::Zip);
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "ZIP 絞り込みで親 ZIP が見える"
        );

        app.maybe_suppress_facet_filter_for_opened_container(0);
        assert!(
            !app.facet_filter_active(),
            "ZIP を開いた直後は親の種類フィルタが退避される"
        );
        assert!(app.facet_filter_suppressed());

        app.current_folder = Some(zip_path.clone());
        app.items = vec![GridItem::ZipImage {
            zip_path: zip_path.clone(),
            entry_name: "p001.jpg".to_owned(),
        }];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.image_metas = vec![None];
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "親の ZIP 種類フィルタで中身の通常画像が消えない"
        );

        app.settings.facet_filter.exts.insert("jpg".to_owned());
        app.rebuild_visible_indices();
        assert_eq!(
            app.visible_indices,
            vec![0],
            "退避中でも内側の拡張子フィルタを設定できる"
        );

        app.current_folder = Some(parent);
        app.items = vec![GridItem::ZipFile(zip_path)];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.image_metas = vec![None];
        app.rebuild_visible_indices();

        assert!(!app.facet_filter_suppressed());
        assert!(
            app.settings
                .facet_filter
                .kinds
                .contains(&FacetItemKind::Zip),
            "親へ戻ると親階層の ZIP フィルタが復元される"
        );
        assert!(
            app.settings.facet_filter.exts.is_empty(),
            "内側で設定したフィルタは親へ持ち越さない"
        );
        assert_eq!(app.visible_indices, vec![0]);
    }

    fn run_grid_key(app: &mut super::App, modifiers: egui::Modifiers, key: egui::Key) {
        let ctx = egui::Context::default();
        ctx.begin_pass(egui::RawInput {
            modifiers,
            events: vec![egui::Event::Key {
                key,
                physical_key: None,
                pressed: true,
                repeat: false,
                modifiers,
            }],
            ..Default::default()
        });
        let _ = app.handle_keyboard(&ctx);
        let _ = ctx.end_pass();
    }

    /// 2026-05 ユーザー報告: ★フィルタでサムネイルが 0 件になった状態でも、
    /// Shift+F6 は current_folder のコンテナ★を解除できること。
    #[test]
    fn shift_f6_clears_current_folder_rating_when_visible_indices_empty() {
        use crate::grid_item::{GridItem, ThumbnailState};
        let mut app = setup_app();
        let folder = std::path::PathBuf::from("c:/pics");
        let image = folder.join("a.jpg");
        let key = crate::adjustment_db::normalize_path(&folder);

        app.current_folder = Some(folder);
        app.items.push(GridItem::Image(image));
        app.thumbnails.push(ThumbnailState::Pending);
        app.rating_db
            .as_ref()
            .expect("rating_db")
            .set(&key, 4)
            .expect("seed current folder rating");

        let mut rf = [false; 6];
        rf[5] = true;
        app.settings.rating_filter = rf;
        app.rebuild_visible_indices();
        assert!(
            app.visible_indices.is_empty(),
            "前提: フィルタ後のサムネイルは 0 件"
        );

        run_grid_key(&mut app, egui::Modifiers::SHIFT, egui::Key::F6);

        assert_eq!(
            app.rating_db.as_ref().unwrap().get(&key),
            0,
            "Shift+F6 は可視アイテムがなくても current_folder の★を解除する"
        );
        assert_eq!(app.current_folder_rating_cache, Some(0));
    }

