#[cfg(windows)]
fn begin_detached_bookmark_media_test(
    app: &mut phase_c_support::AppTestEnv,
    is_audio: bool,
) -> (PathBuf, PathBuf, PathBuf) {
    let media_dir = app
        .tmp
        .path()
        .join(if is_audio { "audio" } else { "video" });
    std::fs::create_dir_all(&media_dir).expect("create media dir");
    let extension = if is_audio { "flac" } else { "mp4" };
    let target = media_dir.join(format!("target.{extension}"));
    let other = media_dir.join(format!("other.{extension}"));
    std::fs::write(&target, []).expect("create target media");
    std::fs::write(&other, []).expect("create other media");

    app.settings.fullfeature_media_window = true;
    app.settings.detached_viewer_open_images_in_window = false;
    app.settings.vst3_enabled = false;
    app.current_folder = Some(super::bookmark_view_synthetic_path());
    app.items = vec![if is_audio {
        GridItem::Audio(target.clone())
    } else {
        GridItem::Video(target.clone())
    }];
    app.image_metas = vec![None];
    app.visible_indices = vec![0];
    app.selected = Some(0);
    app.items_are_bookmark_view = true;
    app.bookmark_view_state = Some(super::BookmarkViewState::Opening {
        target: crate::bookmark_browser::BookmarkViewReturnTarget::Media(target.clone()),
        grid: super::BookmarkViewReturnGridState {
            row_keys: vec![(0, 7)],
            selected_key: Some((0, 7)),
            opened_key: (0, 7),
            scroll_offset_y: 240.0,
        },
    });
    app.bookmark_open_pending = Some(crate::bookmark_browser::PendingBookmarkOpen::Media(
        crate::bookmark_browser::PendingMediaOpen {
            request_id: crate::bookmark_browser::BookmarkOpenRequestId(1),
            path: target.clone(),
            pts_secs: 42.0,
            started_at: std::time::Instant::now(),
            last_wait: None,
        },
    ));
    app.tags_cache.insert(
        crate::tags_db::item_key_for_path(&target),
        vec!["#detached-cache-test".to_string()],
    );
    app.metadata_cache
        .insert("main-grid-meta".to_string(), None);
    app.exif_cache.insert("main-grid-meta".to_string(), None);
    app.xmp_cache.insert("main-grid-meta".to_string(), None);
    app.xmp_panorama_info
        .insert("main-grid-meta".to_string(), None);
    app.video_thumb_overrides.insert(
        "main-grid-video".to_string(),
        PathBuf::from(r"C:\main-grid\cover.jpg"),
    );
    app.folder_pin_map.insert(
        "main-grid-folder".to_string(),
        crate::folder_thumb_pins::FolderPinSource::File {
            rel: "cover.jpg".to_string(),
            kind: crate::folder_thumb_pins::FileKind::Image,
        },
    );
    app.converted_archive_cache_paths.insert(
        "main-grid-archive".to_string(),
        crate::app::ConvertedArchiveSourceState::CachedZip(PathBuf::from(
            r"C:\main-grid\cached.zip",
        )),
    );
    app.current_color_cache_map = Some(std::sync::Arc::new(std::sync::RwLock::new(
        std::collections::HashMap::from([(
            "main-grid-color".to_string(),
            crate::catalog::CacheEntry {
                mtime: 1,
                file_size: 2,
                jpeg_data: Vec::new(),
                source_dims: None,
                layout_dims: None,
            },
        )]),
    )));
    app.current_folder_last_mtime = Some(std::time::SystemTime::UNIX_EPOCH);
    app.current_folder_signature = Some(0xCAFE);

    assert!(app.open_bookmark_media_in_detached_context(
        &egui::Context::default(),
        &target,
        media_dir.clone(),
        true,
    ));
    (media_dir, target, other)
}

#[cfg(windows)]
#[test]
fn detached_bookmark_media_keeps_main_grid_and_closes_in_one_request() {
    for is_audio in [false, true] {
        let mut app = phase_c_support::setup_app();
        let (media_dir, target, _) = begin_detached_bookmark_media_test(&mut app, is_audio);

        assert!(app.items_are_bookmark_view);
        assert_eq!(
            app.current_folder.as_deref(),
            Some(super::bookmark_view_synthetic_path().as_path())
        );
        assert!(matches!(
            app.bookmark_view_state,
            Some(super::BookmarkViewState::Opening { .. })
        ));
        assert!(app.bookmark_open_pending.is_none());
        assert_eq!(app.cell_tag_list(0), ["#detached-cache-test".to_string()]);
        assert!(app.metadata_cache.contains_key("main-grid-meta"));
        assert!(app.exif_cache.contains_key("main-grid-meta"));
        assert!(app.xmp_cache.contains_key("main-grid-meta"));
        assert!(app.xmp_panorama_info.contains_key("main-grid-meta"));
        assert!(app.video_thumb_overrides.contains_key("main-grid-video"));
        assert!(app.folder_pin_map.contains_key("main-grid-folder"));
        assert!(
            app.converted_archive_cache_paths
                .contains_key("main-grid-archive")
        );
        assert!(app.current_color_cache_map.as_ref().is_some_and(|cache| {
            cache
                .read()
                .is_ok_and(|entries| entries.contains_key("main-grid-color"))
        }));
        assert_eq!(
            app.current_folder_last_mtime,
            Some(std::time::SystemTime::UNIX_EPOCH)
        );
        assert_eq!(app.current_folder_signature, Some(0xCAFE));
        app.with_active_viewer_context(|active| {
            assert!(
                !active
                    .tags_cache
                    .values()
                    .flatten()
                    .any(|tag| tag == "#detached-cache-test")
            );
            assert_eq!(active.current_folder.as_deref(), Some(media_dir.as_path()));
            assert!(matches!(
                active.bookmark_view_state,
                Some(super::BookmarkViewState::Detached { .. })
            ));
            assert_eq!(
                active
                    .fullscreen_idx
                    .and_then(|idx| active.items.get(idx))
                    .and_then(|item| match item {
                        GridItem::Video(path) | GridItem::Audio(path) => Some(path.as_path()),
                        _ => None,
                    }),
                Some(target.as_path())
            );
        })
        .expect("media must be owned by detached context from the start");

        app.with_active_viewer_context(|detached| {
            detached.handle_fullscreen_close_request();
            assert_eq!(detached.fullscreen_idx, None);
            assert!(matches!(
                detached.bookmark_view_state,
                Some(super::BookmarkViewState::Detached { .. })
            ));
        })
        .expect("active detached context");
        assert!(
            app.update_active_viewer_context(&egui::Context::default(), None)
                .updated
        );

        assert!(app.active_viewer_context_id().is_none());
        assert!(app.items_are_bookmark_view);
        assert_eq!(
            app.current_folder.as_deref(),
            Some(super::bookmark_view_synthetic_path().as_path())
        );
        assert!(matches!(
            app.bookmark_view_state,
            Some(super::BookmarkViewState::Restoring { .. })
        ));
        assert!(app.bookmark_browser_pending.is_some());
    }
}

#[cfg(windows)]
#[test]
fn detached_bookmark_media_navigation_returns_main_to_real_folder() {
    let mut app = phase_c_support::setup_app();
    let (media_dir, _, other) = begin_detached_bookmark_media_test(&mut app, false);

    app.with_active_viewer_context(|detached| {
        let other_idx = detached
            .items
            .iter()
            .position(|item| {
                matches!(item, GridItem::Video(path) if crate::path_key::eq_keep_drive(path, &other))
            })
            .expect("other video in real folder context");
        detached.fullscreen_idx = Some(other_idx);
        detached.selected = Some(other_idx);
        detached.handle_fullscreen_close_request();
        assert_eq!(detached.fullscreen_idx, None);
        assert!(detached.bookmark_view_state.is_none());
    })
    .expect("active detached context");
    assert!(
        app.update_active_viewer_context(&egui::Context::default(), None)
            .updated
    );

    assert!(app.active_viewer_context_id().is_none());
    assert!(!app.items_are_bookmark_view);
    assert_eq!(app.current_folder.as_deref(), Some(media_dir.as_path()));
    assert_eq!(
        app.selected
            .and_then(|idx| app.items.get(idx))
            .and_then(|item| match item {
                GridItem::Video(path) => Some(path.as_path()),
                _ => None,
            }),
        Some(other.as_path())
    );
    assert!(app.bookmark_view_state.is_none());
}

