    #[test]
    fn unmounted_page_adjustment_clear_queues_pinned_thumbnail_refresh() {
        let mut app = setup_app();
        let path = PathBuf::from("C:/elsewhere/pinned-remote-page.jpg");
        let target = PageAdjustmentTarget {
            page_key: crate::adjustment_db::normalize_path(&path),
            location_path: path.parent().map(PathBuf::from),
            sidecar_coords: None,
            compiled_book: false,
            idx_hint: crate::app::PageIndexHint::Unresolved,
        };
        assert!(app.page_adjustment_indices(&target).is_empty());
        let mut params = AdjustParams::default();
        params.contrast = 19.0;
        let _ = app.set_page_params_for_target(&target, params);
        app.pinned_adjustment_refresh_keys.clear();

        let _ = app.clear_page_params_for_target(&target);

        assert!(
            app.pinned_adjustment_refresh_keys
                .contains(&target.page_key)
        );
    }

    #[test]
    fn apply_conceal_slot_to_selection_saves_pages_and_clears_caches() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let idx_a = push_image(&mut app, "C:/pics/a.jpg");
        let idx_b = push_image(&mut app, "C:/pics/b.jpg");
        app.visible_indices = vec![idx_a, idx_b];
        app.checked.insert(idx_a);
        app.checked.insert(idx_b);
        let mask = mask_2x2();
        app.conceal_db
            .as_ref()
            .unwrap()
            .set_slot(1, &mask, &[], 2, 2)
            .unwrap();
        insert_stale_conceal_cache(&mut app, &ctx, idx_a, "bulk_conceal_stale_a");
        insert_stale_conceal_cache(&mut app, &ctx, idx_b, "bulk_conceal_stale_b");
        app.conceal_base_cache.insert(
            idx_a,
            std::sync::Arc::new(egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK])),
        );

        app.apply_conceal_slot_to_selection(1);

        for idx in [idx_a, idx_b] {
            assert!(
                app.conceal_pages.contains(&idx),
                "conceal badge set should include applied page {idx}"
            );
            assert!(
                !app.conceal_cache.contains_key(&idx),
                "stale conceal render cache must be invalidated for page {idx}"
            );
            let key = app.page_path_key(idx).unwrap();
            let (saved_mask, saved_shapes) = app
                .conceal_db
                .as_ref()
                .unwrap()
                .get_full(&key, 2, 2)
                .expect("conceal slot should be saved to page db");
            assert_eq!(saved_mask, mask);
            assert!(saved_shapes.is_empty());
        }
        assert!(!app.conceal_base_cache.contains_key(&idx_a));
        assert!(app.checked.is_empty());
        assert_eq!(toast_text(&app), "[隠蔽スロット1を2枚に適用]");
    }

    #[test]
    fn apply_conceal_slot_in_viewing_mode_saves_current_page() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let idx = push_image(&mut app, "C:/pics/current.jpg");
        app.fullscreen_idx = Some(idx);
        let mask = mask_2x2();
        app.conceal_db
            .as_ref()
            .unwrap()
            .set_slot(2, &mask, &[], 2, 2)
            .unwrap();
        insert_stale_conceal_cache(&mut app, &ctx, idx, "view_conceal_stale");
        app.conceal_base_cache.insert(
            idx,
            std::sync::Arc::new(egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE])),
        );

        app.apply_conceal_slot_in_viewing_mode(2);

        assert!(app.conceal_pages.contains(&idx));
        assert!(!app.conceal_cache.contains_key(&idx));
        assert!(!app.conceal_base_cache.contains_key(&idx));
        let key = app.page_path_key(idx).unwrap();
        let (saved_mask, saved_shapes) = app
            .conceal_db
            .as_ref()
            .unwrap()
            .get_full(&key, 2, 2)
            .expect("conceal slot should be saved to current page");
        assert_eq!(saved_mask, mask);
        assert!(saved_shapes.is_empty());
        assert_eq!(toast_text(&app), "[隠蔽スロット2適用]");
    }

    /// 正本 DB が受け取れなかった編集を、サイドカーへ「保存済み」として写さない。
    ///
    /// 写すと、次回起動時のサイドカー import が「中央 DB に行がある」を理由に skip し
    /// (中央が authoritative)、古い正本が勝って利用者からは編集が消えたように見える。
    /// さらにサイドカーの mtime だけが進むので、フォルダ切替のたびに import の fast-path
    /// が外れる (2026-08-29 レビュー R-26)。
    ///
    /// 画面上の編集は消さない。失敗はトーストで伝え、利用者がやり直せるようにする。
    #[test]
    fn an_edit_the_store_refused_is_not_mirrored_into_the_sidecar() {
        let mut app = setup_app();
        let folder = app.tmp.path().join("pics");
        std::fs::create_dir_all(&folder).unwrap();
        let image = folder.join("page.png");
        std::fs::write(&image, b"x").unwrap();
        app.settings.sidecar_backup_enabled = true;
        app.items = vec![GridItem::Image(image.clone())];
        app.image_metas = vec![None];
        app.thumbnails = vec![ThumbnailState::Pending];

        // 正本を書けない状態にする。read-only で開いた DB は書き込みだけが失敗する。
        let db_path = app.tmp.path().join("mask.db");
        drop(app.mask_db.take());
        app.mask_db =
            Some(crate::mask_db::MaskDb::open_readonly_at(&db_path).expect("read-only で開ける"));

        let mask = vec![true; 4];
        app.save_mask_with_sidecar(0, &mask, &[], 2, 2);

        assert!(
            toast_text(&app).contains("保存できませんでした"),
            "保存できなかったことが利用者に伝わっていない: {:?}",
            toast_text(&app)
        );
        let mirrored = app
            .sidecars
            .get(&folder)
            .is_some_and(|sidecar| sidecar.items().values().any(|entry| entry.mask.is_some()));
        assert!(
            !mirrored,
            "正本が受け取らなかった編集をサイドカーへ写している (次回起動時に古い正本が勝つ)"
        );
        // 画面上は残る。利用者はやり直せる。
        assert!(
            app.mask_pages.contains(&0),
            "保存に失敗しただけで、編集が画面から消えている"
        );
    }

    /// **正本をそもそも開けていない**ときも、拒否されたときと同じ扱いにする。
    ///
    /// 起動時の `open().ok()` が `None` を返した状態を「書けた」と同じに畳むと、
    /// `edit_store_write_succeeded` が真を返してサイドカーが書かれる。中央に古い行が
    /// あると次回起動の import がそれを捨てるので、**利用者には何も表示されないまま
    /// 編集が消える**。上のテストが `Some(読み取り専用 DB)` 経路、これが `None` 経路
    /// (2026-08-29 レビュー R-26)。
    #[test]
    fn an_edit_with_no_store_open_is_not_mirrored_into_the_sidecar() {
        let mut app = setup_app();
        let folder = app.tmp.path().join("pics");
        std::fs::create_dir_all(&folder).unwrap();
        let image = folder.join("page.png");
        std::fs::write(&image, b"x").unwrap();
        app.settings.sidecar_backup_enabled = true;
        app.items = vec![GridItem::Image(image.clone())];
        app.image_metas = vec![None];
        app.thumbnails = vec![ThumbnailState::Pending];

        // 起動時に開けなかった状態。書き込みを試してすらいない。
        drop(app.mask_db.take());
        assert!(app.mask_db.is_none());

        let mask = vec![true; 4];
        app.save_mask_with_sidecar(0, &mask, &[], 2, 2);

        assert!(
            toast_text(&app).contains("保存できませんでした"),
            "保存先が無いことが利用者に伝わっていない: {:?}",
            toast_text(&app)
        );
        let mirrored = app
            .sidecars
            .get(&folder)
            .is_some_and(|sidecar| sidecar.items().values().any(|entry| entry.mask.is_some()));
        assert!(
            !mirrored,
            "正本を開けていないのにサイドカーへ写している (次回起動時に古い正本が勝つ)"
        );
        assert!(
            app.mask_pages.contains(&0),
            "保存できなかっただけで、編集が画面から消えている"
        );
    }

    /// 3 値のどれがサイドカーを書いてよいかを 1 か所で固定する。
    ///
    /// 14 か所の保存経路はすべて `edit_store_write` を通るので、ここが崩れると
    /// 全経路が同時に崩れる。
    #[test]
    fn only_a_committed_write_lets_the_sidecar_mirror_be_written() {
        use crate::app::EditStoreOutcome;
        let ok: Option<Result<(), String>> = Some(Ok(()));
        let refused: Option<Result<(), String>> = Some(Err("disk full".to_string()));
        let never_opened: Option<Result<(), String>> = None;
        assert_eq!(App::edit_store_write(ok), EditStoreOutcome::Committed);
        assert_eq!(
            App::edit_store_write(refused),
            EditStoreOutcome::Failed("disk full".to_string())
        );
        assert_eq!(
            App::edit_store_write(never_opened),
            EditStoreOutcome::Unavailable
        );

        let mut app = setup_app();
        assert!(app.edit_store_write_succeeded("補正", EditStoreOutcome::Committed));
        assert!(!app.edit_store_write_succeeded("補正", EditStoreOutcome::Unavailable));
        assert!(
            !app.edit_store_write_succeeded(
                "補正",
                EditStoreOutcome::Failed("disk full".to_string())
            )
        );
    }

    // ── 補正レイヤー保存を worker へ出しても R-26 の境界は動かない ──────────
    //
    // 保存は積むだけで戻り、成否は後から返る。同期版が「正本が受理したときだけ
    // サイドカーを書く」順序で守っていた境界を、非同期でも同じ順序で保つ。
    // 以下は `App::apply_local_adjust_write_completion` の状態遷移を、成功経路と
    // **失敗経路の両方**で固定する。

    fn local_adjust_doc(name: &str) -> local_adjust_core::LocalAdjustmentLayers {
        local_adjust_core::LocalAdjustmentLayers::new(vec![
            local_adjust_core::LocalAdjustmentLayer::new(
                name,
                local_adjust_core::LocalMask::Full,
                local_adjust_core::LocalEffect::None,
            ),
        ])
    }

    /// サイドカーを持てる実在フォルダの 1 ページを用意する。
    fn app_with_one_page_for_local_adjust() -> (phase_c_support::AppTestEnv, PathBuf) {
        let mut app = setup_app();
        let folder = app.tmp.path().join("pics");
        std::fs::create_dir_all(&folder).unwrap();
        let image = folder.join("page.png");
        std::fs::write(&image, b"x").unwrap();
        app.settings.sidecar_backup_enabled = true;
        app.items = vec![GridItem::Image(image)];
        app.image_metas = vec![None];
        app.thumbnails = vec![ThumbnailState::Pending];
        (app, folder)
    }

    /// 唯一積まれている保存の (key, generation)。
    fn only_pending_local_adjust_write(app: &App) -> (String, u64) {
        assert_eq!(app.local_adjust_write_pending.len(), 1);
        app.local_adjust_write_pending
            .iter()
            .map(|(key, pending)| (key.clone(), pending.generation))
            .next()
            .unwrap()
    }

    fn mirrored_local_adjust(
        app: &App,
        folder: &Path,
    ) -> Option<local_adjust_core::LocalAdjustmentLayers> {
        app.sidecars.get(folder).and_then(|sidecar| {
            sidecar
                .items()
                .values()
                .find_map(|entry| entry.local_adjust_layers.clone())
        })
    }

    /// 積んだ時点ではまだ**サイドカーを書かない**。
    ///
    /// ここで書いてしまうと、正本が受け取らなかった編集を「保存済み」と主張することに
    /// なる。次回起動の import は「中央が authoritative」なので、中央に古い行があると
    /// その sidecar を捨てる = 利用者には何も出ないまま編集が消える。
    #[test]
    fn enqueueing_a_local_adjust_save_updates_the_screen_but_not_the_sidecar() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();

        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("edited"));

        assert!(
            app.local_adjust_pages.contains(&0),
            "編集は即座に画面へ出る"
        );
        assert!(
            !app.local_adjust_page_keys.is_empty(),
            "バッジ用の presence も即座に立つ"
        );
        assert!(
            mirrored_local_adjust(&app, &folder).is_none(),
            "正本の返事を待たずにサイドカーへ写している"
        );
        assert_eq!(
            app.local_adjust_write_pending.len(),
            1,
            "完了を照合するための記録が残っていない"
        );
    }

    /// 正本が受理したら、**worker が実際に書いた文書**をサイドカーへ写す。
    ///
    /// メモリから取り直すと、積んでから完了までの間に入った編集を「保存済み」として
    /// 写してしまう (書いた内容とミラーがずれる)。
    #[test]
    fn a_committed_write_mirrors_exactly_the_document_that_was_written() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("enqueued"));
        let (key, generation) = only_pending_local_adjust_write(&app);
        // 完了までの間にもう一度編集された状況を作る。写るのは worker が書いた方。
        app.set_local_adjust_layers_for_idx_memory_only(0, local_adjust_doc("later"));

        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key,
                generation,
                layers: local_adjust_doc("written"),
                outcome: crate::app::EditStoreOutcome::Committed,
            },
        );

        assert_eq!(
            mirrored_local_adjust(&app, &folder)
                .expect("受理された編集はサイドカーへ写る")
                .as_slice(),
            local_adjust_doc("written").as_slice(),
            "書いた文書ではなく、その後のメモリを写している"
        );
        assert!(
            app.local_adjust_write_pending.is_empty(),
            "完了した記録が残り続けている"
        );
    }

    /// **正本を開けなかった**とき。サイドカーへは書かず、利用者に伝える。
    ///
    /// 同期版の `Unavailable` は「起動時に開けなかった」だったが、worker 版では
    /// 「書き手が開けなかった」になる。呼び出し側の扱いは同じでなければならない。
    #[test]
    fn a_write_with_no_store_open_is_not_mirrored_and_is_reported() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("edited"));
        let (key, generation) = only_pending_local_adjust_write(&app);

        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key,
                generation,
                layers: local_adjust_doc("edited"),
                outcome: crate::app::EditStoreOutcome::Unavailable,
            },
        );

        assert!(
            mirrored_local_adjust(&app, &folder).is_none(),
            "正本を開けていないのにサイドカーへ写している (次回起動時に古い正本が勝つ)"
        );
        assert!(
            toast_text(&app).contains("保存できませんでした"),
            "保存できなかったことが利用者に伝わっていない: {:?}",
            toast_text(&app)
        );
        assert!(
            app.local_adjust_pages.contains(&0),
            "保存できなかっただけで、編集が画面から消えている"
        );
    }

    /// **正本が拒否した**とき。扱いは開けなかったときと同じ。
    #[test]
    fn a_refused_write_is_not_mirrored_and_is_reported() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("edited"));
        let (key, generation) = only_pending_local_adjust_write(&app);

        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key,
                generation,
                layers: local_adjust_doc("edited"),
                outcome: crate::app::EditStoreOutcome::Failed("disk full".to_string()),
            },
        );

        assert!(
            mirrored_local_adjust(&app, &folder).is_none(),
            "正本が受け取らなかった編集をサイドカーへ写している"
        );
        assert!(
            toast_text(&app).contains("disk full"),
            "拒否の理由が利用者に伝わっていない: {:?}",
            toast_text(&app)
        );
        assert!(app.local_adjust_pages.contains(&0));
    }

    /// 積めなかった保存は**その場で失敗として扱う**。
    ///
    /// worker が止まっていると、積んだつもりの保存は正本に何も書かない。黙って
    /// 受け付けると、画面には編集が残ったまま保存されていない状態が続く。
    #[test]
    fn a_save_the_worker_could_not_take_is_reported_and_not_mirrored() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        // worker を先に用意し、抜けた状態にしてから保存する。
        app.ensure_local_adjust_write_handle();
        app.local_adjust_write_handle
            .as_ref()
            .unwrap()
            .mark_worker_stopped_for_test();

        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("edited"));

        assert!(
            mirrored_local_adjust(&app, &folder).is_none(),
            "積めていない保存をサイドカーへ写している"
        );
        assert!(
            toast_text(&app).contains("保存できませんでした"),
            "保存できなかったことが利用者に伝わっていない: {:?}",
            toast_text(&app)
        );
        assert!(
            app.local_adjust_write_pending.is_empty(),
            "着地しない保存の記録が残り続けている"
        );
        assert!(
            app.local_adjust_pages.contains(&0),
            "保存できなかっただけで、編集が画面から消えている"
        );
    }

    /// 新しい保存が控えていても、**受理された古い完了は publish する**。
    ///
    /// worker は key ごとに順に書くので完了は古い順に届く。ここで古い完了を捨てると、
    /// 次の完了が失敗したときに「正本には古い内容があるのに sidecar には何も無い」
    /// 状態で止まる (2026-08-31 Codex P2)。下の合成遷移テストがその筋を通しで見る。
    #[test]
    fn an_older_committed_completion_still_publishes_while_a_newer_save_is_pending() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("first"));
        let (key, stale_generation) = only_pending_local_adjust_write(&app);
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("second"));

        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key: key.clone(),
                generation: stale_generation,
                layers: local_adjust_doc("first"),
                outcome: crate::app::EditStoreOutcome::Committed,
            },
        );

        assert_eq!(
            mirrored_local_adjust(&app, &folder)
                .expect("受理された内容はサイドカーへ写る")
                .as_slice(),
            local_adjust_doc("first").as_slice(),
            "正本が受理した内容がサイドカーに無い"
        );
        assert!(
            app.local_adjust_write_pending.contains_key(&key),
            "新しい保存の記録まで畳んでいる (その完了がミラー先を失う)"
        );
    }

    /// **合成遷移**: 古い保存が受理され、新しい保存が失敗する。
    ///
    /// この順序でサイドカーが空のまま残ると、正本 (古い内容あり) と食い違ったまま
    /// 次の保存まで直らない。フォルダを移すとその古い内容も復元できない。
    #[test]
    fn a_committed_save_stays_mirrored_when_the_next_save_fails() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("committed"));
        let (key, committed_generation) = only_pending_local_adjust_write(&app);
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("doomed"));
        let (_, doomed_generation) = only_pending_local_adjust_write(&app);

        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key: key.clone(),
                generation: committed_generation,
                layers: local_adjust_doc("committed"),
                outcome: crate::app::EditStoreOutcome::Committed,
            },
        );
        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key,
                generation: doomed_generation,
                layers: local_adjust_doc("doomed"),
                outcome: crate::app::EditStoreOutcome::Failed("disk full".to_string()),
            },
        );

        assert_eq!(
            mirrored_local_adjust(&app, &folder)
                .expect("受理された内容が残っていない")
                .as_slice(),
            local_adjust_doc("committed").as_slice(),
            "失敗した保存が、受理済みのミラーを消している / 上書きしている"
        );
        assert!(
            toast_text(&app).contains("disk full"),
            "失敗が利用者に伝わっていない: {:?}",
            toast_text(&app)
        );
        assert!(app.local_adjust_write_pending.is_empty());
    }

    /// 空の文書を受理したら、サイドカーからも消す。
    #[test]
    fn a_committed_empty_document_removes_the_sidecar_entry() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("edited"));
        let (key, generation) = only_pending_local_adjust_write(&app);
        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key: key.clone(),
                generation,
                layers: local_adjust_doc("edited"),
                outcome: crate::app::EditStoreOutcome::Committed,
            },
        );
        assert!(mirrored_local_adjust(&app, &folder).is_some());

        app.set_local_adjust_layers_for_idx(0, local_adjust_core::LocalAdjustmentLayers::default());
        let generation = app.local_adjust_write_pending[&key].generation;
        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key,
                generation,
                layers: local_adjust_core::LocalAdjustmentLayers::default(),
                outcome: crate::app::EditStoreOutcome::Committed,
            },
        );

        assert!(
            mirrored_local_adjust(&app, &folder).is_none(),
            "全削除がサイドカーへ伝わっていない"
        );
    }

    /// ミラー先は**積んだ時点で固定**する。
    ///
    /// 完了が返る頃には一覧の idx が別のページを指し得る。そのとき解決し直すと、
    /// 無関係なページのサイドカーへ書き込む。
    #[test]
    fn the_mirror_target_is_the_one_fixed_when_the_save_was_enqueued() {
        let (mut app, folder) = app_with_one_page_for_local_adjust();
        app.set_local_adjust_layers_for_idx(0, local_adjust_doc("edited"));
        let (key, generation) = only_pending_local_adjust_write(&app);

        // 一覧が入れ替わり、idx 0 は別フォルダの別ページを指すようになった。
        let other = app.tmp.path().join("other");
        std::fs::create_dir_all(&other).unwrap();
        let other_image = other.join("elsewhere.png");
        std::fs::write(&other_image, b"y").unwrap();
        app.items = vec![GridItem::Image(other_image)];

        app.apply_local_adjust_write_completion(
            crate::local_adjust_write_worker::LocalAdjustWriteCompletion {
                key,
                generation,
                layers: local_adjust_doc("written"),
                outcome: crate::app::EditStoreOutcome::Committed,
            },
        );

        assert!(
            mirrored_local_adjust(&app, &folder).is_some(),
            "積んだ時点のフォルダへ写っていない"
        );
        assert!(
            mirrored_local_adjust(&app, &other).is_none(),
            "完了時の idx で解決し直し、無関係なページへ書いている"
        );
    }

    #[test]
    fn delete_mask_shortcuts_remove_existing_masks_and_clear_caches() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let idx_a = push_image(&mut app, "C:/pics/a.jpg");
        let idx_b = push_image(&mut app, "C:/pics/b.jpg");
        app.visible_indices = vec![idx_a, idx_b];
        let mask = mask_2x2();
        app.save_mask_with_sidecar(idx_a, &mask, &[], 2, 2);
        app.save_conceal_with_sidecar(idx_b, &mask, &[], 2, 2);
        let erase_key = app.page_path_key(idx_a).unwrap();
        let conceal_key = app.page_path_key(idx_b).unwrap();
        app.checked.insert(idx_a);
        app.checked.insert(idx_b);
        insert_stale_erase_result_cache(&mut app, &ctx, idx_a, "erase_result_stale");
        insert_stale_conceal_cache(&mut app, &ctx, idx_a, "erase_conceal_stale");
        app.erase_base_cache.insert(
            idx_a,
            std::sync::Arc::new(egui::ColorImage::new(
                [1, 1],
                vec![egui::Color32::LIGHT_BLUE],
            )),
        );
        app.erase_base_tex_cache.insert(
            idx_a,
            ctx.load_texture(
                "erase_base_tex_stale",
                egui::ColorImage::new([1, 1], vec![egui::Color32::LIGHT_BLUE]),
                egui::TextureOptions::LINEAR,
            ),
        );

        app.delete_erase_masks_from_selection();

        assert!(!app.mask_pages.contains(&idx_a));
        assert!(app.conceal_pages.contains(&idx_b));
        assert!(app.erase_result_cache.is_empty());
        assert!(!app.erase_base_cache.contains_key(&idx_a));
        assert!(!app.erase_base_tex_cache.contains_key(&idx_a));
        assert!(!app.conceal_cache.contains_key(&idx_a));
        assert!(
            app.mask_db
                .as_ref()
                .unwrap()
                .get_full(&erase_key, 2, 2)
                .is_none()
        );
        assert_eq!(toast_text(&app), "[消しゴムマスクを1枚から削除]");
        assert!(app.checked.is_empty());

        app.checked.insert(idx_a);
        app.checked.insert(idx_b);
        insert_stale_conceal_cache(&mut app, &ctx, idx_b, "conceal_delete_stale");
        app.conceal_base_cache.insert(
            idx_b,
            std::sync::Arc::new(egui::ColorImage::new(
                [1, 1],
                vec![egui::Color32::LIGHT_GREEN],
            )),
        );

        app.delete_conceal_masks_from_selection();

        assert!(!app.conceal_pages.contains(&idx_b));
        assert!(!app.conceal_cache.contains_key(&idx_b));
        assert!(!app.conceal_base_cache.contains_key(&idx_b));
        assert!(
            app.conceal_db
                .as_ref()
                .unwrap()
                .get_full(&conceal_key, 2, 2)
                .is_none()
        );
        assert_eq!(toast_text(&app), "[隠蔽マスクを1枚から削除]");
        assert!(app.checked.is_empty());
    }

    #[test]
    fn empty_mask_slots_are_noop_with_specific_toasts() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let idx = push_image(&mut app, "C:/pics/a.jpg");
        app.visible_indices = vec![idx];
        app.selected = Some(idx);
        insert_stale_conceal_cache(&mut app, &ctx, idx, "empty_slot_stale");

        app.apply_conceal_slot_to_selection(1);

        assert!(!app.conceal_pages.contains(&idx));
        assert!(
            app.conceal_cache.contains_key(&idx),
            "empty slot no-op should not invalidate unrelated conceal cache"
        );
        assert_eq!(toast_text(&app), "[隠蔽スロット1は空です]");

        app.fs_feedback_toast = None;
        app.apply_slot_to_selection(1);

        assert!(!app.mask_pages.contains(&idx));
        assert_eq!(toast_text(&app), "[消しゴムスロット1は空です]");
    }

    /// effective_params は「個別 → お気に入り → global」の順で解決する。
    #[test]
    fn cascade_individual_beats_favorite_beats_global() {
        let mut app = setup_app();
        let fav = FavoriteEntry::new("test".to_string(), PathBuf::from("C:/pics"));
        let fav_id = fav.id;
        app.settings.favorites.push(fav);
        let idx = push_image(&mut app, "C:/pics/a.jpg");

        // 初期状態: global
        app.settings.global_preset = params_with_brightness(5.0);
        assert_eq!(app.effective_params(idx).brightness, 5.0);

        // お気に入り標準を入れる → 優先
        app.adjustment_favorite_params
            .insert(fav_id, params_with_brightness(20.0));
        assert_eq!(app.effective_params(idx).brightness, 20.0);

        // 個別設定を入れる → 最優先
        app.adjustment_page_params
            .insert(idx, params_with_brightness(50.0));
        assert_eq!(app.effective_params(idx).brightness, 50.0);

        // 個別解除 → お気に入り、お気に入り解除 → global に戻る
        app.adjustment_page_params.remove(&idx);
        assert_eq!(app.effective_params(idx).brightness, 20.0);
        app.adjustment_favorite_params.remove(&fav_id);
        assert_eq!(app.effective_params(idx).brightness, 5.0);
    }

