    #[test]
    fn an_output_the_filter_hides_leaves_the_filter_and_the_selection_alone() {
        use crate::grid_item::GridItem;
        use crate::post_operation_selection::ExpectedOutputs;
        let mut app = setup_app();
        let folder = std::path::PathBuf::from("c:/p");
        for name in ["a.jpg", "hidden.jpg"] {
            app.items.push(GridItem::Image(folder.join(name)));
            app.thumbnails.push(ThumbnailState::Pending);
        }
        app.current_folder = Some(folder.clone());
        app.rebuild_visible_indices();
        app.selected = Some(0);

        // 出力は items にはあるが、絞り込みで表示から外れている状態。フィルタを
        // 自動解除して無理に見せたり、隠れたままの項目を選んだりしてはいけない。
        let before_filter = app.visible_indices.clone();
        app.visible_indices.retain(|&idx| idx != 1);
        assert_ne!(app.visible_indices, before_filter);
        app.request_post_operation_selection(
            folder.clone(),
            ExpectedOutputs::Known(vec![folder.join("hidden.jpg")]),
        );
        assert!(!app.apply_post_operation_selection());
        assert_eq!(
            app.selected,
            Some(0),
            "見えない項目のために選択を動かさない"
        );
        assert_eq!(app.visible_indices, vec![0], "フィルタは変えない");
        assert!(
            app.post_operation_selection.is_some(),
            "まだ届いていないだけかもしれないので要求は残す"
        );
    }

    #[test]
    fn switching_sides_in_text_mode_keeps_the_way_back_to_the_spread() {
        use crate::grid_item::GridItem;
        use crate::settings::SpreadMode;
        let mut app = setup_app();
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/a.jpg")));
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/b.jpg")));
        app.thumbnails.push(ThumbnailState::Pending);
        app.thumbnails.push(ThumbnailState::Pending);
        // 見開きから Ctrl+T に入った直後の状態。左ページを編集している。
        app.fullscreen_idx = Some(0);
        app.spread_mode = SpreadMode::Single;
        app.text_spread_ctx = Some(crate::app::PageEditSpreadPivot {
            saved_mode: SpreadMode::Rtl,
            pair: (0, 1),
        });
        app.text_mode = true;

        app.switch_text_target_in_spread(1);

        assert_eq!(app.fullscreen_idx, Some(1), "右ページへ移る");
        assert_eq!(
            app.spread_mode,
            SpreadMode::Single,
            "単ページのまま編集を続ける"
        );
        assert!(
            app.text_spread_ctx.is_some(),
            "左右の切り替えで退避を使い切ってはいけない (使い切ると抜けたときに戻れない)"
        );

        // ここで抜けると、入る前の見開きへ戻る。
        app.reset_text_mode();
        assert_eq!(app.spread_mode, SpreadMode::Rtl);
        assert_eq!(app.fullscreen_idx, Some(0));
        assert!(app.text_spread_ctx.is_none(), "退場では退避を使い切る");
    }

    #[test]
    fn reset_erase_mode_restores_saved_spread_state() {
        use crate::grid_item::GridItem;
        use crate::settings::SpreadMode;
        let mut app = setup_app();
        // ペア: idx 0 (left), idx 1 (right) を仮想的に保存している状態を組み立てる。
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/a.jpg")));
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/b.jpg")));
        app.thumbnails.push(ThumbnailState::Pending);
        app.thumbnails.push(ThumbnailState::Pending);
        // 編集対象は左ページとする
        app.fullscreen_idx = Some(0);
        app.spread_mode = SpreadMode::Single; // 消しゴム中の状態
        app.erase_spread_ctx = Some(crate::app::PageEditSpreadPivot {
            saved_mode: SpreadMode::Ltr,
            pair: (0, 1),
        });
        app.fs_zoom = 2.0;
        app.fs_pan = egui::Vec2::new(50.0, 30.0);
        app.erase_mode = true;

        app.reset_erase_mode();

        assert_eq!(
            app.spread_mode,
            SpreadMode::Ltr,
            "reset 後に spread_mode が Ltr へ復元される"
        );
        assert_eq!(
            app.fullscreen_idx,
            Some(0),
            "fullscreen_idx は左ページに戻る (resolve_spread_pair で同ペアが復元される)"
        );
        assert!(app.erase_spread_ctx.is_none(), "spread_ctx は消費される");
        assert_eq!(app.fs_zoom, 1.0, "ズームはリセット");
        assert_eq!(app.fs_pan, egui::Vec2::ZERO, "パンはリセット");
        assert!(!app.erase_mode);
    }

    /// `continuous_reading_active_for_idx` がレンダラの連続読み描画条件と一致し、入力ハンドラ
    /// (キー/ホイール/クリック/gamepad) のゲートとして使える述語であることを固定する回帰テスト。
    /// 縦/横読み中に解析・比較・動画・非対応アイテムへ入ったら false を返し、入力がページ送りへ
    /// フォールバックできること (= ↑↓ がスクロールに吸われてナビもスクロールもしないデッド入力に
    /// ならないこと) を担保する。
    #[test]
    fn continuous_reading_active_predicate_gates_correctly() {
        use crate::grid_item::GridItem;
        use crate::settings::ReadingFlow;
        let mut app = setup_app();
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/a.jpg"))); // idx 0: 対応画像
        app.items
            .push(GridItem::Video(std::path::PathBuf::from("c:/p/v.mp4"))); // idx 1: 動画
        app.thumbnails.push(ThumbnailState::Pending);
        app.thumbnails.push(ThumbnailState::Pending);

        // paged flow では常に非アクティブ
        app.reading_flow = ReadingFlow::Paged;
        assert!(!app.continuous_reading_active_for_idx(0));

        // 縦読み + 対応画像 + 競合モード無し → アクティブ (縦・横どちらも)
        app.reading_flow = ReadingFlow::Vertical;
        assert!(app.continuous_reading_active_for_idx(0));
        app.reading_flow = ReadingFlow::Horizontal;
        assert!(app.continuous_reading_active_for_idx(0));

        // 動画は対応外 → 非アクティブ (連結方式トグル / scroll の誤適用を防ぐ)
        assert!(!app.continuous_reading_active_for_idx(1));
        // 解析モード中はレンダラが単ページへフォールバックするので非アクティブ
        app.analysis_mode = true;
        assert!(!app.continuous_reading_active_for_idx(0));
        app.analysis_mode = false;

        // 比較モード中も非アクティブ
        app.compare_view_mode = crate::app::CompareViewMode::PinnedNormal;
        assert!(!app.continuous_reading_active_for_idx(0));
        app.compare_view_mode = crate::app::CompareViewMode::Off;

        // 範囲外 idx でも panic せず false
        assert!(!app.continuous_reading_active_for_idx(99));
    }

