        app.spread_mode = SpreadMode::Ltr;
        app.fullscreen_idx = Some(0);

        let (new_idx, anchor_idx) = app
            .compute_spread_offset_nudge(0, 1)
            .expect("2ページ見開きから末尾単独表示へのずらしは有効");
