    #[test]
    fn ziptest_zip_fixtures_materialize_expected_tree_paths_if_present() {
        let Some(src) = ziptest_sample("nested_tree_test.zip") else {
            return;
        };
        let detail = crate::zip_loader::enumerate_image_entries_detailed(&src).unwrap();
        assert!(!detail.has_foreign_archives);
        let mut app = app_with_zip_entries(src.clone(), detail.entries, None);
        assert_eq!(
            zip_dir_prefixes(&app),
            vec![
                "01_inner_archives/",
                "02_plain_subfolders/",
                "03_single_wrapper/",
                "04_deep_nest/",
                "05_mixed/",
            ]
        );
        assert_eq!(zip_image_entries(&app), vec!["root_a.png", "root_b.png"]);

        app.zip_nav_enter("01_inner_archives/");
        assert_eq!(
            zip_dir_prefixes(&app),
            vec![
                "01_inner_archives/chapterA.zip/",
                "01_inner_archives/chapterB.cbz/",
                "01_inner_archives/chapterC.zip/",
            ]
        );
        app.zip_nav_enter("01_inner_archives/chapterA.zip/");
        assert!(
            zip_image_entries(&app)
                .iter()
                .any(|n| n == "01_inner_archives/chapterA.zip/p1.png")
        );
        drop(app);

        let Some(wrapper) = ziptest_sample("single_book_wrapper.zip") else {
            return;
        };
        let entries = crate::zip_loader::enumerate_image_entries(&wrapper).unwrap();
        let app = app_with_zip_entries(wrapper, entries, None);
        assert!(zip_dir_prefixes(&app).is_empty());
        assert!(
            zip_image_entries(&app)
                .iter()
                .all(|n| n.starts_with("the_only_folder/"))
        );
        drop(app);

        let Some(flat) = ziptest_sample("simple_flat.zip") else {
            return;
        };
        let entries = crate::zip_loader::enumerate_image_entries(&flat).unwrap();
        let mut app = app_with_zip_entries(flat, entries, None);
        assert!(zip_dir_prefixes(&app).is_empty());
        assert!(!app.zip_nav_handle_ctrl_updown(true));
        assert!(!app.zip_nav_handle_ctrl_updown(false));
    }

    #[test]
    fn ziptest_foreign_zip_fixture_shows_native_zip_part_before_conversion_if_present() {
        let Some(src) = ziptest_sample("foreign_in_zip.zip") else {
            return;
        };
        let detail = crate::zip_loader::enumerate_image_entries_detailed(&src).unwrap();
        assert!(detail.has_foreign_archives);
        let mut app = app_with_zip_entries(src, detail.entries, None);
        assert_eq!(zip_dir_prefixes(&app), vec!["inner/"]);
        assert_eq!(zip_image_entries(&app), vec!["cover_root.png"]);

        app.zip_nav_enter("inner/");
        let dirs = zip_dir_prefixes(&app);
        let images = zip_image_entries(&app);
        assert!(
            dirs == vec!["inner/part2.zip/"]
                || (dirs.is_empty() && images.iter().all(|n| n.starts_with("inner/part2.zip/"))),
            "変換前の ZIP ネイティブ経路では part2.zip だけ見え、RAR/7z は提案対象として残る: dirs={dirs:?} images={images:?}"
        );
    }

    #[test]
    fn ziptest_converted_archive_fixtures_materialize_expected_tree_paths_if_present() {
        let cases: &[(
            &str,
            crate::archive_converter::ArchiveFormat,
            &[&str],
            &[&str],
        )] = &[
            (
                "nested_7z_test.7z",
                crate::archive_converter::ArchiveFormat::SevenZ,
                &["deep.7z/", "inside.zip/", "sub/"],
                &["z7_01.png", "z7_02.png"],
            ),
            (
                "rar_in_zip.zip",
                crate::archive_converter::ArchiveFormat::Zip,
                &["inner.rar/"],
                &["front.png"],
            ),
            (
                "zip_in_rar.rar",
                crate::archive_converter::ArchiveFormat::Rar,
                &["inner.zip/"],
                &["zr_01.png", "zr_02.png"],
            ),
            (
                "nested_rar_test.rar",
                crate::archive_converter::ArchiveFormat::Rar,
                &["inner.rar/"],
                &["zr_01.png", "zr_02.png"],
            ),
        ];

        for (name, format, expected_dirs, expected_root_images) in cases {
            let Some((_dir, source, converted_zip)) = convert_ziptest_sample(name, *format) else {
                continue;
            };
            let entries = crate::zip_loader::enumerate_image_entries(&converted_zip).unwrap();
            let mut app = app_with_zip_entries(converted_zip, entries, Some(source.clone()));
            assert_eq!(zip_dir_prefixes(&app), *expected_dirs, "{name}");
            for image in *expected_root_images {
                assert!(
                    zip_image_entries(&app).iter().any(|n| n == image),
                    "{name}: missing root image {image}"
                );
            }
            let first_dir = expected_dirs[0];
            app.zip_nav_enter(first_dir);
            assert!(
                zip_image_entries(&app)
                    .iter()
                    .any(|n| n.starts_with(first_dir)),
                "{name}: entering {first_dir} should reveal pages"
            );
            let dir_key = first_dir.trim_end_matches('/');
            assert_eq!(
                current_container_rating_key(&app),
                rating_key_for(&source.join(dir_key)),
                "{name}: converted archive child rating key should use source archive root"
            );
        }
    }

    #[test]
    fn ziptest_converted_foreign_zip_fixture_materializes_all_archive_parts_if_present() {
        let Some((_dir, source, converted_zip)) = convert_ziptest_sample(
            "foreign_in_zip.zip",
            crate::archive_converter::ArchiveFormat::Zip,
        ) else {
            return;
        };
        let entries = crate::zip_loader::enumerate_image_entries(&converted_zip).unwrap();
        let has_part3_rar = entries
            .iter()
            .any(|entry| entry.entry_name.starts_with("inner/part3.rar/"));
        let mut app = app_with_zip_entries(converted_zip, entries, Some(source.clone()));
        assert_eq!(zip_dir_prefixes(&app), vec!["inner/"]);
        assert_eq!(zip_image_entries(&app), vec!["cover_root.png"]);
        assert_eq!(current_container_rating_key(&app), rating_key_for(&source));

        app.zip_nav_enter("inner/");
        let mut expected = vec!["inner/part1.7z/", "inner/part2.zip/"];
        if has_part3_rar {
            expected.push("inner/part3.rar/");
        }
        assert_eq!(zip_dir_prefixes(&app), expected);
        assert_eq!(
            current_container_rating_key(&app),
            rating_key_for(&source.join("inner"))
        );
    }

    fn start_archive_decisions_for_test(app: &mut App, indices: impl IntoIterator<Item = usize>) {
        let scope: HashSet<usize> = indices.into_iter().collect();
        let end = app.items.len();
        app.start_converted_archive_cache_paths_refresh(&scope, (0, end), (0, end));
    }

    fn poll_archive_decisions_for_test(app: &mut App) {
        let ctx = egui::Context::default();
        for _ in 0..100 {
            app.poll_converted_archive_cache_paths(&ctx);
            if app.converted_archive_cache_paths_pending.is_none() {
                return;
            }
            std::thread::sleep(std::time::Duration::from_millis(2));
        }
        panic!("archive decision worker did not finish");
    }

    fn install_folder_item_for_archive_pin_test(app: &mut App, folder: &Path) {
        let metadata = std::fs::metadata(folder).unwrap();
        app.install_new_items(
            vec![GridItem::Folder(folder.to_path_buf())],
            vec![Some((
                crate::ui_helpers::mtime_secs(&metadata),
                metadata.len() as i64,
            ))],
        );
    }

    fn assert_archive_pin_root_refresh_stays_idle(app: &mut App, frames: usize) {
        for frame in 0..frames {
            start_archive_decisions_for_test(app, 0..1);
            assert!(
                app.converted_archive_cache_paths_pending.is_none(),
                "stable archive pin root restarted on idle frame {frame}"
            );
        }
    }

    fn install_pending_archive_items(app: &mut App, count: usize) -> Vec<String> {
        let paths: Vec<_> = (0..count)
            .map(|idx| PathBuf::from(format!(r"C:\archive-scope-test\book-{idx:03}.7z")))
            .collect();
        app.install_new_items(
            paths
                .iter()
                .cloned()
                .map(|path| GridItem::ConvertibleArchive {
                    path,
                    format: crate::archive_converter::ArchiveFormat::SevenZ,
                })
                .collect(),
            vec![Some((1, 2)); count],
        );
        paths
            .iter()
            .map(|path| crate::path_key::normalize_keep_drive(path))
            .collect()
    }

    #[test]
    fn convertible_archive_with_cache_builds_zip_first_thumb_request() {
        use crate::folder_thumb_pins::FolderPinSource;
        use crate::grid_item::GridItem;
        use crate::thumb_loader::ResolveStrategy;

        let src = std::path::PathBuf::from(r"C:\books\book.7z");
        let cache = std::path::PathBuf::from(r"C:\cache\book.zip");
        let item = GridItem::ConvertibleArchive {
            path: src.clone(),
            format: crate::archive_converter::ArchiveFormat::SevenZ,
        };
        let mut converted = std::collections::HashMap::new();
        converted.insert(
            crate::path_key::normalize_keep_drive(&src),
            crate::app::ConvertedArchiveSourceState::CachedZip(cache.clone()),
        );
        let pins: std::collections::HashMap<String, FolderPinSource> =
            std::collections::HashMap::new();

        let req = make_load_request(
            &item,
            4,
            111,
            222,
            false,
            None,
            Some(crate::settings::SortOrder::Numeric),
            3,
            &pins,
            &converted,
            None,
            None,
            None,
            None,
            false,
        )
        .expect("converted archive with a valid cache should request a thumbnail");

        assert_eq!(req.path, cache);
        assert_eq!(req.mtime, 111);
        assert_eq!(req.file_size, 222);
        assert_eq!(req.resolve_override, Some(ResolveStrategy::ZipFirstImage));
        assert_eq!(
            req.cache_key_override.as_deref(),
            Some("archivethumb:7z:book.7z")
        );
    }

    #[test]
    fn converted_rar_cache_hit_skips_direct_read_inspection() {
        let source = PathBuf::from(r"C:\books\book.rar");
        let cached = PathBuf::from(r"C:\cache\book.zip");
        let candidate = ConvertedArchiveCandidate {
            archive_key: crate::path_key::normalize_keep_drive(&source),
            path: source.clone(),
            mtime: 10,
            file_size: 20,
            idx: 0,
        };
        let inspections = Cell::new(0usize);

        let state = resolve_converted_archive_candidate_with(
            &candidate,
            &AtomicBool::new(false),
            |path| Ok(path.to_path_buf()),
            |path, mtime, file_size| {
                assert_eq!(path, source);
                assert_eq!((mtime, file_size), (10, 20));
                Some(cached.clone())
            },
            |path, _| {
                inspections.set(inspections.get() + 1);
                Ok((
                    crate::rar_loader::RarDirectReadDecision::Direct,
                    path.to_path_buf(),
                ))
            },
        );

        assert_eq!(
            state,
            Some(crate::app::ConvertedArchiveSourceState::CachedZip(cached))
        );
        assert_eq!(inspections.get(), 0);
    }

    #[test]
    fn direct_readable_rar_with_converted_zip_intentionally_prefers_cached_zip() {
        let source = PathBuf::from(r"C:\books\direct.rar");
        let cached = PathBuf::from(r"C:\cache\direct.zip");
        let candidate = ConvertedArchiveCandidate {
            archive_key: crate::path_key::normalize_keep_drive(&source),
            path: source.clone(),
            mtime: 30,
            file_size: 40,
            idx: 0,
        };
        let direct_inspection_would_run = Cell::new(false);

        let state = resolve_converted_archive_candidate_with(
            &candidate,
            &AtomicBool::new(false),
            |path| Ok(path.to_path_buf()),
            |_, _, _| Some(cached.clone()),
            |path, _| {
                direct_inspection_would_run.set(true);
                Ok((
                    crate::rar_loader::RarDirectReadDecision::Direct,
                    path.to_path_buf(),
                ))
            },
        );

        assert_eq!(
            state,
            Some(crate::app::ConvertedArchiveSourceState::CachedZip(cached)),
            "A1 intentionally changes Direct + converted from Direct to CachedZip"
        );
        assert!(!direct_inspection_would_run.get());
    }

    #[test]
    fn install_new_items_resolves_converted_archive_cache_paths_async() {
        use crate::grid_item::GridItem;
        use std::io::Write;

        let mut app = setup_app();
        let src = app.tmp.path().join("book.7z");
        let cached = app.tmp.path().join("book.zip");
        std::fs::File::create(&src)
            .unwrap()
            .write_all(b"archive")
            .unwrap();
        std::fs::File::create(&cached)
            .unwrap()
            .write_all(b"PK\x03\x04")
            .unwrap();

        let src_meta = std::fs::metadata(&src).unwrap();
        let src_mtime = crate::ui_helpers::mtime_secs(&src_meta);
        let src_size = src_meta.len() as i64;
        let cached_size = std::fs::metadata(&cached).unwrap().len() as i64;
        app.archive_cache_db
            .as_ref()
            .unwrap()
            .record(
                &src,
                src_mtime,
                src_size,
                crate::archive_converter::ArchiveFormat::SevenZ,
                &cached,
                cached_size,
                1,
                false,
            )
            .unwrap();

        app.install_new_items(
            vec![GridItem::ConvertibleArchive {
                path: src.clone(),
                format: crate::archive_converter::ArchiveFormat::SevenZ,
            }],
            vec![Some((src_mtime, src_size))],
        );

        let key = crate::path_key::normalize_keep_drive(&src);
        assert_eq!(
            app.converted_archive_cache_paths.get(&key),
            Some(&crate::app::ConvertedArchiveSourceState::Pending),
            "install_new_items must publish an explicit Pending state without peeking the DB"
        );
        assert!(app.converted_archive_cache_paths_pending.is_none());
        start_archive_decisions_for_test(&mut app, 0..1);
        assert!(app.converted_archive_cache_paths_pending.is_some());

        let ctx = egui::Context::default();
        for _ in 0..50 {
            app.poll_converted_archive_cache_paths(&ctx);
            if app.converted_archive_cache_paths_pending.is_none() {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(5));
        }

        assert!(app.converted_archive_cache_paths_pending.is_none());
        assert_eq!(
            app.converted_archive_cache_paths
                .get(&key)
                .and_then(crate::app::ConvertedArchiveSourceState::load_path),
            Some(cached.as_path())
        );
    }

    #[test]
    fn convertible_archive_typed_states_distinguish_waiting_from_unavailable() {
        let src = PathBuf::from(r"C:\books\book.7z");
        let direct = PathBuf::from(r"C:\books\book.rar");
        let cached = PathBuf::from(r"C:\cache\book.zip");
        let item = GridItem::ConvertibleArchive {
            path: src.clone(),
            format: crate::archive_converter::ArchiveFormat::SevenZ,
        };
        let key = crate::path_key::normalize_keep_drive(&src);
        let pins = std::collections::HashMap::new();

        let pending_sources = std::collections::HashMap::from([(
            key.clone(),
            crate::app::ConvertedArchiveSourceState::Pending,
        )]);
        let pending = make_load_request(
            &item,
            0,
            1,
            2,
            false,
            None,
            None,
            0,
            &pins,
            &pending_sources,
            None,
            None,
            None,
            None,
            false,
        )
        .expect("Pending must build a cache-only request");
        assert_eq!(pending.path, src);
        assert_eq!(pending.source_policy, LoadSourcePolicy::CacheOnly);

        let unavailable_sources = std::collections::HashMap::from([(
            key.clone(),
            crate::app::ConvertedArchiveSourceState::Unavailable,
        )]);
        assert!(
            make_load_request(
                &item,
                0,
                1,
                2,
                false,
                None,
                None,
                0,
                &pins,
                &unavailable_sources,
                None,
                None,
                None,
                None,
                false,
            )
            .is_none(),
            "Unavailable remains a terminal no-request state"
        );

        for state in [
            crate::app::ConvertedArchiveSourceState::Direct(direct.clone()),
            crate::app::ConvertedArchiveSourceState::CachedZip(cached.clone()),
        ] {
            let expected = state.load_path().unwrap().to_path_buf();
            let sources = std::collections::HashMap::from([(key.clone(), state)]);
            let request = make_load_request(
                &item, 0, 1, 2, false, None, None, 0, &pins, &sources, None, None, None, None,
                false,
            )
            .expect("resolved archive state should build a request");
            assert_eq!(request.path, expected);
        }
    }

    #[test]
    fn pending_convertible_archive_cache_only_request_returns_cached_thumbnail() {
        let source = PathBuf::from(r"C:\books\book.rar");
        let item = GridItem::ConvertibleArchive {
            path: source.clone(),
            format: crate::archive_converter::ArchiveFormat::Rar,
        };
        let sources = std::collections::HashMap::from([(
            crate::path_key::normalize_keep_drive(&source),
            crate::app::ConvertedArchiveSourceState::Pending,
        )]);
        let request = make_load_request(
            &item,
            0,
            11,
            22,
            false,
            None,
            None,
            0,
            &std::collections::HashMap::new(),
            &sources,
            None,
            None,
            None,
            None,
            false,
        )
        .expect("Pending archive should build cache-only request");
        assert_eq!(request.source_policy, LoadSourcePolicy::CacheOnly);

        let mut webp = Vec::new();
        image::DynamicImage::ImageRgba8(image::RgbaImage::from_pixel(
            2,
            2,
            image::Rgba([10, 20, 30, 255]),
        ))
        .write_to(
            &mut std::io::Cursor::new(&mut webp),
            image::ImageFormat::WebP,
        )
        .unwrap();
        let key = request.cache_key_override.clone().unwrap();
        let cache_map = std::sync::RwLock::new(std::collections::HashMap::from([(
            key,
            crate::catalog::CacheEntry {
                mtime: 11,
                file_size: 22,
                jpeg_data: webp,
                source_dims: Some((2, 2)),
                layout_dims: None,
            },
        )]));
        let (tx, rx) = std::sync::mpsc::channel();
        let done = Arc::new(AtomicUsize::new(0));
        let stats = Arc::new(Mutex::new(crate::stats::ThumbStats::default()));
        let keep_start = Arc::new(AtomicUsize::new(0));
        let keep_end = Arc::new(AtomicUsize::new(1));
        crate::thumb_loader::process_load_request(
            &request,
            &cache_map,
            &tx,
            None,
            64,
            75,
            64,
            CacheDecision::from_settings(&crate::settings::Settings::default()),
            &done,
            &stats,
            None,
            &keep_start,
            &keep_end,
            None,
            None,
            None,
        );

        let message = rx.recv().expect("cache-only hit should emit thumbnail");
        assert!(message.image.is_some());
        assert!(message.origin.from_cache());
    }

