    /// 単一ラッパー本のピン: 本の中で set される「実効 prefix キー」のピンが、親階層の
    /// ZipDir セルが引く「literal prefix キー」へ alias 登録される (レビュー P2:
    /// set/lookup キー不一致の根治)。
    #[test]
    fn folder_pin_map_aliases_effective_prefix_for_wrapper_book() {
        let mut app = setup_app();
        let zip_path = std::path::PathBuf::from(r"C:\test\outer.zip");
        app.current_folder = Some(zip_path.clone());

        // bookB はラッパー (bookB/only/ に実体)。本の中で P したときの set キーは
        // 実効 prefix の合成キー (pin_container_key 相当)。
        app.zip_nav = Some(test_zip_nav(&["bookA/p1.jpg", "bookB/only/p1.jpg"]));
        let effective_key = zip_path.join("bookB").join("only");
        assert!(app.set_folder_thumb_pin(
            &effective_key,
            crate::folder_thumb_pins::FolderPinSource::ZipEntry {
                zip_rel: String::new(),
                entry: "bookB/only/p1.jpg".to_string(),
            },
        ));

        // root レベルを materialize → install で refresh_folder_pin_map が走る。
        let (items, metas) = {
            let nav = app.zip_nav.as_ref().unwrap();
            nav.materialize_current(crate::settings::SortOrder::FileName)
        };
        app.install_new_items(items, metas);

        // make_load_request が引く literal キー (zip_path + "bookB") でピンが引ける。
        let literal_norm = crate::path_key::normalize_keep_drive(&zip_path.join("bookB"));
        assert!(
            app.folder_pin_map.contains_key(&literal_norm),
            "実効キーのピンが literal キーへ alias 登録される: {:?}",
            app.folder_pin_map.keys().collect::<Vec<_>>()
        );
    }

    #[test]
    fn metadata_terminal_folder_pin_targets_share_current_book_and_zipdir_alias_rules() {
        let mut app = setup_app();
        let zip_path = std::path::PathBuf::from(r"C:\test\outer.zip");
        app.current_folder = Some(zip_path.clone());
        app.zip_nav = Some(test_zip_nav(&["bookA/p1.jpg", "bookB/only/p1.jpg"]));
        let (items, metas) = {
            let nav = app.zip_nav.as_ref().unwrap();
            nav.materialize_current(crate::settings::SortOrder::FileName)
        };
        app.install_new_items(items, metas);

        app.begin_metadata_import_terminal_refresh();
        while !app.advance_metadata_import_terminal_refresh(Path::new(r"C:\test"), false, false) {}
        let requests = app.take_metadata_import_refresh_requests();
        assert_eq!(requests.len(), 1);
        let request = &requests[0];
        let effective = crate::path_key::normalize_keep_drive(&zip_path.join("bookB").join("only"));
        let literal = crate::path_key::normalize_keep_drive(&zip_path.join("bookB"));

        assert!(
            request.folder_pin_paths.iter().any(|path| {
                crate::path_key::normalize_keep_drive(path)
                    == crate::path_key::normalize_keep_drive(&zip_path)
            }),
            "current ZIP book itself must be included"
        );
        assert!(
            request
                .items
                .iter()
                .filter_map(|item| item.container_path.as_deref())
                .any(|path| crate::path_key::normalize_keep_drive(path) == effective)
        );
        assert!(
            request.folder_pin_aliases.contains(&(literal, effective)),
            "terminal refresh must use the same literal/effective ZipDir alias"
        );
    }

    /// 階層 re-materialize のサムネ再利用キー: ZipDir は representative 込みで同一視する。
    /// dir_prefix だけで同一視すると、ソート変更 (apply_sort_change_reload →
    /// zip_nav_show_current_level) で代表画像が変わっても旧 Loaded サムネが移植されて
    /// 表紙が古いまま残る (Codex P2)。
    #[test]
    fn zip_level_thumb_reuse_key_distinguishes_representative_change() {
        use crate::grid_item::GridItem;
        let zip_path = std::path::PathBuf::from(r"C:\test\outer.zip");
        let zipdir = |rep: Option<&str>| GridItem::ZipDir {
            zip_path: zip_path.clone(),
            dir_prefix: "book/".to_string(),
            is_archive: false,
            representative: rep.map(|s| s.to_string()),
        };

        // 同じ dir_prefix でも代表が違えばキー不一致 (= Pending に戻して新代表で読み直す)。
        let asc = zip_level_thumb_reuse_key(&zipdir(Some("book/a.jpg"))).unwrap();
        let desc = zip_level_thumb_reuse_key(&zipdir(Some("book/z.jpg"))).unwrap();
        assert_ne!(asc, desc, "代表画像が変わったら再利用しない");

        // 代表が同じなら一致 (= ソート変更でも代表が変わらない本は再利用される)。
        assert_eq!(
            zip_level_thumb_reuse_key(&zipdir(Some("book/a.jpg"))).unwrap(),
            asc
        );

        // ZipImage とはキー空間を型タグで分離 ('#' を含む entry 名との衝突防止):
        // ZipDir("book/", rep "a.jpg") と entry "book/#a.jpg" が同一キーにならない。
        let img = GridItem::ZipImage {
            zip_path,
            entry_name: "book/#a.jpg".to_string(),
        };
        assert_ne!(zip_level_thumb_reuse_key(&img).unwrap(), asc);
    }

    #[test]
    fn zip_level_rematerialize_preserves_pinned_edit_preview_identity() {
        let mut app = setup_app();
        let zip_path = PathBuf::from(r"C:\test\outer.zip");
        app.current_folder = Some(zip_path);
        app.zip_nav = Some(test_zip_nav(&[
            "bookA/page1.jpg",
            "bookA/page2.jpg",
            "bookB/page1.jpg",
        ]));
        app.zip_nav_show_current_level();
        let idx = app
            .items
            .iter()
            .position(|item| {
                matches!(
                    item,
                    GridItem::ZipDir { dir_prefix, .. } if dir_prefix == "bookA/"
                )
            })
            .expect("bookA ZipDir");
        let reuse_key = zip_level_thumb_reuse_key(&app.items[idx]).unwrap();

        let ctx = egui::Context::default();
        let tex = ctx.load_texture(
            "zip-preview-reuse",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            Default::default(),
        );
        app.thumbnails[idx] = ThumbnailState::Loaded {
            tex,
            from_cache: false,
            from_edit_preview: true,
            rendered_at_px: 128,
            source_dims: Some((1, 1)),
            layout_dims: None,
        };
        let preview_key = "c:/test/outer.zip::book/page1.jpg".to_owned();
        app.thumb_edit_preview_keys.insert(idx, preview_key.clone());

        app.zip_nav_show_current_level();

        let restored_idx = app
            .items
            .iter()
            .position(|item| zip_level_thumb_reuse_key(item).as_deref() == Some(reuse_key.as_str()))
            .expect("same ZipDir after rematerialize");

        assert!(matches!(
            app.thumbnails[restored_idx],
            ThumbnailState::Loaded {
                from_edit_preview: true,
                ..
            }
        ));
        assert_eq!(
            app.thumb_edit_preview_keys.get(&restored_idx),
            Some(&preview_key)
        );
    }

