    /// 非表示 Raster PDF の display-fit レンダに AI を流すと native 再レンダで捨てるため、
    /// native 着地まで AI 先読みを保留する。
    /// `pdf_prefetch_should_defer_ai` は should_native と違いズーム / in-flight を見ず、
    /// 「cur が native と異なる間」true を返す (native 再レンダ中も保留継続)。
    #[test]
    fn pdf_prefetch_defers_ai_until_native() {
        use crate::ai::ModelKind;
        use crate::ai::upscale::AiProcessSizeLimit;
        use crate::grid_item::GridItem;
        use crate::settings::AiFeatureMode;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.settings.ai_feature_mode = AiFeatureMode::HighQuality;
        app.settings.ai_upscale_size_limit = Some(AiProcessSizeLimit::square(2048));
        app.settings.ai_denoise_size_limit = Some(AiProcessSizeLimit::square(2048));
        app.settings.global_preset.upscale_model = None;
        app.settings.global_preset.denoise_model = None;

        app.items.push(GridItem::PdfPage {
            pdf_path: std::path::PathBuf::from("c:/p/doc.pdf"),
            page_num: 0,
            content_type: Some(crate::pdf_loader::PdfPageContentType::Raster { w: 100, h: 200 }),
        });
        let idx = app.items.len() - 1;
        // 先読みページなので fs_zoom は無関係 (= ズーム中でも保留判定は変わらない)。
        app.fs_zoom = 3.0;

        let dummy_tex = ctx.load_texture(
            "pdf_prefetch_dummy",
            egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]),
            egui::TextureOptions::LINEAR,
        );
        let set_cur = |app: &mut App, w: usize, h: usize, tex: &egui::TextureHandle| {
            let px = egui::ColorImage::new([w, h], vec![egui::Color32::WHITE; w * h]);
            app.fs_cache.insert(
                idx,
                FsCacheEntry::Static {
                    tex: tex.clone(),
                    pixels: std::sync::Arc::new(px),
                    source_dims: None,
                    load_seq: 0,
                    animation: crate::fs_animation::StaticAnimationState::Still,
                },
            );
        };

        // 4096px 相当 (100x4000) + AI なし: 保留しない (= 通常どおり先読み。AI も走らないが)。
        set_cur(&mut app, 100, 4000, &dummy_tex);
        assert!(!app.pdf_prefetch_should_defer_ai(idx));

        // アップスケール ON: 4096px に AI を流さず native 着地まで保留。
        app.settings.global_preset.upscale_model = Some("auto".to_string());
        assert!(app.pdf_prefetch_should_defer_ai(idx));

        // viewport-fit が native より小さい場合も、捨てられる AI 先読みを保留する。
        set_cur(&mut app, 50, 100, &dummy_tex);
        assert!(app.pdf_prefetch_should_defer_ai(idx));
        set_cur(&mut app, 100, 4000, &dummy_tex);

        // 高負荷上限 (4096) でも cur (100x4000) > native → 保留して native へ落とす (P2)。
        app.settings.ai_upscale_size_limit = Some(AiProcessSizeLimit::square(4096));
        assert!(app.pdf_prefetch_should_defer_ai(idx));
        app.settings.ai_upscale_size_limit = Some(AiProcessSizeLimit::square(2048));

        // デノイズだけでも保留。
        app.settings.global_preset.upscale_model = None;
        app.settings.global_preset.denoise_model =
            Some(ModelKind::DenoiseRealplksr.as_str().to_string());
        assert!(app.pdf_prefetch_should_defer_ai(idx));

        // native 着地で保留解除。
        set_cur(&mut app, 100, 200, &dummy_tex);
        assert!(!app.pdf_prefetch_should_defer_ai(idx));
    }

    /// Ctrl+E / Ctrl+S は、再計算したペアではなく直近に描画された見開きレイアウトを
    /// 優先する。これで「画面は見開きなのに保存対象は片側ページ」のずれを防ぐ。
    #[test]
    fn open_export_dialog_prefers_visible_spread_layout() {
        use crate::grid_item::GridItem;
        use crate::settings::SpreadMode;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/a.jpg")));
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/p/b.jpg")));
        app.visible_indices = vec![1];
        app.thumbnails.push(ThumbnailState::Pending);
        app.thumbnails.push(ThumbnailState::Pending);
        let left_pixels = egui::ColorImage::new([1, 1], vec![egui::Color32::RED]);
        let right_pixels = egui::ColorImage::new([1, 1], vec![egui::Color32::BLUE]);
        app.fs_cache.insert(
            0,
            FsCacheEntry::Static {
                tex: ctx.load_texture(
                    "export_visible_spread_left",
                    left_pixels.clone(),
                    egui::TextureOptions::LINEAR,
                ),
                pixels: std::sync::Arc::new(left_pixels),
                source_dims: None,
                load_seq: 0,
                animation: crate::fs_animation::StaticAnimationState::Still,
            },
        );
        app.fs_cache.insert(
            1,
            FsCacheEntry::Static {
                tex: ctx.load_texture(
                    "export_visible_spread_right",
                    right_pixels.clone(),
                    egui::TextureOptions::LINEAR,
                ),
                pixels: std::sync::Arc::new(right_pixels),
                source_dims: None,
                load_seq: 0,
                animation: crate::fs_animation::StaticAnimationState::Still,
            },
        );
        app.fullscreen_idx = Some(1);
        app.spread_mode = SpreadMode::Ltr;
        app.fullscreen_page_layout
            .begin(crate::displayed_image_transform::FullscreenPageLayoutKind::Spread);
        for (idx, min) in [(0, egui::Pos2::ZERO), (1, egui::pos2(10.0, 0.0))] {
            let rect = egui::Rect::from_min_size(min, egui::vec2(10.0, 10.0));
            let transform = crate::displayed_image_transform::DisplayedImageTransform::resolve(
                crate::displayed_image_transform::DisplayedImageTransformInput {
                    pixel_fit: crate::displayed_image_transform::RectPixelFit::Texels,
                    page_idx: idx,
                    viewport_rect: rect,
                    source_size: egui::vec2(10.0, 10.0),
                    texture_size: egui::vec2(10.0, 10.0),
                    rotation: crate::rotation_db::Rotation::None,
                    free_rotation_rad: 0.0,
                    content_bbox: None,
                    fit_mode: crate::settings::FullscreenFitMode::Page,
                    fit_scale_limits:
                        crate::displayed_image_transform::FullscreenFitScaleLimits::default(),
                    pixels_per_point: 1.0,
                    placement: crate::displayed_image_transform::ResolvedDisplayPlacement::Normal {
                        zoom_pan: None,
                    },
                },
            )
            .unwrap();
            app.fullscreen_page_layout.push(transform);
        }

        app.open_export_dialog_for_current(&ctx, 1);

        let state = app.export_dialog.take().expect("export dialog should open");
        assert!(matches!(
            state.source,
            crate::export_dialog::ExportSource::RenderedSpread
        ));
        match state.pixels {
            crate::export_dialog::ExportPixels::Spread { left, right } => {
                assert_eq!(left.base_pixels.pixels[0], egui::Color32::RED);
                assert_eq!(right.base_pixels.pixels[0], egui::Color32::BLUE);
            }
            crate::export_dialog::ExportPixels::Single(_) => {
                panic!("visible spread layout should snapshot both pages")
            }
        }
    }

    /// Ctrl+E の「元の場所」は、前回保存先を既定表示している場合でも
    /// 元ファイル / 元 PDF のあるフォルダへ戻せる。
    #[test]
    fn export_dialog_can_reset_output_dir_to_source_dir() {
        use crate::grid_item::GridItem;
        let ctx = egui::Context::default();
        let temp = tempfile::tempdir().unwrap();
        let source_dir = temp.path().join("source");
        let last_dir = temp.path().join("last");
        std::fs::create_dir_all(&source_dir).unwrap();
        std::fs::create_dir_all(&last_dir).unwrap();

        let mut app = setup_app();
        let image_path = source_dir.join("a.jpg");
        app.items.push(GridItem::Image(image_path));
        app.visible_indices = vec![0];
        app.thumbnails.push(ThumbnailState::Pending);
        let pixels = egui::ColorImage::new([1, 1], vec![egui::Color32::WHITE]);
        app.fs_cache.insert(
            0,
            FsCacheEntry::Static {
                tex: ctx.load_texture(
                    "export_source_dir_reset",
                    pixels.clone(),
                    egui::TextureOptions::LINEAR,
                ),
                pixels: std::sync::Arc::new(pixels),
                source_dims: None,
                load_seq: 0,
                animation: crate::fs_animation::StaticAnimationState::Still,
            },
        );
        app.fullscreen_idx = Some(0);
        app.settings.export_last_directory = Some(last_dir.clone());

        app.open_export_dialog_for_current(&ctx, 0);

        let mut state = app.export_dialog.take().expect("export dialog should open");
        assert_eq!(state.output_dir_text, last_dir.display().to_string());
        state.reset_output_dir_to_source_dir();
        assert_eq!(state.output_dir_text, source_dir.display().to_string());
    }

    /// 一括エクスポートは選択の中から書き出せる物だけを取り、残りを件数で返す。
    /// 黙って落とすとユーザーは「N 件選んだのに M 件しか出ない」で理由を失う。
