    /// 後続バッチは、**入力を待たずに**始まる。
    ///
    /// worker が結果を送るだけで画面を起こしていなかったので、残りのバッチは次に UI が
    /// 動くまで始まらなかった。フォルダーを開き直しても 9 種類目以降の候補が古いままに
    /// なる (v3.5.0 レビュー Q02)。完了で起こし、受け取った frame でそのまま次へ進む。
    #[test]
    fn a_finished_prewarm_batch_wakes_the_ui_and_starts_the_next_one() {
        use crate::grid_item::GridItem;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        for extension in [
            "jpg", "png", "gif", "bmp", "tif", "avif", "heic", "jxl", "webp", "jpeg",
        ] {
            app.items
                .push(GridItem::Image(std::path::PathBuf::from(format!(
                    "c:/trip/a.{extension}"
                ))));
            app.thumbnails.push(ThumbnailState::Pending);
        }

        // 先に画面を静止させる。
        for _ in 0..8 {
            if !ctx.has_requested_repaint() {
                break;
            }
            let _ = ctx.run(Default::default(), |_| {});
        }
        assert!(!ctx.has_requested_repaint(), "ここでは静止している");

        app.poll_association_handler_prewarm(&ctx);
        let queued_after_first = app.association_prewarm_queue.len();
        assert!(queued_after_first > 0, "残りがある");

        // 完了が画面を起こす。ここを起こさないと、残りは次の入力まで始まらない。
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        while !ctx.has_requested_repaint() {
            assert!(
                std::time::Instant::now() < deadline,
                "完了が画面を起こさない"
            );
        }

        // 起きた frame の poll が、受け取ってそのまま次のバッチを始める。
        app.poll_association_handler_prewarm(&ctx);
        assert!(
            app.association_prewarm.is_some(),
            "受け取った frame で次のバッチが始まる"
        );
        assert!(
            app.association_prewarm_queue.len() < queued_after_first,
            "残りが減っている"
        );
    }

    /// 9 種類目以降の拡張子も、**いつかは並べ直される**。
    ///
    /// 1 バッチの上限で打ち切っていたので、9 種類目以降はフォルダーを開き直しても更新
    /// されず、一度覚えた古い候補や失敗して覚えた空が終了まで残った (v3.5.0 レビュー N05)。
    #[test]
    fn every_extension_in_the_folder_eventually_gets_re_enumerated() {
        use crate::grid_item::GridItem;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let extensions = [
            "jpg", "png", "gif", "bmp", "tif", "avif", "heic", "jxl", "webp", "jpeg",
        ];
        for extension in extensions {
            app.items
                .push(GridItem::Image(std::path::PathBuf::from(format!(
                    "c:/trip/a.{extension}"
                ))));
            app.thumbnails.push(ThumbnailState::Pending);
        }

        // 1 バッチ目。
        app.poll_association_handler_prewarm(&ctx);
        assert!(app.association_prewarm.is_some());
        let after_first = app.association_prewarm_queue.len();
        assert!(
            after_first > 0,
            "1 バッチで全部は処理しない (打ち切らずに残す)"
        );

        // 実行中は次のバッチを始めない。
        app.poll_association_handler_prewarm(&ctx);
        assert_eq!(app.association_prewarm_queue.len(), after_first);

        // 完了させて続きへ。最終的に全部が処理される。
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(20);
        while !app.association_prewarm_queue.is_empty() || app.association_prewarm.is_some() {
            assert!(std::time::Instant::now() < deadline, "列挙が終わらない");
            app.poll_association_handler_prewarm(&ctx);
        }

        assert!(app.association_prewarm_queue.is_empty());
    }

    /// 準備は**フォルダーごとに 1 回**。毎フレーム worker を作らない。
    #[test]
    fn the_association_prewarm_runs_once_per_folder_load() {
        use crate::grid_item::GridItem;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.items
            .push(GridItem::Image(std::path::PathBuf::from("c:/trip/a.jpg")));
        app.thumbnails.push(ThumbnailState::Pending);

        app.poll_association_handler_prewarm(&ctx);
        let first = app.association_prewarm_generation;
        assert_eq!(first, Some(app.items_generation));

        // 同じ世代では作り直さない。
        app.association_prewarm = None;
        app.poll_association_handler_prewarm(&ctx);
        assert!(
            app.association_prewarm.is_none(),
            "同じフォルダーで列挙を作り直さない"
        );
    }

    /// Ctrl+E を押したフレームでは、**編集内容をまだ読んでいない**。
    ///
    /// 隠蔽 / 消しゴムのマスクは圧縮 payload の展開を伴い、補正レイヤーと注釈フォントも
    /// 読み込みが要る。選択件数ぶんをダイアログを出す前にまとめて読んでいたので、多数の
    /// ページに編集を付けて一覧から Ctrl+E を押すと、その間 UI が止まりキャンセルもできな
    /// かった (v3.5.0 レビュー F04)。対象を並べるのは安い判定だけにする。
    #[test]
    fn opening_the_batch_export_dialog_does_not_read_any_page_edits_yet() {
        use crate::grid_item::GridItem;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        for name in ["a.jpg", "b.jpg", "c.jpg"] {
            app.items
                .push(GridItem::Image(std::path::PathBuf::from(format!(
                    "c:/trip/{name}"
                ))));
            app.thumbnails.push(ThumbnailState::Pending);
        }
        app.items.push(GridItem::Video(std::path::PathBuf::from(
            "c:/trip/clip.mp4",
        )));
        app.thumbnails.push(ThumbnailState::Pending);
        app.visible_indices = vec![0, 1, 2, 3];
        app.checked = [0usize, 1, 2, 3].into_iter().collect();

        app.open_export_batch_dialog(&ctx);

        let state = app
            .export_batch_dialog
            .as_ref()
            .expect("ダイアログは即座に開く");
        assert_eq!(state.total, 3, "書き出せる 3 件を対象にする");
        assert_eq!(state.skipped, 1, "動画は安い判定で除外する");
        assert!(
            state.items.is_empty(),
            "押したフレームでは 1 件も読んでいない"
        );
        assert_eq!(state.pending.len(), 3, "読み出しは後続フレームへ回す");
    }

    /// 準備中に一覧が並び替わっても、**選んだファイルが出る**。
    ///
    /// 対象を一覧 index だけで覚えていたので、複数フレームに分けた準備の途中で外部監視の
    /// 再読込が入ると、残りの index が別のファイルを指した。選んでいないファイルが出力
    /// されたり、同じファイルが二度入ったりする (v3.5.0 レビュー R04)。
    #[test]
    fn a_batch_export_target_survives_the_list_being_reordered_while_preparing() {
        use crate::grid_item::GridItem;
        let ctx = egui::Context::default();
        let mut app = setup_app();
        for name in ["a.jpg", "b.jpg"] {
            app.items
                .push(GridItem::Image(std::path::PathBuf::from(format!(
                    "c:/trip/{name}"
                ))));
            app.thumbnails.push(ThumbnailState::Pending);
        }
        app.visible_indices = vec![0, 1];
        app.checked = [0usize, 1].into_iter().collect();

        app.open_export_batch_dialog(&ctx);

        // 外部監視の再読込で先頭に別ファイルが入り、選んだ 2 件が後ろへずれる。
        app.items.insert(
            0,
            GridItem::Image(std::path::PathBuf::from("c:/trip/new.jpg")),
        );
        app.thumbnails.insert(0, ThumbnailState::Pending);

        let mut state = app.export_batch_dialog.take().expect("開いている");
        while state.preparing() {
            app.advance_export_batch_preparation_for_test(&mut state);
        }

        let names = state
            .items
            .iter()
            .map(|item| item.filename.as_str())
            .collect::<Vec<_>>();
        assert_eq!(names, vec!["a", "b"], "選んだ 2 件がそのまま出る");
    }

