    #[test]
    fn deferring_page_turn_work_cancels_producers_but_preserves_resident_results() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let resident_idx = push_image(&mut app, r"C:\pics\resident.png");
        let pending_idx = push_image(&mut app, r"C:\pics\pending.png");
        let resident_pixels = Arc::new(egui::ColorImage::filled([2, 2], egui::Color32::LIGHT_BLUE));
        let resident_tex = ctx.load_texture(
            "page_turn_resident",
            (*resident_pixels).clone(),
            egui::TextureOptions::LINEAR,
        );
        app.fs_cache.insert(
            resident_idx,
            FsCacheEntry::Static {
                tex: resident_tex,
                pixels: Arc::clone(&resident_pixels),
                source_dims: Some([2, 2]),
                load_seq: 1,
                animation: crate::fs_animation::StaticAnimationState::Still,
            },
        );

        let (_fs_tx, fs_rx) = std::sync::mpsc::channel();
        let fs_cancel = Arc::new(AtomicBool::new(false));
        let input_seq = app.input_seq;
        app.fs_pending.insert(
            pending_idx,
            FsPendingValue::new(
                Arc::clone(&fs_cancel),
                fs_rx,
                input_seq,
                FsLoadPurpose::for_page(true),
            ),
        );
        app.fs_upload_backlog.push(FsUploadResult::new(
            pending_idx,
            FsLoadResult::Failed,
            input_seq,
            FsLoadPurpose::for_page(true),
        ));

        let ai_key = FinalAiKey {
            edit_key: dummy_edit_key(&app, pending_idx),
            color_ai_hash: 1,
            bg: 0,
        };
        let (ai_pending, ai_cancel) = make_fake_final_ai_pending();
        app.final_ai_pending.insert(ai_key, ai_pending);

        let effect_key = FinalCompositeKey {
            edit_key: dummy_edit_key(&app, pending_idx),
            params_hash: 1,
            bg: 0,
        };
        let effect_cancel = Arc::new(AtomicBool::new(false));
        let (_effect_tx, effect_rx) = std::sync::mpsc::channel();
        let items_generation = app.items_generation;
        app.final_effect_pending.insert(
            effect_key,
            FinalEffectPending {
                cancel: Arc::clone(&effect_cancel),
                rx: effect_rx,
                items_generation,
                output_complete: true,
                nearest_sampler: false,
                prefetch: false,
            },
        );

        app.defer_page_turn_full_resolution_work();

        assert!(fs_cancel.load(Ordering::Relaxed));
        assert!(ai_cancel.load(Ordering::Relaxed));
        assert!(effect_cancel.load(Ordering::Relaxed));
        assert!(app.fs_pending.is_empty());
        assert!(app.final_ai_pending.is_empty());
        assert!(app.final_effect_pending.is_empty());
        assert!(app.fs_cache.contains_key(&resident_idx));
        assert_eq!(app.fs_upload_backlog.len(), 1);
    }

    #[test]
    fn materialized_page_turn_polls_target_final_effect_but_leaves_prefetch_result() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let target_idx = push_image(&mut app, r"C:\pics\target-final-effect.png");
        let prefetch_idx = push_image(&mut app, r"C:\pics\prefetch-final-effect.png");
        app.fullscreen_idx = Some(target_idx);
        app.fs_holdover_tex = Some(FsHoldover::NavigationSequence(FsNavigationSequence {
            previous: None,
            opened_at: std::time::Instant::now(),
            target: FsNavigationSequenceTarget::Display(FsNavigationDisplayTarget {
                items_generation: app.items_generation,
                pages: vec![target_idx],
                phase: FsNavigationTargetPhase::Awaiting {
                    accept_rendition: true,
                },
            }),
        }));

        let mut senders = Vec::new();
        let items_generation = app.items_generation;
        for idx in [target_idx, prefetch_idx] {
            let key = FinalCompositeKey {
                edit_key: dummy_edit_key(&app, idx),
                params_hash: 1,
                bg: 0,
            };
            let (tx, rx) = std::sync::mpsc::channel();
            tx.send(FinalCompositeResult::Cancelled).unwrap();
            senders.push(tx);
            app.final_effect_pending.insert(
                key,
                FinalEffectPending {
                    cancel: Arc::new(AtomicBool::new(false)),
                    rx,
                    items_generation,
                    output_complete: true,
                    nearest_sampler: false,
                    prefetch: idx != target_idx,
                },
            );
        }

        app.poll_final_effects(&ctx);

        assert!(
            app.final_effect_pending
                .keys()
                .all(|key| key.edit_key.idx != target_idx),
            "materialized target result must be consumed"
        );
        assert!(
            app.final_effect_pending
                .keys()
                .any(|key| key.edit_key.idx == prefetch_idx),
            "non-target result must remain deferred"
        );
    }

