    #[test]
    fn external_folder_change_clears_retained_final_ai_cache() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let folder = app.tmp.path().join("external_refresh");
        std::fs::create_dir_all(&folder).unwrap();
        let first_image = folder.join("a.png");
        std::fs::write(&first_image, b"old").unwrap();
        let initial_sig = signature_from_scan(&scan_directory(&folder));

        app.current_folder = Some(folder.clone());
        app.current_folder_last_mtime = Some(std::time::SystemTime::UNIX_EPOCH);
        app.current_folder_signature = Some(initial_sig);
        app.items = vec![GridItem::Image(first_image.clone())];
        app.thumbnails = vec![ThumbnailState::Pending];

        let key = FinalAiKey {
            edit_key: EditResultKey {
                item_id: app.item_id(0),
                items_generation: 0,
                idx: 0,
                source_gen: 0,
                erase_mask_gen: 0,
                local_gen: 0,
                conceal_mask_gen: 0,
                conceal_gen: 0,
            },
            color_ai_hash: 42,
            bg: 0,
        };
        app.insert_retained_final_ai(
            0,
            key,
            [1, 1],
            Arc::new(egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK])),
        );
        assert!(
            !app.retained_final_ai_cache.is_empty(),
            "test setup must populate retained cache"
        );

        std::fs::write(folder.join("b.png"), b"new").unwrap();
        app.check_external_folder_changes(&ctx, crate::app::ExternalChangeCheck::Resumed);
        // 走査は worker に出る。結果が着くまで poll する (UI スレッドで読まない、F14)。
        crate::app::tests::phase_c_support::wait_for_external_rescan(&mut app);

        assert!(
            app.retained_final_ai_cache.is_empty(),
            "external folder refresh must not reuse retained AI pixels for changed disk content"
        );
        assert!(
            app.items
                .iter()
                .any(|item| matches!(item, GridItem::Image(path) if path.ends_with("b.png"))),
            "external folder refresh must still install newly added files without media playback"
        );
    }

    /// AI 処理サイズ上限の変更 (`apply_ai_size_limit_change`) は final AI cache /
    /// failed / live pending / final composite と旧 AI cache 系を全て無効化する
    /// (Codex P3)。サイズ上限はキャッシュ key に含まれないため、明示破棄しないと
    /// 旧判定での結果 (failed 含む) が残り続け、上限を上げても再処理されない。
    #[test]
    fn apply_ai_size_limit_change_invalidates_ai_caches() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.items = vec![GridItem::Image(PathBuf::from(r"C:\imgs\00.png"))];

        let edit_key = EditResultKey {
            item_id: crate::item_identity::ItemId::NONE,
            items_generation: 0,
            idx: 0,
            source_gen: 0,
            erase_mask_gen: 0,
            local_gen: 0,
            conceal_mask_gen: 0,
            conceal_gen: 0,
        };
        let base_key = FinalAiKey {
            edit_key,
            color_ai_hash: 0,
            bg: 0,
        };
        app.final_ai_cache.insert(
            base_key,
            FinalAiEntry {
                pixels: Arc::new(egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK])),
                used_upscale: true,
            },
        );
        app.insert_retained_final_ai(
            0,
            base_key,
            [1, 1],
            Arc::new(egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK])),
        );
        app.final_ai_failed.insert(FinalAiKey {
            color_ai_hash: 1,
            ..base_key
        });
        let (pending, final_cancel) = make_fake_final_ai_pending();
        app.final_ai_pending.insert(
            FinalAiKey {
                color_ai_hash: 2,
                ..base_key
            },
            pending,
        );

        let tex = ctx.load_texture(
            "size_limit_test",
            egui::ColorImage::filled([1, 1], egui::Color32::WHITE),
            egui::TextureOptions::LINEAR,
        );
        app.final_composite_cache.insert(
            FinalCompositeKey {
                edit_key,
                params_hash: 0,
                bg: 0,
            },
            FinalCompositeEntry {
                pixels: Arc::new(egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK])),
                texture: tex.clone(),
                complete: true,
            },
        );

        // 旧 AI 経路 (legacy cache) も無効化対象
        app.ai_upscale_cache.insert(
            (0, 0),
            crate::fs_animation::FsCacheEntry::Static {
                tex,
                pixels: Arc::new(egui::ColorImage::filled([1, 1], egui::Color32::WHITE)),
                source_dims: None,
                load_seq: 0,
                animation: crate::fs_animation::StaticAnimationState::Still,
            },
        );
        app.ai_upscale_failed.insert((1, 0));
        let legacy_cancel = Arc::new(std::sync::atomic::AtomicBool::new(false));
        let (_tx, rx) = std::sync::mpsc::channel::<crate::ai::upscale::UpscaleResult>();
        app.ai_upscale_pending
            .insert((2, 0), (Arc::clone(&legacy_cancel), rx));

        app.apply_ai_size_limit_change();

        assert!(app.final_ai_cache.is_empty(), "final_ai_cache cleared");
        assert!(
            app.retained_final_ai_cache.is_empty(),
            "retained final AI cache cleared"
        );
        assert!(app.final_ai_failed.is_empty(), "final_ai_failed cleared");
        assert!(app.final_ai_pending.is_empty(), "final_ai_pending cleared");
        assert!(
            final_cancel.load(std::sync::atomic::Ordering::Relaxed),
            "live final AI pending must be cancelled"
        );
        assert!(
            app.final_composite_cache.is_empty(),
            "final_composite_cache cleared"
        );
        assert!(app.ai_upscale_cache.is_empty(), "legacy AI cache cleared");
        assert!(app.ai_upscale_failed.is_empty(), "legacy AI failed cleared");
        assert!(
            app.ai_upscale_pending.is_empty(),
            "legacy AI pending drained"
        );
        assert!(
            legacy_cancel.load(std::sync::atomic::Ordering::Relaxed),
            "legacy pending must be cancelled"
        );
    }

