    #[test]
    fn passive_pointer_press_release_queues_activation_after_ready_frame() {
        let mut armed = false;
        assert!(!App::detached_passive_window_update_activation(
            true, 10, 9, &mut armed, true, true
        ));
        assert!(
            !armed,
            "the click that created the parked window must not arm activation"
        );

        assert!(!App::detached_passive_window_update_activation(
            true, 10, 10, &mut armed, true, false
        ));
        assert!(armed, "a post-park press arms activation");
        assert!(App::detached_passive_window_update_activation(
            true, 10, 10, &mut armed, false, true
        ));
        assert!(
            !armed,
            "release consumes the click so a failed activation needs a fresh press"
        );

        let mut missing_route_armed = false;
        assert!(!App::detached_passive_window_update_activation(
            false,
            10,
            10,
            &mut missing_route_armed,
            true,
            true
        ));
    }

    #[test]
    fn parked_live_egui_window_activates_only_on_click_release() {
        // ParkedLive audio windows have no native presenter, so they use the egui passive path.
        // That path intentionally has no key/wheel input channel: press arms, release restores.
        let mut armed = false;
        assert!(!App::detached_passive_window_update_activation(
            true, 1, 1, &mut armed, false, false
        ));
        assert!(!armed);

        assert!(!App::detached_passive_window_update_activation(
            true, 1, 1, &mut armed, true, false
        ));
        assert!(armed);
        assert!(App::detached_passive_window_update_activation(
            true, 1, 1, &mut armed, false, true
        ));
        assert!(!armed);
    }

    #[test]
    #[cfg(windows)]
    fn f12_on_audio_toggles_detached_viewer_mode() {
        // Stage AUDIO: 音声ファイルも動画と同じ 1 本のメディア窓で detached 表示できる。
        // F12 は no-op ではなく、通常モードのグローバル detached 設定を切り替えて音声 viewport
        // を main/detached 間で移動する。
        let mut app = setup_app();
        let audio = push_audio(&mut app, r"C:\music\a.flac");
        app.fullscreen_idx = Some(audio);
        app.viewer_presentation = ViewerPresentation::Fullscreen;

        app.toggle_detached_viewer_mode();

        assert!(app.settings.detached_viewer_enabled);
        assert_eq!(app.viewer_presentation, ViewerPresentation::DetachedWindow);
        assert_eq!(
            app.active_detached_session.map(|session| session.source),
            Some(DetachedSource::Audio)
        );

        app.toggle_detached_viewer_mode();

        assert!(!app.settings.detached_viewer_enabled);
        assert_eq!(
            app.viewer_presentation,
            app.non_detached_viewer_presentation()
        );
        assert!(
            app.active_detached_session.is_none(),
            "F12 OFF must close the audio detached session"
        );
    }

    fn insert_static_fs_entry(app: &mut App, ctx: &egui::Context, idx: usize, label: &str) {
        let pixels = egui::ColorImage::new([2, 1], vec![egui::Color32::WHITE; 2]);
        let tex = ctx.load_texture(label, pixels.clone(), egui::TextureOptions::LINEAR);
        app.fs_cache.insert(
            idx,
            FsCacheEntry::Static {
                tex,
                pixels: std::sync::Arc::new(pixels),
                source_dims: Some([2, 1]),
                load_seq: 0,
                animation: crate::fs_animation::StaticAnimationState::Still,
            },
        );
    }

    fn assert_rect_close(actual: egui::Rect, expected: egui::Rect) {
        let eps = 0.001;
        assert!(
            (actual.min.x - expected.min.x).abs() < eps
                && (actual.min.y - expected.min.y).abs() < eps
                && (actual.max.x - expected.max.x).abs() < eps
                && (actual.max.y - expected.max.y).abs() < eps,
            "actual={actual:?} expected={expected:?}"
        );
    }

    fn assert_frozen_background_white(background: &DetachedImageWindowFrozenBackground) {
        match background {
            DetachedImageWindowFrozenBackground::Solid(color) => {
                assert_eq!(*color, egui::Color32::WHITE)
            }
            _ => panic!("expected frozen page to preserve white transparent background"),
        }
    }

    fn test_zip_nav_for(zip_path: PathBuf, names: &[&str]) -> crate::zip_tree::ZipNavState {
        let entries: Vec<crate::zip_loader::ZipImageEntry> = names
            .iter()
            .map(|n| crate::zip_loader::ZipImageEntry {
                entry_name: n.to_string(),
                uncompressed_size: 0,
                mtime: 0,
            })
            .collect();
        let tree = std::sync::Arc::new(crate::zip_tree::ZipTree::build(zip_path, entries));
        crate::zip_tree::ZipNavState::new(tree)
    }

