    #[test]
    #[cfg(windows)]
    fn detached_video_audio_mode_f11_toggles_borderless_without_unhiding_presenter() {
        // DetachedWindow の動画→音声モードでも F11 は presentation 切替ではなく、detached 窓の
        // borderless 切替に寄せる。hidden presenter を show / SwitchPlacement するのは
        // exit_video_audio_mode だけの責務。
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let video = push_video(&mut app, r"C:\clips\a.mp4");
        app.fullscreen_idx = Some(video);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.begin_active_detached_session(11, DetachedSource::Video);
        app.video_audio_mode = Some(video);
        app.video_audio_vst = None;

        app.toggle_video_window_mode_for_input(&ctx);

        assert_eq!(app.video_audio_mode, Some(video));
        assert_eq!(app.viewer_presentation, ViewerPresentation::DetachedWindow);
        assert!(!app.video_presentation_transition.is_transitioning());
        assert_eq!(
            app.detached_viewer_borderless_transition
                .as_ref()
                .map(|t| t.target_borderless),
            Some(true)
        );

        app.detached_viewer_borderless_transition = Some(DetachedViewerBorderlessTransition {
            target_borderless: true,
            phase: DetachedViewerBorderlessTransitionPhase::Settle {
                until: std::time::Instant::now() - std::time::Duration::from_millis(1),
            },
        });
        app.step_detached_viewer_borderless_transition(&ctx);
        assert_eq!(
            app.video_audio_mode,
            Some(video),
            "audio mode must survive the borderless transition settle frame"
        );
        assert!(
            !app.video_presentation_transition.is_transitioning(),
            "settle must not issue a presenter placement switch while audio mode owns display"
        );
    }

    #[test]
    #[cfg(windows)]
    fn continuous_autoadvance_keeps_presentation_over_open_in_window_setting() {
        // 「画像・動画を別ウィンドウで開く」ON でも、連続再生の自動次送りでは直前の動画の
        // presentation を維持する (別ウィンドウのちらつきを出さない)。手動 open は従来どおり
        // 設定に従う (one-shot 未セット)。
        let mut app = setup_app();
        let video = push_video(&mut app, r"C:\clips\a.mp4");
        app.settings.detached_viewer_open_images_in_window = true;

        // one-shot 未セット (= ユーザー手動 open 相当) は設定どおり detached。
        assert_eq!(
            app.resolve_viewer_presentation_for_open(video, true),
            ViewerPresentation::DetachedWindow,
            "manual open keeps the open-in-separate-window setting behavior"
        );

        // 自動次送りの one-shot (直前が MainWindow) は MainWindow を維持し、消費される。
        app.fs_media_open_forced_presentation = Some(ViewerPresentation::MainWindow);
        assert_eq!(
            app.resolve_viewer_presentation_for_open(video, true),
            ViewerPresentation::MainWindow,
            "auto-advance keeps the previous presentation instead of re-opening detached"
        );
        assert!(
            app.fs_media_open_forced_presentation.is_none(),
            "the forced-presentation one-shot must be consumed"
        );

        // 直前が Detached なら Detached を維持する。
        app.fs_media_open_forced_presentation = Some(ViewerPresentation::DetachedWindow);
        assert_eq!(
            app.resolve_viewer_presentation_for_open(video, true),
            ViewerPresentation::DetachedWindow,
            "auto-advance keeps a detached previous presentation too"
        );
    }

