    #[test]
    #[cfg(windows)]
    fn bulk_parked_context_retire_cancels_work_without_close_fullscreen() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let cancel = Arc::new(AtomicBool::new(false));
        let context_cancel = Arc::clone(&cancel);
        let id = app.push_window_context_for_test(&ctx, 705, move |context| {
            install_context_fs_pending(context, context_cancel);
        });

        assert!(!cancel.load(Ordering::Relaxed));
        // This is the bulk teardown seam: it retires the at-rest bundle directly and deliberately
        // does not mount it or call close_fullscreen first.
        app.teardown_paused_media_bundles_for_window_ids(&[705], "test_bulk_context_retire");

        assert!(cancel.load(Ordering::Relaxed));
        assert_eq!(app.viewer_context_residence(id), ContextResidence::Retired);
        assert_eq!(app.locate_window_context(705), None);
        assert!(app.active_detached_session.is_none());
        // Killing mutation: skip the bound-window unbind in retire_context; the retired context
        // remains discoverable through window 705.
    }

    #[test]
    #[cfg(windows)]
    fn retiring_context_leaves_sibling_context_work_untouched() {
        let mut app = setup_app();
        let retiring_cancels = context_work_cancel_tokens();
        let sibling_cancels = context_work_cancel_tokens();
        let retiring_installed = retiring_cancels.clone();
        let sibling_installed = sibling_cancels.clone();
        let retiring = app.build_window_context_for_test(706, move |context| {
            install_all_context_work(context, &retiring_installed);
        });
        let sibling = app.build_window_context_for_test(707, move |context| {
            install_all_context_work(context, &sibling_installed);
        });

        app.retire_context(retiring, "test_context_work_sibling_isolation", |_| ())
            .expect("context should retire");

        assert!(
            retiring_cancels
                .iter()
                .all(|cancel| cancel.load(Ordering::Relaxed))
        );
        assert!(
            sibling_cancels
                .iter()
                .all(|cancel| !cancel.load(Ordering::Relaxed))
        );
        assert_eq!(
            app.viewer_context_residence(sibling),
            ContextResidence::AtRest
        );
    }

    #[test]
    #[cfg(windows)]
    fn detached_folder_pending_requests_are_cancelled_on_pause_and_drop() {
        fn nav_pending(cancel: Arc<AtomicBool>) -> FolderNavPending {
            let (_tx, rx) = mpsc::channel::<FolderNavThreadResult>();
            FolderNavPending {
                cancel,
                rx,
                forward: true,
                mode: FolderNavMode::Fullscreen,
            }
        }
        fn scan_pending(cancel: Arc<AtomicBool>) -> FolderPaneOpenPending {
            let (_tx, rx) = mpsc::channel::<std::io::Result<ScannedDir>>();
            FolderPaneOpenPending {
                path: PathBuf::from(r"C:\detached"),
                cancel,
                rx,
                purpose: FolderOpenScanPurpose::DetachedImage {
                    image_path: PathBuf::from(r"C:\detached\a.jpg"),
                },
            }
        }

        let pause_nav_cancel = Arc::new(AtomicBool::new(false));
        let pause_scan_cancel = Arc::new(AtomicBool::new(false));
        let mut paused = setup_app();
        paused.navigation_scope = ViewerNavigationScope::DetachedPhysical;
        paused.folder_nav_pending = Some(nav_pending(Arc::clone(&pause_nav_cancel)));
        paused.folder_pane_open_pending = Some(scan_pending(Arc::clone(&pause_scan_cancel)));
        paused.pending_folder_nav_steps = 3;
        paused.pending_folder_nav_mode = FolderNavMode::Fullscreen;

        paused.pause_mounted_background_work_keep_current_frame();

        assert!(pause_nav_cancel.load(Ordering::Relaxed));
        assert!(pause_scan_cancel.load(Ordering::Relaxed));
        assert!(paused.folder_nav_pending.is_none());
        assert!(paused.folder_pane_open_pending.is_none());
        assert_eq!(paused.pending_folder_nav_steps, 0);
        assert_eq!(paused.pending_folder_nav_mode.perf_tag(), "grid");

        let drop_nav_cancel = Arc::new(AtomicBool::new(false));
        let drop_scan_cancel = Arc::new(AtomicBool::new(false));
        paused.build_active_context_for_test(None, DetachedSource::Image, |context| {
            context.navigation_scope = ViewerNavigationScope::DetachedPhysical;
            context.folder_nav_pending = Some(nav_pending(Arc::clone(&drop_nav_cancel)));
            context.folder_pane_open_pending = Some(scan_pending(Arc::clone(&drop_scan_cancel)));
        });
        paused.remove_active_context_for_test();
        assert!(drop_nav_cancel.load(Ordering::Relaxed));
        assert!(drop_scan_cancel.load(Ordering::Relaxed));
    }

