    #[test]
    #[cfg(windows)]
    fn tray_residency_preserves_mounted_video_transport_and_session() {
        for (case, presentation) in [
            ("fullscreen", ViewerPresentation::Fullscreen),
            ("in_window", ViewerPresentation::MainWindow),
            ("f12", ViewerPresentation::DetachedWindow),
        ] {
            let mut app = setup_app();
            let path = app.tmp.path().join(format!("tray-{case}.mp4"));
            let video = push_video(&mut app, path.to_str().unwrap());
            app.fullscreen_idx = Some(video);
            app.selected = Some(video);
            app.viewer_presentation = presentation;
            if matches!(presentation, ViewerPresentation::DetachedWindow) {
                app.detached_viewer_window_id = Some(200);
            }
            install_playing_test_media(&mut app, video, path.clone(), 30.0);

            assert_eq!(app.prepare_media_session_for_tray_residency(), 1);
            assert_eq!(app.fullscreen_idx, Some(video));
            assert_eq!(app.viewer_presentation, presentation);
            assert_eq!(
                app.settings
                    .video_resume_positions
                    .get(&crate::adjustment_db::normalize_path(&path)),
                Some(&30.0)
            );

            let Some(FsCacheEntry::Video { player, .. }) = app.fs_cache.get(&video) else {
                unreachable!();
            };
            assert!(
                player.intent_playing(),
                "{case} transport must keep running"
            );
            assert_eq!(player.position(), 30.0, "{case} must remain in place");

            let ctx = egui::Context::default();
            app.window_visible = false;
            app.sync_after_restore(&ctx);
            let Some(FsCacheEntry::Video { player, .. }) = app.fs_cache.get(&video) else {
                unreachable!();
            };
            assert!(
                player.intent_playing(),
                "{case} restore must not synthesize pause/play"
            );
            assert_eq!(app.fullscreen_idx, Some(video));
        }
    }

    #[test]
    fn remote_session_acquire_pauses_local_progress_without_auto_resume() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let video_path = app.tmp.path().join("remote-session.mp4");
        let video = push_video(&mut app, video_path.to_str().unwrap());
        let animated = push_image(&mut app, "remote-session.gif");
        app.fullscreen_idx = Some(video);
        app.selected = Some(video);
        app.slideshow_playing = true;
        app.continuous_reading_scroll_transition =
            Some(ContinuousReadingScrollTransition::AwaitingReanchor {
                history_trigger: HistoryTrigger::AutoAdvance,
            });
        install_playing_test_media(&mut app, video, video_path, 17.5);
        let pixels = egui::ColorImage::filled([1, 1], egui::Color32::WHITE);
        let texture = ctx.load_texture(
            "remote_session_animation",
            pixels.clone(),
            egui::TextureOptions::LINEAR,
        );
        app.fs_cache.insert(
            animated,
            FsCacheEntry::Animated {
                frames: vec![(texture, 0.1)],
                frame_pixels: vec![std::sync::Arc::new(pixels)],
                current_frame: 0,
                playback: crate::fs_animation::AnimationPlayback::Playing { next_frame_at: 1.0 },
                load_seq: 0,
            },
        );

        let handle = crate::remote_ipc::session::SessionHandle::new();
        app.set_remote_session_handle(handle.clone());
        handle.acquire(mimageviewer_ipc::SessionAcquireRequest {
            client_id: "phone".to_owned(),
            peer: mimageviewer_ipc::SessionPeerInfo {
                connection_kind: mimageviewer_ipc::SessionConnectionKind::Direct,
                device_name: Some("phone".to_owned()),
            },
        });
        app.poll_remote_session(&ctx);

        assert_test_media_paused_at(&app, video, 17.5);
        assert!(!app.slideshow_playing);
        assert!(app.continuous_reading_scroll_transition.is_none());
        assert!(
            !app.fs_cache
                .get(&animated)
                .expect("animated entry stays cached")
                .animation_is_playing()
        );

        handle.local_disconnect();
        // 操作権返却そのものは transport へ Play を送らない。再開は利用者操作だけ。
        assert_test_media_paused_at(&app, video, 17.5);
        assert!(
            !app.fs_cache
                .get(&animated)
                .expect("animated entry stays cached")
                .animation_is_playing()
        );
    }

    /// 出力 worker が持つ借用は、リモートへ操作権を渡す前の静止確認に数えられる。
    ///
    /// 一括書き出しと外部ツールの実体化は消しゴム (MI-GAN) や AI 拡大を回し得るのに、
    /// この静止確認から漏れていた。消しゴム付きの出力中に接続すると、ローカル AI が
    /// 走ったまま操作権が移り、リモート側の AI と GPU / モデルを取り合う
    /// (v3.5.0 レビュー F09)。両 worker が借用を持つことは型で強制しているので、ここでは
    /// 借用そのものが障壁になることを固定する。
    #[test]
    fn a_local_output_worker_lease_holds_the_remote_acquire_barrier() {
        let mut app = setup_app();
        assert!(
            app.local_ai_remote_barrier_snapshot().is_quiesced(),
            "何も走っていなければ静止している"
        );

        let lease = app.local_ai_activity_lease();

        let barrier = app.local_ai_remote_barrier_snapshot();
        assert!(!barrier.is_quiesced(), "借用がある間は静止と見なさない");
        assert!(
            barrier.blocker_summary().contains("local_ai_activity"),
            "何が止めているかをログに出せる: {}",
            barrier.blocker_summary()
        );

        drop(lease);
        assert!(app.local_ai_remote_barrier_snapshot().is_quiesced());
    }

    #[test]
    fn remote_session_barriers_keep_modal_until_final_release() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let handle = crate::remote_ipc::session::SessionHandle::new();
        app.set_remote_session_handle(handle.clone());

        assert!(!app.remote_session_blocks_local_control());
        app.poll_remote_session(&ctx);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::Local
        );
        assert_eq!(handle.snapshot().acquisition_sequence, 0);
        assert_eq!(handle.snapshot().control_return_sequence, 0);

        let local_ai_activity = app.local_ai_activity_lease();
        handle.acquire(mimageviewer_ipc::SessionAcquireRequest {
            client_id: "phone".to_owned(),
            peer: mimageviewer_ipc::SessionPeerInfo {
                connection_kind: mimageviewer_ipc::SessionConnectionKind::Direct,
                device_name: Some("phone".to_owned()),
            },
        });
        assert!(app.remote_session_blocks_local_control());
        app.poll_remote_session(&ctx);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::AcquiringRemote,
            "remote work must wait for the local worker terminal lease"
        );
        drop(local_ai_activity);
        app.poll_remote_session(&ctx);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::RemoteActive
        );

        let control_before = handle.snapshot().control_return_sequence;
        handle.local_disconnect();
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::DrainingRemote
        );
        assert!(app.remote_session_blocks_local_control());
        assert_eq!(
            handle.snapshot().control_return_sequence,
            control_before,
            "drain start must not publish control return"
        );

        app.poll_remote_session(&ctx);
        let released = handle.snapshot();
        assert_eq!(
            released.phase,
            crate::remote_ipc::session::RemoteControlPhase::Local
        );
        assert_eq!(
            released.control_return_sequence,
            control_before.wrapping_add(1)
        );
        assert!(!app.remote_session_blocks_local_control());

        // A later frame must not observe the completed drain as another release/reload.
        app.poll_remote_session(&ctx);
        let after_later_poll = handle.snapshot();
        assert_eq!(after_later_poll.phase, released.phase);
        assert_eq!(
            after_later_poll.control_return_sequence,
            released.control_return_sequence
        );
    }

    #[test]
    fn streaming_drain_and_reacquire_between_frames_do_not_restore_local_view() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let image = push_image(&mut app, "coalesced-reacquire.png");
        app.fullscreen_idx = Some(image);
        let handle = crate::remote_ipc::session::SessionHandle::new();
        app.set_remote_session_handle(handle.clone());

        handle.acquire(mimageviewer_ipc::SessionAcquireRequest {
            client_id: "phone".to_owned(),
            peer: mimageviewer_ipc::SessionPeerInfo {
                connection_kind: mimageviewer_ipc::SessionConnectionKind::Direct,
                device_name: Some("phone".to_owned()),
            },
        });
        app.poll_remote_session(&ctx);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::RemoteActive
        );

        let owner = handle.owner_for_test("phone");
        let mut registration = handle
            .streaming_owner(&owner)
            .unwrap()
            .register_streaming()
            .unwrap();
        let worker_lease = registration.take_worker_lease();
        handle.local_disconnect();
        app.poll_remote_session(&ctx);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::DrainingRemote,
            "the app drain must wait for the streaming worker lease"
        );

        drop(registration);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::DrainingRemote,
            "the control registration is not the worker drain lease"
        );
        drop(worker_lease);
        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::Local
        );
        handle.acquire(mimageviewer_ipc::SessionAcquireRequest {
            client_id: "phone".to_owned(),
            peer: mimageviewer_ipc::SessionPeerInfo {
                connection_kind: mimageviewer_ipc::SessionConnectionKind::Direct,
                device_name: Some("phone".to_owned()),
            },
        });

        app.poll_remote_session(&ctx);

        assert_eq!(
            handle.snapshot().phase,
            crate::remote_ipc::session::RemoteControlPhase::RemoteActive
        );
        assert_eq!(
            app.fullscreen_idx,
            Some(image),
            "a control return that was never visible must not enqueue the old local restore"
        );
    }

    #[test]
    fn local_ai_remote_barrier_snapshot_names_every_closed_condition() {
        let snapshot = LocalAiRemoteBarrierSnapshot {
            mounted: MountedAiRemoteBarrierSnapshot {
                final_ai_pending: 2,
                erase_inpaint_pending: 1,
            },
            detached: Some(MountedAiRemoteBarrierSnapshot {
                final_ai_pending: 1,
                erase_inpaint_pending: 0,
            }),
            ai_upscale_pending: 3,
            retained_final_ai_orphans: 4,
            local_adjust_segmentation_pending: true,
            book_op_pending: true,
            local_ai_activity: 5,
            trt_restart_in_flight: true,
            video_upscale: Some(VideoUpscaleRemoteBarrierSnapshot {
                queue_paused: false,
                pause_requested: true,
                paused_idle: false,
            }),
        };

        assert!(!snapshot.is_quiesced());
        let blockers = snapshot.blocker_summary();
        for expected in [
            "mounted(final_ai_pending=2,erase_inpaint_pending=1)",
            "detached(final_ai_pending=1,erase_inpaint_pending=0)",
            "ai_upscale_pending=3",
            "retained_final_ai_orphans=4",
            "local_adjust_segmentation_pending",
            "book_op_pending",
            "local_ai_activity=5",
            "trt_restart_in_flight",
            "video_upscale(queue_paused=false,pause_requested=true,paused_idle=false)",
        ] {
            assert!(
                blockers.contains(expected),
                "missing {expected}: {blockers}"
            );
        }
    }

    #[test]
    fn disabled_legacy_ai_still_reaps_cancelled_pending_worker() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        app.ai_upscale_enabled = false;
        app.ai_denoise_model = None;
        let cancel = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(true));
        let (tx, rx) = std::sync::mpsc::channel();
        drop(tx);
        app.ai_upscale_pending.insert((1, 0), (cancel, rx));

        app.poll_ai_upscale(&ctx);

        assert!(app.ai_upscale_pending.is_empty());
        assert!(
            !app.ai_upscale_failed.contains(&(1, 0)),
            "barrier cancellation is not a processing failure"
        );
    }

