    #[test]
    fn image_only_detached_setting_parks_previous_window_as_independent() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let first = push_image(&mut app, r"C:\pics\a.jpg");
        let second = push_image(&mut app, r"C:\pics\b.jpg");
        insert_static_fs_entry(&mut app, &ctx, first, "always_new_first");
        app.settings.detached_viewer_open_images_in_window = true;
        app.fullscreen_idx = Some(first);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.fs_viewport_shown = true;
        app.fs_viewport_presentation = Some(ViewerPresentation::DetachedWindow);
        app.fs_open_intent_from_grid = true;
        let first_window_id = app.ensure_detached_viewer_window_id();
        assert_eq!(first_window_id, 1);
        app.begin_mounted_detached_session_for_test(first_window_id, DetachedSource::Image);

        app.open_fullscreen(second, crate::app::HistoryTrigger::UserChosen);

        assert_eq!(app.fullscreen_idx, Some(second));
        assert_eq!(app.viewer_presentation, ViewerPresentation::DetachedWindow);
        assert_eq!(app.detached_image_windows.len(), 1);
        assert_eq!(app.detached_image_windows[0].id, 1);
        assert_eq!(
            app.detached_window_manager
                .runtime(1)
                .map(|runtime| runtime.linked),
            Some(false),
            "always-new passive snapshots must be independent; linked snapshots are forbidden after CUT"
        );
        assert_eq!(app.detached_viewer_window_id, Some(2));
        assert!(!app.detached_viewer_recreate_on_next_render);
        assert!(!app.fs_viewport_shown);
        assert_eq!(app.locate_window_context(first_window_id), None);
        assert_eq!(
            app.active_detached_session.map(|session| session.window_id),
            Some(2),
            "always-new rebind must stop naming the parked window before releasing it"
        );
        assert!(app.locate_window_context(2).is_some());
        // Killing mutation: remove finish_active_detached_session_handoff before the old-window
        // unbind; the ownership-boundary assertion panics before window 2 can be bound.
    }

    #[test]
    fn auto_fullscreen_image_folder_always_new_parks_existing_detached_window() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let existing = push_image(&mut app, r"C:\pics\existing.jpg");
        insert_static_fs_entry(&mut app, &ctx, existing, "auto_folder_existing_window");
        app.settings.detached_viewer_open_images_in_window = true;
        app.settings.auto_fullscreen_zip_pdf = true;
        app.settings.auto_fullscreen_image_folders = true;
        app.fullscreen_idx = Some(existing);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.detached_viewer_independent_active = true;
        app.detached_viewer_window_id = Some(41);
        app.begin_mounted_detached_session_for_test(41, DetachedSource::Image);
        app.fs_viewport_shown = true;
        app.fs_viewport_presentation = Some(ViewerPresentation::DetachedWindow);

        let folder = app.tmp.path().join("auto_folder_always_new");
        std::fs::create_dir(&folder).unwrap();
        std::fs::write(folder.join("001.jpg"), b"dummy").unwrap();
        std::fs::write(folder.join("002.png"), b"dummy").unwrap();
        app.pending_auto_fs_open = true;

        app.load_folder(folder.clone());

        assert_eq!(app.current_folder.as_deref(), Some(folder.as_path()));
        assert_eq!(
            app.fullscreen_idx, None,
            "the auto-opened image viewer must not remain bundled with main"
        );
        assert_eq!(app.selected, Some(0));
        let (active_window_id, active_grid_intent) = app
            .with_active_viewer_context(|active| {
                assert_eq!(active.fullscreen_idx, Some(0));
                assert_eq!(
                    active.viewer_presentation,
                    ViewerPresentation::DetachedWindow
                );
                assert_eq!(
                    active.navigation_scope,
                    ViewerNavigationScope::DetachedPhysical
                );
                (
                    active.detached_viewer_window_id,
                    active.fs_open_intent_from_grid,
                )
            })
            .expect("the auto-opened image folder must own an active context");
        assert!(
            app.detached_viewer_focus_requested,
            "image-only folder auto-open is still an explicit grid open and should focus the newly active detached window"
        );
        assert_eq!(
            app.detached_image_windows.len(),
            1,
            "the previously active detached window should be preserved as passive"
        );
        assert_eq!(app.detached_image_windows[0].id, 41);
        assert_eq!(
            app.detached_image_windows[0].location_display,
            "existing.jpg"
        );
        assert_ne!(
            active_window_id,
            Some(41),
            "always-new auto-open must not reuse the previous detached viewport as continuation navigation"
        );
        assert!(
            active_window_id.is_some(),
            "a new active detached viewport should be allocated for the image-only folder"
        );
        assert!(
            !app.fs_open_intent_from_grid && !active_grid_intent,
            "open_fullscreen consumes the restored grid intent"
        );
    }

