    #[test]
    fn image_only_detached_plain_image_snapshot_can_reactivate() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let first = push_image(&mut app, r"C:\pics\a.jpg");
        let second = push_image(&mut app, r"C:\pics\b.jpg");
        insert_static_fs_entry(&mut app, &ctx, first, "reactivate_plain_first");
        insert_static_fs_entry(&mut app, &ctx, second, "reactivate_plain_second");
        app.settings.detached_viewer_open_images_in_window = true;
        app.fullscreen_idx = Some(first);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.detached_viewer_independent_active = true;
        app.panorama_state = Some(crate::panorama::PanoramaState::new(
            0.5,
            -0.25,
            crate::panorama::PanoProjection::Perspective,
        ));
        app.fs_viewport_shown = true;
        app.fs_viewport_presentation = Some(ViewerPresentation::DetachedWindow);
        app.fs_open_intent_from_grid = true;
        let initial_window_id = app.ensure_detached_viewer_window_id();
        app.begin_mounted_detached_session_for_test(initial_window_id, DetachedSource::Image);

        app.open_fullscreen(second, crate::app::HistoryTrigger::UserChosen);

        assert_eq!(app.fullscreen_idx, Some(second));
        assert_eq!(app.detached_image_windows.len(), 1);
        let first_window_id = app.detached_image_windows[0].id;
        assert!(
            app.detached_window_can_activate(app.detached_image_windows[0].id),
            "plain image snapshots must be able to become the active viewer again"
        );
        // findings-19: 通常画像の parked still にも Image フォールバック descriptor が
        // 付く。ただし後段の activation はスタンプ優先で従来どおり成功すること
        // (このテストの activate 成功 assert がその契約を固定する)。
        assert!(matches!(
            app.detached_image_windows[0].reopen_descriptor,
            Some(crate::app::ViewerContextDescriptor::Image { .. })
        ));
        assert!(app.detached_image_windows[0].reopen_sync_stamp.is_some());
        assert!(
            app.panorama_state.is_none(),
            "opening the follow-up window should still reset foreground panorama mode"
        );
        let second_window_id = app
            .detached_viewer_window_id
            .expect("second detached window should be active");
        assert_ne!(first_window_id, second_window_id);
        app.detached_window_hwnd_set(second_window_id, 0x2222);
        app.transition_detached_window_state(
            second_window_id,
            DetachedWindowState::Active,
            "test_active_switch_second",
        );
        app.detached_viewer_host_generation = 17;

        assert!(app.activate_detached_image_window_snapshot(&ctx, first_window_id));

        assert_eq!(app.fullscreen_idx, Some(first));
        assert_eq!(app.viewer_presentation, ViewerPresentation::DetachedWindow);
        assert_eq!(app.detached_viewer_window_id, Some(first_window_id));
        assert!(
            app.detached_viewer_independent_active,
            "always-new detached image windows remain independent after reactivation"
        );
        assert!(
            app.panorama_state.is_none(),
            "reactivated plain image windows should return in normal display mode so V can start panorama anew"
        );
        assert_eq!(app.detached_image_windows.len(), 1);
        assert_eq!(app.detached_image_windows[0].location_display, "b.jpg");
        assert!(app.detached_window_can_activate(app.detached_image_windows[0].id));
        assert_eq!(app.detached_image_windows[0].id, second_window_id);
        assert_eq!(
            app.detached_window_state(second_window_id),
            Some(DetachedWindowState::Parked),
            "switching active still windows must park the previous active window in place"
        );
        assert_eq!(
            app.detached_window_hwnd_raw_for_window_id(second_window_id),
            0x2222,
            "the previous active window HWND must survive the active switch"
        );
        assert_eq!(
            app.detached_viewer_host_generation, 17,
            "active switching must not close/recreate the previous active window"
        );
    }

