    #[test]
    fn detached_spread_snapshot_preserves_trim_uv_and_background() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let placement = crate::settings::DetachedViewerWindowPlacement {
            x: 80.0,
            y: 80.0,
            w: 960.0,
            h: 720.0,
            maximized: false,
        };
        app.settings.detached_viewer_open_images_in_window = true;
        app.settings.fullscreen_fit_mode = crate::settings::FullscreenFitMode::Width;
        app.settings.spread_page_gap_px = 0;
        app.settings.detached_viewer_window_placement = Some(placement);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.detached_viewer_independent_active = true;
        app.detached_viewer_window_id = Some(72);
        app.spread_mode = crate::settings::SpreadMode::Ltr;
        app.fs_transparent_bg_mode = 1;
        app.view_trim_apply_mode = crate::view_trim::ViewTrimApplyMode::Book;
        app.view_trim_book_settings.enabled = true;
        app.view_trim_book_settings.spread_separate = true;
        app.view_trim_book_settings.spread_left = crate::view_trim::ViewTrimMargins {
            left: 0.00,
            top: 0.10,
            right: 0.20,
            bottom: 0.10,
        };
        app.view_trim_book_settings.spread_right = crate::view_trim::ViewTrimMargins {
            left: 0.20,
            top: 0.00,
            right: 0.00,
            bottom: 0.20,
        };
        let left = push_image(&mut app, r"C:\pics\spread-trim-left.png");
        let right = push_image(&mut app, r"C:\pics\spread-trim-right.png");
        for (idx, label) in [(left, "spread_trim_left"), (right, "spread_trim_right")] {
            let pixels = egui::ColorImage::new([1, 2], vec![egui::Color32::WHITE; 2]);
            let tex = ctx.load_texture(label, pixels.clone(), egui::TextureOptions::LINEAR);
            app.fs_cache.insert(
                idx,
                FsCacheEntry::Static {
                    tex,
                    pixels: std::sync::Arc::new(pixels),
                    source_dims: Some([1, 2]),
                    load_seq: 0,
                    animation: crate::fs_animation::StaticAnimationState::Still,
                },
            );
        }
        app.fullscreen_idx = Some(left);

        let snapshot = app
            .build_active_detached_image_window_snapshot(Some(&ctx))
            .expect("spread detached viewer should build a snapshot");

        assert_eq!(snapshot.frozen_continuous_pages.len(), 2);
        let left_page = &snapshot.frozen_continuous_pages[0];
        let right_page = &snapshot.frozen_continuous_pages[1];
        assert_frozen_background_white(&left_page.background);
        assert_frozen_background_white(&right_page.background);
        assert_rect_close(
            left_page.uv_rect,
            egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)),
        );
        assert_rect_close(
            right_page.uv_rect,
            egui::Rect::from_min_max(egui::pos2(0.0, 0.0), egui::pos2(1.0, 1.0)),
        );

        assert!(
            left_page.paint_rect_norm.right() > right_page.paint_rect_norm.left(),
            "frozen page rects must keep the hidden inner trim margins behind the cropped UVs"
        );
        assert!(
            left_page.clip_rect_norm.right() <= right_page.clip_rect_norm.left() + 0.001,
            "frozen page clips must remove the overlap between full page rects"
        );
        assert!(left_page.clip_rect_norm.left() >= left_page.paint_rect_norm.left() - 0.001);
        assert!(left_page.clip_rect_norm.right() <= left_page.paint_rect_norm.right() + 0.001);
        assert!(right_page.clip_rect_norm.left() >= right_page.paint_rect_norm.left() - 0.001);
        assert!(right_page.clip_rect_norm.right() <= right_page.paint_rect_norm.right() + 0.001);
        assert!(
            left_page.clip_rect_norm.width() < left_page.paint_rect_norm.width()
                && right_page.clip_rect_norm.width() < right_page.paint_rect_norm.width(),
            "trimmed spread pages must preserve full paint rects but clip hidden side margins"
        );
    }

    /// 凍結した見開きの**見える継ぎ目**が、設定した間隔ちょうどになる (backlog §1.154)。
    ///
    /// live 経路は v3.4.0 で直ったが、凍結 snapshot だけは残っていた。あちらは transform を
    /// `content_bbox: None` で組み、可視範囲を**寄せる前**のレイアウト矩形から作った clip で
    /// 表していたので、見える端を clip が・絵の位置を寄せた transform が決めていた。
    /// 端数倍率と正の間隔を通し、`clip_rect_norm` の内側の距離で測る — 利用者に見えるのは
    /// そこだからである。既存の
    /// `detached_spread_snapshot_preserves_trim_uv_and_background` は gap=0 で重なりの
    /// 有無しか見ておらず、この距離を固定していない。
    #[test]
    fn the_frozen_spread_seam_is_the_configured_width_at_fractional_scales() {
        for gap in [0_u32, 1, 3] {
            for (window_w, window_h) in [(960.0_f32, 720.0_f32), (953.0, 719.0)] {
                let mut app = setup_app();
                let ctx = egui::Context::default();
                let placement = crate::settings::DetachedViewerWindowPlacement {
                    x: 80.0,
                    y: 80.0,
                    w: window_w,
                    h: window_h,
                    maximized: false,
                };
                app.settings.detached_viewer_open_images_in_window = true;
                app.settings.fullscreen_fit_mode = crate::settings::FullscreenFitMode::Width;
                app.settings.spread_page_gap_px = gap;
                app.settings.detached_viewer_window_placement = Some(placement);
                app.viewer_presentation = ViewerPresentation::DetachedWindow;
                app.detached_viewer_independent_active = true;
                app.detached_viewer_window_id = Some(74);
                app.spread_mode = crate::settings::SpreadMode::Ltr;
                let left = push_image(&mut app, r"C:\pics\seam-left.png");
                let right = push_image(&mut app, r"C:\pics\seam-right.png");
                // 端数の出る寸法。左右で 1px 違えて、片側だけ丸めが倒れる並びにする。
                for (idx, label, dims) in [
                    (left, "seam_left", [617_usize, 881_usize]),
                    (right, "seam_right", [613, 883]),
                ] {
                    let pixels = egui::ColorImage::new(
                        [dims[0], dims[1]],
                        vec![egui::Color32::WHITE; dims[0] * dims[1]],
                    );
                    let tex = ctx.load_texture(label, pixels.clone(), egui::TextureOptions::LINEAR);
                    app.fs_cache.insert(
                        idx,
                        FsCacheEntry::Static {
                            tex,
                            pixels: std::sync::Arc::new(pixels),
                            source_dims: Some(dims),
                            load_seq: 0,
                            animation: crate::fs_animation::StaticAnimationState::Still,
                        },
                    );
                }
                app.fullscreen_idx = Some(left);

                let snapshot = app
                    .build_active_detached_image_window_snapshot(Some(&ctx))
                    .expect("spread detached viewer should build a snapshot");

                assert_eq!(snapshot.frozen_continuous_pages.len(), 2);
                let pixels_per_point = ctx.pixels_per_point();
                // 正規化を実寸へ戻して測る。凍結ページはウィンドウ比で持ち出される。
                let to_px = |value: f32| value * window_w * pixels_per_point;
                let seam = to_px(snapshot.frozen_continuous_pages[1].clip_rect_norm.left())
                    - to_px(snapshot.frozen_continuous_pages[0].clip_rect_norm.right());
                let want = (gap as f32 * pixels_per_point).round();
                assert!(
                    (seam - want).abs() < 0.01,
                    "gap={gap} window={window_w}x{window_h}: 継ぎ目 {seam}px (設定 {want}px)"
                );
            }
        }
    }

    #[test]
    fn detached_auto_trim_snapshot_uses_baked_runtime_bbox_after_fs_cache_eviction() {
        let mut app = setup_app();
        let ctx = egui::Context::default();
        let placement = crate::settings::DetachedViewerWindowPlacement {
            x: 80.0,
            y: 80.0,
            w: 960.0,
            h: 720.0,
            maximized: false,
        };
        app.settings.detached_viewer_open_images_in_window = true;
        app.settings.fullscreen_fit_mode = crate::settings::FullscreenFitMode::Width;
        app.settings.spread_page_gap_px = 0;
        app.settings.detached_viewer_window_placement = Some(placement);
        app.viewer_presentation = ViewerPresentation::DetachedWindow;
        app.detached_viewer_independent_active = true;
        app.transition_detached_window_state(73, DetachedWindowState::Active, "test");
        app.detached_viewer_window_id = Some(73);
        app.spread_mode = crate::settings::SpreadMode::Ltr;
        app.view_trim_apply_mode = crate::view_trim::ViewTrimApplyMode::Auto;
        let left = push_image(&mut app, r"C:\pics\auto-trim-left.png");
        let right = push_image(&mut app, r"C:\pics\auto-trim-right.png");

        let make_margin_image = || {
            let size = [20, 20];
            let mut pixels = vec![egui::Color32::WHITE; size[0] * size[1]];
            for y in 5..15 {
                for x in 4..16 {
                    pixels[y * size[0] + x] = egui::Color32::BLACK;
                }
            }
            egui::ColorImage::new(size, pixels)
        };

        for (idx, label) in [(left, "auto_trim_left"), (right, "auto_trim_right")] {
            let pixels = make_margin_image();
            let tex = ctx.load_texture(label, pixels.clone(), egui::TextureOptions::LINEAR);
            app.thumbnails.insert(
                idx,
                ThumbnailState::Loaded {
                    tex: tex.clone(),
                    from_cache: false,
                    from_edit_preview: false,
                    rendered_at_px: 20,
                    source_dims: Some((20, 20)),
                    layout_dims: None,
                },
            );
            app.fs_cache.insert(
                idx,
                FsCacheEntry::Static {
                    tex,
                    pixels: std::sync::Arc::new(pixels),
                    source_dims: Some([20, 20]),
                    load_seq: 0,
                    animation: crate::fs_animation::StaticAnimationState::Still,
                },
            );
        }
        app.fullscreen_idx = Some(left);

        let first = app
            .build_active_detached_image_window_snapshot(Some(&ctx))
            .expect("spread detached viewer should build a snapshot");
        assert_eq!(first.frozen_continuous_pages.len(), 2);
        assert!(
            app.detached_window_runtime_trim_bbox(73, left)
                .is_some_and(|bbox| bbox.is_some()),
            "first display commit should bake the left page auto-trim bbox"
        );
        assert!(
            app.detached_window_runtime_trim_bbox(73, right)
                .is_some_and(|bbox| bbox.is_some()),
            "first display commit should bake the right page auto-trim bbox"
        );
        let first_rects = first
            .frozen_continuous_pages
            .iter()
            .map(|page| (page.paint_rect_norm, page.clip_rect_norm))
            .collect::<Vec<_>>();

        app.fs_cache.remove(&left);
        app.fs_cache.remove(&right);
        app.fs_margin_bbox_cache.clear();

        let second = app
            .build_active_detached_image_window_snapshot(Some(&ctx))
            .expect("thumbnail fallback should still allow the detached snapshot to build");
        assert_eq!(second.frozen_continuous_pages.len(), 2);
        let second_rects = second
            .frozen_continuous_pages
            .iter()
            .map(|page| (page.paint_rect_norm, page.clip_rect_norm))
            .collect::<Vec<_>>();

        assert_eq!(first_rects.len(), second_rects.len());
        for ((first_paint, first_clip), (second_paint, second_clip)) in
            first_rects.into_iter().zip(second_rects)
        {
            assert_rect_close(first_paint, second_paint);
            assert_rect_close(first_clip, second_clip);
        }
    }

