    #[test]
    #[cfg(windows)]
    fn activating_parked_live_media_restores_video_session() {
        use crate::video::NativeVideoOutputEvent as Ev;
        use crate::video::native_window::{
            NativeVideoMouseWheelEvent, NativeVideoWindowEvent as WinEv,
        };

        let mut app = setup_app();
        let ctx = egui::Context::default();
        let video = push_video(&mut app, r"C:\clips\live.mp4");
        let items = app.items.clone();
        let tex = ctx.load_texture(
            "parked_live_resume",
            egui::ColorImage::new([1, 1], vec![egui::Color32::BLACK]),
            egui::TextureOptions::LINEAR,
        );
        app.detached_image_windows
            .push(DetachedImageWindowSnapshot {
                id: 61,
                texture: crate::gpu_lanczos::FullscreenPaintResource::direct(tex),
                title: "live".to_owned(),
                location_display: "live".to_owned(),
                image_dims: None,
                rotation: crate::rotation_db::Rotation::None,
                zoom_pan: None,
                free_rotation: 0.0,
                image_rect_norm: egui::Rect::from_min_max(
                    egui::pos2(0.0, 0.0),
                    egui::pos2(1.0, 1.0),
                ),
                image_content_bbox: None,
                frozen_continuous_pages: Vec::new(),
                reopen_descriptor: None,
                reopen_sync_stamp: None,
                activation_ready_frame: 0,
                activation_armed: true,
                focused_last_frame: false,
                initial_placement_applied: true,
            });
        app.build_window_context_for_test(61, move |context| {
            context.items = items;
            context.address = "parked-live://sentinel".to_owned();
            context.fullscreen_idx = Some(video);
            context.viewer_presentation = ViewerPresentation::DetachedWindow;
            context.detached_viewer_independent_active = true;
            context.detached_viewer_window_id = Some(61);
        });
        app.transition_detached_window_state(61, DetachedWindowState::ParkedLive, "test_setup");

        assert!(app.activate_detached_image_window_snapshot(&ctx, 61));

        let session = app
            .active_detached_session
            .expect("parked live media should resume as active detached video");
        assert_eq!(session.window_id, 61);
        assert_eq!(session.source, DetachedSource::Video);
        assert_eq!(
            app.detached_window_state(61),
            Some(DetachedWindowState::Active)
        );
        assert!(app.other_active_viewer_context_contains_video());
        assert!(
            !app.detached_image_windows
                .iter()
                .any(|window| window.id == 61),
            "ParkedLive restore must atomically remove the passive snapshot"
        );
        app.with_active_viewer_context(|active| {
            assert_eq!(active.address, "parked-live://sentinel");
            assert_eq!(active.detached_viewer_window_id, Some(61));
            assert_eq!(active.fullscreen_idx, Some(video));
        })
        .expect("parked live bundle should become the active context");
        let wheel = Ev::Window(WinEv::MouseWheel(NativeVideoMouseWheelEvent {
            delta: -120,
            x: 10,
            y: 10,
            shift: false,
            ctrl: false,
        }));
        assert!(
            !app.native_video_event_blocked_by_parked_live_filter(&wheel),
            "after ParkedLive restore, native wheel must return to the normal active-video path"
        );
    }

    fn write_nav_test_zip(path: &std::path::Path) {
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).unwrap();
        }
        let file = std::fs::File::create(path).unwrap();
        let mut zw = zip::ZipWriter::new(file);
        let opts: zip::write::FileOptions<'_, ()> =
            zip::write::FileOptions::default().compression_method(zip::CompressionMethod::Stored);
        zw.start_file("page.jpg", opts).unwrap();
        std::io::Write::write_all(&mut zw, b"page").unwrap();
        zw.finish().unwrap();
    }

    struct ConvertedArchiveNavFixture {
        expected_next: std::path::PathBuf,
        cache_wrong_next: std::path::PathBuf,
    }

    fn setup_converted_archive_nav_fixture(
        app: &mut App,
        tmp: &std::path::Path,
    ) -> ConvertedArchiveNavFixture {
        use crate::grid_item::GridItem;

        let source_dir = tmp.join("library");
        let cache_dir = tmp.join("archive-cache-like");
        let source_zip = source_dir.join("01-source.zip");
        let expected_next = source_dir.join("02-next");
        let cache_zip = cache_dir.join("01-cache.zip");
        let cache_wrong_next = cache_dir.join("02-cache-next");

        write_nav_test_zip(&source_zip);
        write_nav_test_zip(&cache_zip);
        std::fs::create_dir_all(&expected_next).unwrap();
        std::fs::write(expected_next.join("p.jpg"), b"expected").unwrap();
        std::fs::create_dir_all(&cache_wrong_next).unwrap();
        std::fs::write(cache_wrong_next.join("p.jpg"), b"wrong").unwrap();

        app.settings.sort_order = crate::settings::SortOrder::FileName;
        app.settings.folder_skip_limit = 8;
        app.current_folder = Some(cache_zip.clone());
        app.archive_source_override = Some(source_zip);
        app.items = vec![GridItem::ZipImage {
            zip_path: cache_zip.clone(),
            entry_name: "bookB/p1.jpg".to_string(),
        }];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.visible_indices = vec![0];
        app.fullscreen_idx = Some(0);

        // ZIP 内 DFS の最後の本にいる状態。Ctrl+↓ は ZIP ツリー内では進めず、
        // 呼び出し側の通常フォルダ DFS へフォールバックする。
        let mut nav = test_zip_nav_for(cache_zip, &["bookA/p1.jpg", "bookB/p1.jpg"]);
        nav.enter("bookB/");
        app.zip_nav = Some(nav);

        ConvertedArchiveNavFixture {
            expected_next,
            cache_wrong_next,
        }
    }

    fn wait_folder_nav_result(app: &mut App) -> FolderNavResult {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(2);
        loop {
            if let Some(result) = app.poll_folder_nav() {
                return result;
            }
            assert!(
                std::time::Instant::now() < deadline,
                "folder nav worker did not finish"
            );
            std::thread::sleep(std::time::Duration::from_millis(5));
        }
    }

    #[test]
    fn fullscreen_ctrl_nav_exits_converted_zip_from_source_path() {
        let mut app = setup_app();
        let tmp = app.tmp.path().to_path_buf();
        let fixture = setup_converted_archive_nav_fixture(&mut app, &tmp);
        let ctx = egui::Context::default();

        app.handle_fullscreen_ctrl_nav_context(&ctx, 0, true, false);
        let result = wait_folder_nav_result(&mut app);

        assert_eq!(result.path.as_ref(), Some(&fixture.expected_next));
        assert_ne!(
            result.path.as_ref(),
            Some(&fixture.cache_wrong_next),
            "変換キャッシュ ZIP の物理パスを起点にすると archive_cache 側へ逸れる"
        );
        assert!(result.hit_image_folder);
    }

