    #[test]
    #[cfg(windows)]
    fn parked_live_native_right_drag_allow_list_is_narrow_and_state_based() {
        use crate::ring_shortcut::{RightDragContext, RightDragMode, RightDragOwner};
        use crate::video::NativeVideoOutputEvent as Ev;
        use crate::video::native_window::{
            NativeVideoKeyEvent, NativeVideoMouseButton, NativeVideoMouseButtonEvent,
            NativeVideoMouseEvent, NativeVideoMouseWheelEvent, NativeVideoWindowEvent as WinEv,
        };

        let mut app = setup_app();
        let window_id = 93;
        let owner = RightDragOwner::DetachedWindow(window_id);
        app.native_video_parked_live_input_window_id = Some(window_id);
        app.settings.ring_shortcuts.set_right_drag_mode(
            RightDragContext::VideoFullscreen,
            RightDragMode::MouseGesture,
        );

        let right_down = NativeVideoMouseButtonEvent {
            button: NativeVideoMouseButton::Right,
            down: true,
            double_click: false,
            x: 40,
            y: 50,
            shift: false,
            ctrl: false,
        };
        let right_up = NativeVideoMouseButtonEvent {
            down: false,
            ..right_down
        };
        let left_down = NativeVideoMouseButtonEvent {
            button: NativeVideoMouseButton::Left,
            ..right_down
        };
        let mouse_move = NativeVideoMouseEvent {
            x: 60,
            y: 70,
            shift: false,
            ctrl: false,
        };
        assert!(
            app.native_video_output_event_allowed_while_parked_live(&Ev::Window(
                WinEv::MouseButton(right_down)
            ))
        );
        assert!(
            app.native_video_output_event_allowed_while_parked_live(&Ev::Window(
                WinEv::MouseButton(right_up)
            ))
        );
        assert!(
            !app.native_video_output_event_allowed_while_parked_live(&Ev::Window(
                WinEv::MouseMove(mouse_move)
            )),
            "an unowned hover move must remain filtered"
        );
        assert!(
            !app.native_video_output_event_allowed_while_parked_live(&Ev::Window(
                WinEv::MouseButton(left_down)
            )),
            "left click remains on its dedicated activation path"
        );

        app.mouse_gesture = Some(crate::ring_shortcut::MouseGestureState::new(
            owner,
            RightDragContext::VideoFullscreen,
            // ジェスチャが「メニュー遅延を十分に過ぎている」ことだけを表す。**実時間の
            // 長さに意味は無い。** Windows の `Instant` は起動からの計数なので、
            // `Instant::now() - 1時間` は**稼働 1 時間未満のマシンで必ずパニックする**
            // (2026-08-28、稼働 44 分の実機で発覚。閾値 400ms に対して 9000 倍だった)。
            std::time::Instant::now() - crate::ring_shortcut::mouse_flick_menu_delay() * 4,
            egui::pos2(40.0, 50.0),
        ));
        assert!(
            app.native_video_output_event_allowed_while_parked_live(&Ev::Window(WinEv::MouseMove(
                mouse_move
            ))),
            "the owning reducer, not its age, keeps drag moves enabled"
        );
        app.mouse_gesture = Some(crate::ring_shortcut::MouseGestureState::new(
            RightDragOwner::DetachedWindow(window_id + 1),
            RightDragContext::VideoFullscreen,
            std::time::Instant::now(),
            egui::pos2(40.0, 50.0),
        ));
        assert!(
            !app.native_video_output_event_allowed_while_parked_live(&Ev::Window(
                WinEv::MouseMove(mouse_move)
            ))
        );

        app.mouse_gesture = None;
        app.mouse_ring_flick = Some(crate::ring_shortcut::MouseFlickState::new(
            owner,
            crate::ring_shortcut::RingShortcutContext::VideoFullscreen,
            std::time::Instant::now(),
            egui::pos2(40.0, 50.0),
        ));
        assert!(
            app.native_video_output_event_allowed_while_parked_live(&Ev::Window(WinEv::MouseMove(
                mouse_move
            )))
        );

        let key = NativeVideoKeyEvent {
            virtual_key: 0x28,
            scan_code: 0,
            extended: false,
            shift: false,
            ctrl: false,
            alt: false,
            repeat: false,
        };
        let wheel = NativeVideoMouseWheelEvent {
            delta: -120,
            x: 60,
            y: 70,
            shift: false,
            ctrl: false,
        };
        for event in [
            Ev::Window(WinEv::KeyDown(key)),
            Ev::Window(WinEv::MouseWheel(wheel)),
            Ev::Seek { target_secs: 12.0 },
            Ev::SetVolume {
                volume: 0.5,
                persist: true,
            },
            Ev::SetPlaybackSpeed { speed: 1.5 },
            Ev::TogglePlay,
        ] {
            assert!(!app.native_video_output_event_allowed_while_parked_live(&event));
        }

        app.settings
            .ring_shortcuts
            .set_right_drag_mode(RightDragContext::VideoFullscreen, RightDragMode::Disabled);
        for event in [
            Ev::Window(WinEv::MouseButton(right_down)),
            Ev::Window(WinEv::MouseButton(right_up)),
            Ev::Window(WinEv::MouseMove(mouse_move)),
        ] {
            assert!(!app.native_video_output_event_allowed_while_parked_live(&event));
            assert!(app.native_video_event_blocked_by_parked_live_filter(&event));
        }
    }

    #[test]
    #[cfg(windows)]
    fn parked_live_native_right_drag_enters_detached_window_owner_reducer() {
        use crate::ring_shortcut::{RightDragContext, RightDragMode, RightDragOwner};
        use crate::video::NativeVideoOutputEvent as Ev;
        use crate::video::native_window::{
            NativeVideoMouseButton, NativeVideoMouseButtonEvent, NativeVideoMouseEvent,
            NativeVideoWindowEvent as WinEv,
        };

        let mut app = setup_app();
        let ctx = egui::Context::default();
        let video = push_video(&mut app, r"C:\clips\parked-gesture.mp4");
        let window_id = 94;
        let owner = RightDragOwner::DetachedWindow(window_id);
        app.fullscreen_idx = Some(video);
        app.native_video_parked_live_input_window_id = Some(window_id);
        app.settings.ring_shortcuts.set_right_drag_mode(
            RightDragContext::VideoFullscreen,
            RightDragMode::MouseGesture,
        );

        let right_down = NativeVideoMouseButtonEvent {
            button: NativeVideoMouseButton::Right,
            down: true,
            double_click: false,
            x: 400,
            y: 300,
            shift: false,
            ctrl: false,
        };
        let down_event = Ev::Window(WinEv::MouseButton(right_down));
        assert!(app.native_video_output_event_allowed_while_parked_live(&down_event));
        app.handle_native_video_window_event(&ctx, video, WinEv::MouseButton(right_down));
        assert!(app.mouse_gesture.as_ref().is_some_and(|gesture| {
            gesture.owner == owner && gesture.context == RightDragContext::VideoFullscreen
        }));

        app.handle_native_video_window_event(
            &ctx,
            video,
            WinEv::MouseMove(NativeVideoMouseEvent {
                x: 480,
                y: 300,
                shift: false,
                ctrl: false,
            }),
        );
        assert_eq!(
            app.mouse_gesture
                .as_ref()
                .map(|gesture| gesture.current_pos),
            Some(egui::pos2(480.0, 300.0))
        );

        app.cancel_mouse_gesture();
        app.settings.ring_shortcuts.set_right_drag_mode(
            RightDragContext::VideoFullscreen,
            RightDragMode::RingShortcut,
        );
        app.handle_native_video_window_event(&ctx, video, WinEv::MouseButton(right_down));
        assert!(app.mouse_ring_flick.as_ref().is_some_and(|flick| {
            flick.owner == owner
                && flick.context == crate::ring_shortcut::RingShortcutContext::VideoFullscreen
        }));
    }

    /// Regression for backlog §1.131: while ParkedLive, the seek strip asked the presenter for its
    /// own window from the draw path and the classifier read that as a HUD click, so the video
    /// window took the foreground back 13ms after the user activated a different one. Renderer-,
    /// worker- and lifecycle-produced events must never request activation, and the classifier is
    /// exhaustive so a new event cannot join them by default.
    #[test]
    #[cfg(windows)]
    fn parked_live_renderer_emitted_events_do_not_request_activation() {
        use crate::video::NativeVideoOutputEvent as Ev;
        use crate::video::seek_strip::{SeekStripCenter, SeekStripCloseCause};

        // The event the user hit: emitted whenever the strip layout key changes, with no click.
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::RequestSeekStripWindow {
                    center: SeekStripCenter::Thumbnails { center_index: 0.0 },
                    visible_count: 10,
                    pixel_width: 1752,
                    pixel_height: 141,
                }
            )
        );

        // The strip closes itself from the draw path whenever the HUD is not visible. Only the
        // three causes the user actually asks for count as a dismissal.
        for cause in [
            SeekStripCloseCause::HudHidden,
            SeekStripCloseCause::VideoChanged,
            SeekStripCloseCause::FullscreenExit,
            SeekStripCloseCause::TileModeOpened,
            SeekStripCloseCause::Unavailable,
        ] {
            assert!(
                !App::native_video_output_event_is_parked_live_hud_click_activation(
                    &Ev::CloseSeekStrip { cause }
                ),
                "{cause:?} is not a user dismissal"
            );
        }
        for cause in [
            SeekStripCloseCause::Toggle,
            SeekStripCloseCause::DownwardDrag,
            SeekStripCloseCause::Escape,
        ] {
            assert!(
                App::native_video_output_event_is_parked_live_hud_click_activation(
                    &Ev::CloseSeekStrip { cause }
                ),
                "{cause:?} is a user dismissal"
            );
        }

        // Worker completions and commit notifications arrive on their own schedule.
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::Anime4kMeasurementCompleted(Err("failed".to_string()))
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::VideoScaleSettingsCommitted {
                    filter: crate::settings::VideoScaleFilter::default(),
                    smoothing_percent: 50,
                    anime4k_variant: None,
                    toast: None,
                }
            )
        );

        // The VST panel reports its position both after a drag and after an automatic clamp. The
        // drag already requests activation through the left-button path, so this must not.
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::SetVst3PanelPos { pos: [12.0, 34.0] }
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::SetVst3PanelVisible { visible: true }
            )
        );

        // A touch that teaches the chrome gesture is still the user acting.
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::TouchChromeLearned
            )
        );
        // So is every deliberate strip operation.
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(&Ev::OpenSeekStrip)
        );
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::CommitSeekStrip {
                    center: SeekStripCenter::Thumbnails { center_index: 4.0 },
                }
            )
        );
    }

    #[test]
    #[cfg(windows)]
    fn parked_live_native_hud_commands_request_activation_only() {
        use crate::video::NativeVideoOutputEvent as Ev;
        use crate::video::NativeVideoPlacement;
        use crate::video::native_window::{
            NativeVideoKeyEvent, NativeVideoMouseButton, NativeVideoMouseButtonEvent,
            NativeVideoMouseWheelEvent, NativeVideoWindowEvent as WinEv,
        };

        let mut app = setup_app();
        let ctx = egui::Context::default();
        let video = push_video(&mut app, r"C:\clips\live.mp4");
        app.fullscreen_idx = Some(video);
        app.native_video_parked_live_input_window_id = Some(92);

        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::ToggleAudioMode
            )
        );
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::ToggleWindowMode
            )
        );
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::CloseFullscreen { generation: 1 }
            )
        );
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(&Ev::Seek {
                target_secs: 12.0
            })
        );
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(&Ev::SetVolume {
                volume: 0.5,
                persist: true
            })
        );
        assert!(
            App::native_video_output_event_is_parked_live_hud_click_activation(&Ev::NavigateItem {
                delta: 1,
                via_wheel: false
            })
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::NavigateItem {
                    delta: 1,
                    via_wheel: true
                }
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::TileColumnsDelta { delta: 1 }
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::RequestSeekThumbnail {
                    target_secs: 12.0,
                    bar_width_points: 300.0,
                    pixels_per_point: 2.0,
                }
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::ClearSeekThumbnail
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::PlacementCommitted {
                    request_id: 1,
                    placement: NativeVideoPlacement::DetachedWindow,
                    generation: 1
                }
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(
                &Ev::PlacementSwitchFailed { request_id: 1 }
            )
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(&Ev::Window(
                WinEv::KeyDown(NativeVideoKeyEvent {
                    virtual_key: 0x28,
                    scan_code: 0,
                    extended: false,
                    shift: false,
                    ctrl: false,
                    alt: false,
                    repeat: false,
                })
            ))
        );
        assert!(
            !App::native_video_output_event_is_parked_live_hud_click_activation(&Ev::Window(
                WinEv::MouseWheel(NativeVideoMouseWheelEvent {
                    delta: -120,
                    x: 10,
                    y: 10,
                    shift: false,
                    ctrl: false,
                })
            ))
        );

        app.handle_native_video_output_event(&ctx, video, 0, Ev::ToggleAudioMode);

        assert_eq!(app.native_video_parked_live_activation_requests, vec![92]);
        assert!(
            app.video_audio_mode.is_none(),
            "parked HUD commands must activate the window instead of executing their function"
        );

        app.handle_native_video_output_event(&ctx, video, 0, Ev::TogglePlay);
        assert_eq!(
            app.native_video_parked_live_activation_requests,
            vec![92],
            "activation requests are deduplicated while parked"
        );

        let left_down = NativeVideoMouseButtonEvent {
            button: NativeVideoMouseButton::Left,
            down: true,
            double_click: false,
            x: 10,
            y: 10,
            shift: false,
            ctrl: false,
        };
        let left_up = NativeVideoMouseButtonEvent {
            down: false,
            ..left_down
        };
        app.handle_native_video_output_event(
            &ctx,
            video,
            0,
            Ev::Window(WinEv::MouseButton(left_down)),
        );
        app.handle_native_video_output_event(
            &ctx,
            video,
            0,
            Ev::Window(WinEv::MouseButton(left_up)),
        );
        assert_eq!(
            app.native_video_parked_live_activation_requests,
            vec![92],
            "semantic HUD command + raw click converge to one parked activation request"
        );

        app.native_video_parked_live_activation_requests.clear();
        app.handle_native_video_output_event(
            &ctx,
            video,
            0,
            Ev::NavigateItem {
                delta: 1,
                via_wheel: true,
            },
        );
        app.handle_native_video_output_event(&ctx, video, 0, Ev::TileColumnsDelta { delta: 1 });
        assert!(
            app.native_video_parked_live_activation_requests.is_empty(),
            "parked wheel-origin native commands stay inert and must not activate"
        );

        app.handle_native_video_output_event(
            &ctx,
            video,
            0,
            Ev::NavigateItem {
                delta: 1,
                via_wheel: false,
            },
        );
        assert_eq!(
            app.native_video_parked_live_activation_requests,
            vec![92],
            "parked HUD prev/next button commands request activation"
        );
    }

