    #[test]
    fn snapshot_out_of_scope_load_is_refused_before_main_state_effects() {
        let mut app = setup_app();
        let (source, _before) = install_convertible_archive_main_grid(&mut app);

        // Preserve a real resident smart-folder session while installing the real SnapshotState,
        // then put both owners back into the common-load precondition state. This makes the
        // one-shot authorization observable: a refused load must neither consume it nor discard
        // its SmartFolder surface.
        let smart_state = app
            .top_level_grid_view
            .smart_folder()
            .cloned()
            .expect("smart-folder surface before snapshot");
        let smart_session = app
            .top_level_grid_view
            .take_smart_folder_session()
            .expect("resident smart-folder session before snapshot");
        activate_convertible_archive_snapshot(&mut app, &source);
        app.top_level_grid_view.replace_surface(
            super::top_level_grid_view::TopLevelGridSurface::SmartFolder(smart_state),
        );
        app.top_level_grid_view
            .install_smart_folder_session(smart_session);
        assert!(app.authorize_smart_folder_session_open(&source));

        let outside = app.tmp.path().join("outside-snapshot-scope");
        std::fs::create_dir_all(&outside).unwrap();
        let reserved_history = app.tmp.path().join("still-reserved-history.zip");
        app.reading_history_return_from = Some(reserved_history.clone());
        app.suppress_nav_record_for_search_restore = true;

        let folder_before = app.current_folder.clone();
        let surface_before = app.top_level_grid_view.surface().clone();
        let smart_id_before = app.current_smart_folder_id;
        let items_before = app.items.iter().map(GridItem::perf_key).collect::<Vec<_>>();
        let snapshot_count_before = app.snapshot_count();
        assert_eq!(app.snapshot_owner_entry(&outside), None);

        app.load_folder(outside);

        assert_eq!(app.current_folder, folder_before);
        assert_eq!(app.reading_history_return_from, Some(reserved_history));
        assert!(app.suppress_nav_record_for_search_restore);
        assert_eq!(app.top_level_grid_view.surface(), &surface_before);
        assert_eq!(app.current_smart_folder_id, smart_id_before);
        assert!(app.top_level_grid_view.smart_folder_session().is_some());
        assert_eq!(
            app.items.iter().map(GridItem::perf_key).collect::<Vec<_>>(),
            items_before
        );
        assert_eq!(app.snapshot_count(), snapshot_count_before);

        // Prove the authorization assertion is not a field-presence check: after temporarily
        // removing only the snapshot precondition, the exact previously authorized source is
        // still consumable by the real session boundary.
        let snapshot = app
            .snapshot
            .take()
            .expect("snapshot remains active after refusal");
        assert!(app.preserve_smart_folder_session_for_load(&source));
        app.snapshot = Some(snapshot);
        // Mutation `smart_session_effect_before_snapshot_guard`: move
        // preserve_smart_folder_session_for_load/clear_smart_folder_view_state back above the
        // guard. It consumes/drops the authorization and surface, so the surface/session and
        // behavioral authorization assertions fail. Moving the reading-history reconciliation
        // back above the guard independently fails the reservation assertion.
    }

    fn drain_smart_folder_nav(app: &mut App, ctx: &egui::Context) {
        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(10);
        while app.folder_nav_pending.is_some() {
            if let Some(result) = app.poll_folder_nav() {
                app.apply_folder_nav_result(ctx, result);
            } else {
                assert!(
                    std::time::Instant::now() < deadline,
                    "smart-folder navigation did not finish before the deadline"
                );
                std::thread::yield_now();
            }
        }
        assert_eq!(app.pending_folder_nav_steps, 0);
    }

    #[derive(Clone, Copy, Debug)]
    enum SyntheticSearchOrigin {
        DriveList,
        ReadingHistory,
        RatingView,
    }

    fn install_synthetic_search_origin(app: &mut App, origin: SyntheticSearchOrigin) -> PathBuf {
        match origin {
            SyntheticSearchOrigin::DriveList => app.enter_drive_list(None),
            SyntheticSearchOrigin::ReadingHistory => app.enter_reading_history(),
            SyntheticSearchOrigin::RatingView => {
                app.rating_view_stars = 4;
                app.rating_view_rows_stars = Some(4);
                app.rating_view_rows.clear();
                app.install_rating_view_rows();
            }
        }
        app.current_folder
            .clone()
            .expect("synthetic view must install its location")
    }

    fn assert_synthetic_search_origin_restored(app: &App, origin: SyntheticSearchOrigin) {
        match origin {
            SyntheticSearchOrigin::DriveList => assert!(app.items_are_drive_list),
            SyntheticSearchOrigin::ReadingHistory => {
                assert!(app.items_are_reading_history_view)
            }
            SyntheticSearchOrigin::RatingView => {
                assert!(app.items_are_rating_view);
                assert_eq!(app.rating_view_stars, 4);
            }
        }
    }

    #[test]
    fn smart_folder_drill_parent_search_snapshot_and_history_round_trip_keep_scope() {
        let mut app = setup_app();
        app.active_quick_folder_slot = None;
        let normal = app.tmp.path().join("normal-scope-roundtrip");
        let source = app.tmp.path().join("smart-scope-source");
        let entry = source.join("entry");
        let child = entry.join("child");
        let grandchild = child.join("grandchild");
        let page = child.join("page.jpg");
        std::fs::create_dir_all(&normal).unwrap();
        std::fs::create_dir_all(&grandchild).unwrap();
        std::fs::write(&page, []).unwrap();
        std::fs::write(grandchild.join("nested.jpg"), []).unwrap();
        let definition = definition("Smart Scope", source);
        let id = definition.id;
        app.settings.smart_folders = vec![definition];
        app.current_folder = Some(normal.clone());
        let ctx = egui::Context::default();
        app.open_smart_folder(id, false);
        wait_for_smart_folder_idle(&mut app, &ctx, id);
        assert!(app.begin_smart_folder_drill(&entry));
        app.load_folder(entry.clone());
        assert!(app.begin_smart_folder_drill(&child));
        app.load_folder(child.clone());
        assert_eq!(
            app.top_level_grid_view
                .smart_folder()
                .and_then(|state| state.scoped_current()),
            Some(child.as_path())
        );
        assert!(app.address.contains("Smart Scope"));
        assert!(app.address.contains("entry"));
        assert!(app.address.contains("child"));
        assert!(matches!(
            app.resolve_grid_parent_nav(),
            Some(crate::ui_main::AddressBarNav::Direct(path))
                if crate::folder_tree::path_eq(&path, &entry)
        ));
        app.load_folder(entry.clone());
        let synthetic = crate::app::smart_folder::smart_folder_synthetic_path(id);
        assert!(matches!(
            app.resolve_grid_parent_nav(),
            Some(crate::ui_main::AddressBarNav::Direct(path))
                if crate::folder_tree::path_eq(&path, &synthetic)
        ));

        assert!(app.begin_smart_folder_drill(&child));
        app.load_folder(child.clone());
        app.open_global_search();
        app.close_global_search();
        assert_eq!(
            app.top_level_grid_view
                .smart_folder()
                .and_then(|state| state.scoped_current()),
            Some(child.as_path()),
            "search close must restore the scoped current folder"
        );

        app.activate_snapshot(crate::snapshot::SnapshotSourceLabel::Mixed);
        assert!(app.is_snapshot_active());
        app.deactivate_snapshot();
        assert_eq!(
            app.top_level_grid_view
                .smart_folder()
                .and_then(|state| state.scoped_current()),
            Some(child.as_path()),
            "snapshot release must restore the scoped current folder"
        );

        app.activate_snapshot(crate::snapshot::SnapshotSourceLabel::Mixed);
        app.load_folder(grandchild.clone());
        app.deactivate_snapshot();
        assert_eq!(
            app.top_level_grid_view
                .smart_folder()
                .and_then(|state| state.scoped_current()),
            Some(grandchild.as_path()),
            "snapshot child navigation must remain in the original smart scope"
        );
        app.load_folder(child.clone());

        app.folder_nav_back_stack = vec![normal.clone()];
        app.folder_nav_back_rating_view_stars = vec![None];
        app.folder_nav_back_smart_folder_states = vec![None];
        let back = app.navigate_folder_history_back().expect("history back");
        assert_eq!(back, normal);
        assert_eq!(
            app.dispatch_synthetic_folder_history_target(&back),
            super::SyntheticFolderHistoryDispatch::NotSynthetic
        );
        app.load_folder(back);
        let forward = app
            .navigate_folder_history_forward()
            .expect("history forward");
        assert_eq!(
            app.dispatch_synthetic_folder_history_target(&forward),
            super::SyntheticFolderHistoryDispatch::NotSynthetic
        );
        app.load_folder(forward);
        assert!(app.top_level_grid_view.smart_folder_session().is_none());
        assert!(app.top_level_grid_view.smart_folder().is_none());
    }

