    app.settings.details_show_video_dimensions = false;
    app.settings.details_show_video_codec = false;
    let items = (0..count)
        .map(|idx| GridItem::Image(PathBuf::from(format!(r"C:\Smart\item-{idx:06}.jpg"))))
        .collect();
