    #[test]
    fn ring_rating_registers_only_one_undo_after_durable_success() {
        let mut app = setup_app();
        let path = app.tmp.path().join("ring.jpg");
        app.items = vec![GridItem::Image(path.clone())];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.visible_indices = vec![0];
        app.selected = Some(0);
        let key = crate::adjustment_db::normalize_path(&path);
        app.rating_db
            .as_ref()
            .unwrap()
            .set_user_rating(&key, 1, app.rating_meta_for_idx(0).as_ref())
            .unwrap();
        app.rating_cache.insert(0, 1);
        let mut picker =
            app.build_ring_picker_state(crate::ring_shortcut::RingShortcutContext::Grid);
        picker
            .dirty_rows
            .push(crate::ring_shortcut::RingPickerRowId::ItemRating);
        picker.item_rating = 4;

        // A successful live preview already writes 4. Finalization writes the
        // same value again but must derive one original->durable transition.
        assert!(app.set_rating_result(0, 4).unwrap());
        let (records, container) = app.finalize_live_picker_ratings(&picker);
        assert_eq!(records.len(), 1);
        assert_eq!(records[0].path_key, key);
        assert_eq!((records[0].before, records[0].after), (1, 4));
        app.commit_live_picker_undo(records, container);

        assert_eq!(app.meta_undo.undo_len(), 1);
        assert_eq!(app.meta_undo.redo_len(), 0);
        assert_eq!(app.rating_db.as_ref().unwrap().get(&key), 4);
    }

    /// リングのコンテナ評価は、**開いた窓のフォルダ**へ書かれる。
    ///
    /// 確定のたびに「いまのフォルダ」を引き直していたので、リングを開いたまま前面の窓が
    /// 変わると、別の窓のフォルダへ★を書き、Undo もそちら宛てに操作した窓の変更前値を
    /// 積んでいた。Undo してもどちらも元へ戻らない (v3.5.0 レビュー N01 / Q01)。
    #[test]
    fn a_ring_container_rating_lands_on_the_folder_it_was_opened_in() {
        let mut app = setup_app();
        let opened_in = app.tmp.path().join("opened_in");
        let moved_to = app.tmp.path().join("moved_to");
        std::fs::create_dir_all(&opened_in).unwrap();
        std::fs::create_dir_all(&moved_to).unwrap();
        let opened_key = crate::adjustment_db::normalize_path(&opened_in);
        let moved_key = crate::adjustment_db::normalize_path(&moved_to);

        // 開いた窓は★2 のフォルダ、後で前面になる窓は★1 のフォルダ。
        app.current_folder = Some(opened_in.clone());
        app.set_current_folder_rating(2).unwrap();
        let mut picker =
            app.build_ring_picker_state(crate::ring_shortcut::RingShortcutContext::Grid);
        picker
            .dirty_rows
            .push(crate::ring_shortcut::RingPickerRowId::ContainerRating);
        picker.container_rating = 4;

        // リングを開いたまま、投影が別のフォルダを指すようになる。
        app.current_folder = Some(moved_to.clone());
        app.current_folder_rating_cache = None;
        app.set_current_folder_rating(1).unwrap();
        let undo_before = app.meta_undo.undo_len();

        let (items, container) = app.finalize_live_picker_ratings(&picker);
        assert!(items.is_empty());
        app.commit_live_picker_undo(items, container);

        let db = app.rating_db.as_ref().unwrap();
        assert_eq!(db.get(&opened_key), 4, "開いた窓のフォルダに書く");
        assert_eq!(db.get(&moved_key), 1, "前面になった窓のフォルダは変えない");
        assert_eq!(
            app.meta_undo.undo_len(),
            undo_before + 1,
            "その変更を取り消せる"
        );

        app.apply_meta_undo();
        let db = app.rating_db.as_ref().unwrap();
        assert_eq!(
            db.get(&opened_key),
            2,
            "Undo は開いた窓のフォルダを元へ戻す"
        );
        assert_eq!(db.get(&moved_key), 1);
    }

    /// パッドが切れたときのリング確定は、**sample の中でやらない**。
    ///
    /// sample は root 投影で走る。リングのフォルダ評価は mount 中の context の保存先へ書く
    /// ので、root のまま確定すると別ウィンドウで変えた評価がメイン側のフォルダへ書かれ、
    /// Undo も別フォルダ宛てに積まれる (v3.5.0 レビュー N01)。物理側の保持解除だけを
    /// sample が行い、確定は通常の配送と同じ場所へ回す。
    #[test]
    fn the_pad_teardown_leaves_the_ring_commit_to_the_normal_dispatch() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        app.settings.gamepad_enabled = true;
        app.ring_picker =
            Some(app.build_ring_picker_state(crate::ring_shortcut::RingShortcutContext::Grid));
        // 保持中の入力も作っておく (物理側は sample で終わること)。
        app.gamepad
            .push_for_test(crate::gamepad::PadEvent::AxisChanged(
                crate::gamepad::PadAxis::LeftX,
                0.9,
            ));
        let _ = app.sample_gamepad_input(&ctx);
        assert!(!app.gamepad_state.is_idle());

        app.settings.gamepad_enabled = false;
        let batch = app.sample_gamepad_input(&ctx);

        assert!(batch.session_ended_for_test(), "区切りを batch で伝える");
        assert!(app.gamepad_state.is_idle(), "物理側は sample が終わらせる");
        assert!(
            app.ring_picker.is_some(),
            "編集の確定は sample の中でやらない"
        );
    }

    /// パッドが切れても、リングで付けた評価は**取り消せる**。
    ///
    /// 評価行はプレビューの時点で DB へ書いており、開いたときの before から Undo を組むのは
    /// 通常の確定処理だけ。切断で overlay を捨てるようにしたとき、その確定を通していな
    /// かったので、書いた評価だけ残って取り消せなくなっていた (v3.5.0 レビュー R12)。
    #[test]
    fn losing_the_pad_still_records_the_undo_for_a_rating_made_in_the_ring() {
        let ctx = egui::Context::default();
        let mut app = setup_app();
        let path = app.tmp.path().join("ring_disconnect.jpg");
        app.items = vec![GridItem::Image(path.clone())];
        app.thumbnails = vec![ThumbnailState::Pending];
        app.visible_indices = vec![0];
        app.selected = Some(0);
        let key = crate::adjustment_db::normalize_path(&path);
        app.rating_db
            .as_ref()
            .unwrap()
            .set_user_rating(&key, 1, app.rating_meta_for_idx(0).as_ref())
            .unwrap();
        app.rating_cache.insert(0, 1);
        app.settings.gamepad_enabled = true;

        let mut picker =
            app.build_ring_picker_state(crate::ring_shortcut::RingShortcutContext::Grid);
        picker
            .dirty_rows
            .push(crate::ring_shortcut::RingPickerRowId::ItemRating);
        picker.item_rating = 4;
        app.ring_picker = Some(picker);
        // プレビューが既に DB へ書いている。
        assert!(app.set_rating_result(0, 4).unwrap());
        assert_eq!(app.meta_undo.undo_len(), 0);

        // パッドが切れる (= 設定 OFF と同じ終端)。sample は物理側だけを終わらせ、
        // リングの確定は通常の配送が所有 context で行う (N01)。
        app.settings.gamepad_enabled = false;
        let batch = app.sample_gamepad_input(&ctx);
        assert!(
            app.ring_picker.is_some(),
            "sample はリングを確定しない (root 投影のため)"
        );
        let _ = app.dispatch_gamepad_batch(&ctx, batch);

        assert!(app.ring_picker.is_none(), "overlay は閉じる");
        assert_eq!(app.rating_db.as_ref().unwrap().get(&key), 4, "評価は残る");
        assert_eq!(app.meta_undo.undo_len(), 1, "その評価を取り消せる");
    }

    #[test]
